window.__tinePages=[{"favorite":false,"journal":false,"slug":"feature-showcase","title":"Feature showcase"},{"favorite":false,"journal":false,"slug":"features-formulas","title":"Features/Formulas"},{"favorite":false,"journal":false,"slug":"features-pdf-annotation","title":"Features/PDF annotation"},{"favorite":false,"journal":false,"slug":"features-plugins","title":"Features/Plugins"},{"favorite":false,"journal":false,"slug":"features-queries","title":"Features/Queries"},{"favorite":false,"journal":false,"slug":"features-quick-capture","title":"Features/Quick capture"},{"favorite":false,"journal":false,"slug":"features-sheets","title":"Features/Sheets"},{"favorite":false,"journal":false,"slug":"features-tips-shortcuts","title":"Features/Tips & shortcuts"},{"favorite":false,"journal":false,"slug":"project-roadmap","title":"Project/Roadmap"},{"favorite":false,"journal":false,"slug":"reference-command-line","title":"Reference/Command line"},{"favorite":false,"journal":false,"slug":"reference-files-external-edits-and-backups","title":"Reference/Files, external edits, and backups"},{"favorite":false,"journal":false,"slug":"reference-journals-tasks-and-scheduling","title":"Reference/Journals, tasks, and scheduling"},{"favorite":false,"journal":false,"slug":"reference-pages-links-references-and-search","title":"Reference/Pages, links, references, and search"},{"favorite":false,"journal":false,"slug":"reference-platforms-and-mobile","title":"Reference/Platforms and mobile"},{"favorite":false,"journal":false,"slug":"reference-tine-query-model","title":"Reference/Tine query model"},{"favorite":false,"journal":false,"slug":"reference-troubleshooting-and-recovery","title":"Reference/Troubleshooting and recovery"},{"favorite":false,"journal":false,"slug":"start-bring-an-existing-graph","title":"Start/Bring an existing graph"},{"favorite":false,"journal":false,"slug":"start-where-things-are","title":"Start/Where things are"},{"favorite":false,"journal":false,"slug":"tine-guide","title":"Tine Guide"},{"favorite":true,"journal":false,"slug":"welcome-to-tine","title":"Welcome to Tine"},{"favorite":false,"journal":false,"slug":"workflows-capture-and-plan-your-day","title":"Workflows/Capture and plan your day"},{"favorite":false,"journal":false,"slug":"workflows-customize-tine-s-look","title":"Workflows/Customize Tine's look"},{"favorite":false,"journal":false,"slug":"workflows-extend-tine","title":"Workflows/Extend Tine"},{"favorite":false,"journal":false,"slug":"workflows-find-and-revisit","title":"Workflows/Find and revisit"},{"favorite":false,"journal":false,"slug":"workflows-keep-context-visible","title":"Workflows/Keep context visible"},{"favorite":false,"journal":false,"slug":"workflows-research-a-document","title":"Workflows/Research a document"},{"favorite":false,"journal":false,"slug":"workflows-structure-repeated-information","title":"Workflows/Structure repeated information"}];
window.__tineBlocks=[{"anchor":"b0","slug":"feature-showcase","text":"This page exercises every Logseq page-level feature Tine knows about, so you can see exactly how each one renders — and where we're still rough. It's ordinary Logseq Markdown; the same file opens unchanged in Logseq.","title":"Feature showcase"},{"anchor":"b1","slug":"feature-showcase","text":"1 — Inline text formatting","title":"Feature showcase"},{"anchor":"b2","slug":"feature-showcase","text":"Bold, italic, also italic, strikethrough, inline code, highlight, and also highlight.","title":"Feature showcase"},{"anchor":"b3","slug":"feature-showcase","text":"Colored text, as in Logseq, with Hiccup: [:span {:style \"color: #d97706\"} \"amber text\"], [:span {:style \"background-color: #fde68a; color: #1f2937\"} \"marker\"], and [:u {:style \"text-decoration-color: #dc2626\"} \"a red underline\"]. In the app only color, background-color and text-decoration-color are read from style.","title":"Feature showcase"},{"anchor":"b4","slug":"feature-showcase","text":"A mix in one line: a bold code span, an italic link, and a struck highlight.","title":"Feature showcase"},{"anchor":"b5","slug":"feature-showcase","text":"Raw inline HTML renders (sanitized to a safe allowlist): , , + , , and / . Scripts and event handlers (onerror=, <script>) are stripped.","title":"Feature showcase"},{"anchor":"b6","slug":"feature-showcase","text":"Parity note: a tag glued to a word — H<sub>2</sub>O, mc<sup>2</sup> — stays literal in Logseq too (mldoc only starts inline HTML at a word boundary), and so do the Markdown carets x^2^ / H~2~O. For a glued subscript, use math: E = mc^2, H_2O.","title":"Feature showcase"},{"anchor":"b7","slug":"feature-showcase","text":"2 — Links & references","title":"Feature showcase"},{"anchor":"b8","slug":"feature-showcase","text":"Page link: Welcome to Tine · tag: #demo · namespaced page: Features/Quick capture.","title":"Feature showcase"},{"anchor":"b9","slug":"feature-showcase","text":"External link: the Logseq docs · bare URL: https://logseq.com · autolinked email: .","title":"Feature showcase"},{"anchor":"b10","slug":"feature-showcase","text":"Labelled page link: read the welcome.","title":"Feature showcase"},{"anchor":"00000000-0000-4000-8000-00000000feed","slug":"feature-showcase","text":"This block is a reference target.","title":"Feature showcase"},{"anchor":"b11","slug":"feature-showcase","text":"Block reference to it: .","title":"Feature showcase"},{"anchor":"b12","slug":"feature-showcase","text":"3 — Headings","title":"Feature showcase"},{"anchor":"b13","slug":"feature-showcase","text":"Heading 1","title":"Feature showcase"},{"anchor":"b14","slug":"feature-showcase","text":"Heading 2","title":"Feature showcase"},{"anchor":"b15","slug":"feature-showcase","text":"Heading 3","title":"Feature showcase"},{"anchor":"b16","slug":"feature-showcase","text":"Heading 4","title":"Feature showcase"},{"anchor":"b17","slug":"feature-showcase","text":"Heading 5","title":"Feature showcase"},{"anchor":"b18","slug":"feature-showcase","text":"Heading 6","title":"Feature showcase"},{"anchor":"b19","slug":"feature-showcase","text":"4 — Lists & nesting","title":"Feature showcase"},{"anchor":"b20","slug":"feature-showcase","text":"Parent bullet","title":"Feature showcase"},{"anchor":"b21","slug":"feature-showcase","text":"Child bullet","title":"Feature showcase"},{"anchor":"b22","slug":"feature-showcase","text":"Grandchild bullet","title":"Feature showcase"},{"anchor":"b23","slug":"feature-showcase","text":"Second child with a formatted tail","title":"Feature showcase"},{"anchor":"b24","slug":"feature-showcase","text":"Numbered list (logseq order):","title":"Feature showcase"},{"anchor":"b25","slug":"feature-showcase","text":"First","title":"Feature showcase"},{"anchor":"b26","slug":"feature-showcase","text":"Second","title":"Feature showcase"},{"anchor":"b27","slug":"feature-showcase","text":"Third","title":"Feature showcase"},{"anchor":"b28","slug":"feature-showcase","text":"5 — Block content types","title":"Feature showcase"},{"anchor":"b29","slug":"feature-showcase","text":"A blockquote. Logseq renders this with a left rule and muted text.","title":"Feature showcase"},{"anchor":"b30","slug":"feature-showcase","text":"Fenced code block with language highlighting:","title":"Feature showcase"},{"anchor":"b31","slug":"feature-showcase","text":"fn main() { let greeting = \"hello from Tine\"; println!(\"{greeting}\"); }","title":"Feature showcase"},{"anchor":"b32","slug":"feature-showcase","text":"A Markdown table:","title":"Feature showcase"},{"anchor":"b33","slug":"feature-showcase","text":"Feature Logseq Tine Tables yes ? Math yes ?","title":"Feature showcase"},{"anchor":"b34","slug":"feature-showcase","text":"Horizontal rule follows:","title":"Feature showcase"},{"anchor":"b36","slug":"feature-showcase","text":"Inline math E = mc^2 and display math:","title":"Feature showcase"},{"anchor":"b37","slug":"feature-showcase","text":"\\int_{-\\infty}^{\\infty} e^{-x^2}\\,dx = \\sqrt{\\pi}","title":"Feature showcase"},{"anchor":"b38","slug":"feature-showcase","text":"An inline image (sized): capture window","title":"Feature showcase"},{"anchor":"b39","slug":"feature-showcase","text":"6 — Tasks, priorities, scheduling","title":"Feature showcase"},{"anchor":"b40","slug":"feature-showcase","text":"A plain task marker","title":"Feature showcase"},{"anchor":"b41","slug":"feature-showcase","text":"A task in progress","title":"Feature showcase"},{"anchor":"b42","slug":"feature-showcase","text":"A finished task","title":"Feature showcase"},{"anchor":"b43","slug":"feature-showcase","text":"Deferred (now-workflow marker)","title":"Feature showcase"},{"anchor":"b44","slug":"feature-showcase","text":"Active (now-workflow marker)","title":"Feature showcase"},{"anchor":"b45","slug":"feature-showcase","text":"Blocked on someone else","title":"Feature showcase"},{"anchor":"b46","slug":"feature-showcase","text":"Abandoned task","title":"Feature showcase"},{"anchor":"b47","slug":"feature-showcase","text":"High-priority task","title":"Feature showcase"},{"anchor":"b48","slug":"feature-showcase","text":"Medium-priority task","title":"Feature showcase"},{"anchor":"b49","slug":"feature-showcase","text":"Low-priority task","title":"Feature showcase"},{"anchor":"b50","slug":"feature-showcase","text":"A scheduled task","title":"Feature showcase"},{"anchor":"b51","slug":"feature-showcase","text":"A task with a deadline","title":"Feature showcase"},{"anchor":"b52","slug":"feature-showcase","text":"A repeating task","title":"Feature showcase"},{"anchor":"b53","slug":"feature-showcase","text":"A task with a logbook (time tracking)","title":"Feature showcase"},{"anchor":"b54","slug":"feature-showcase","text":"7 — Block properties","title":"Feature showcase"},{"anchor":"b55","slug":"feature-showcase","text":"A block carrying its own properties.","title":"Feature showcase"},{"anchor":"b56","slug":"feature-showcase","text":"8 — Embeds","title":"Feature showcase"},{"anchor":"b57","slug":"feature-showcase","text":"Page embed of another demo page:","title":"Feature showcase"},{"anchor":"b59","slug":"feature-showcase","text":"Block embed of the reference target above:","title":"Feature showcase"},{"anchor":"b61","slug":"feature-showcase","text":"9 — Queries","title":"Feature showcase"},{"anchor":"b62","slug":"feature-showcase","text":"Simple query — every TODO task in this graph:","title":"Feature showcase"},{"anchor":"b64","slug":"feature-showcase","text":"Simple query — blocks referencing a page:","title":"Feature showcase"},{"anchor":"b66","slug":"feature-showcase","text":"Query by priority:","title":"Feature showcase"},{"anchor":"b68","slug":"feature-showcase","text":"Compound query (and / or / not) — TODO tasks that are also high priority:","title":"Feature showcase"},{"anchor":"b70","slug":"feature-showcase","text":"10 — Macros, renderers & callouts","title":"Feature showcase"},{"anchor":"b71","slug":"feature-showcase","text":"Video embed:","title":"Feature showcase"},{"anchor":"b72","slug":"feature-showcase","text":"Namespace macro:","title":"Feature showcase"},{"anchor":"b73","slug":"feature-showcase","text":"A NOTE callout:","title":"Feature showcase"},{"anchor":"b74","slug":"feature-showcase","text":"Callouts (admonitions) group a highlighted aside. This is a NOTE.","title":"Feature showcase"},{"anchor":"b75","slug":"feature-showcase","text":"A footnote reference in a sentence.","title":"Feature showcase"},{"anchor":"b76","slug":"feature-showcase","text":"And here is the footnote body.","title":"Feature showcase"},{"anchor":"b77","slug":"feature-showcase","text":"Create one yourself","title":"Feature showcase"},{"anchor":"b78","slug":"feature-showcase","text":"1. Make a scratch page and add one bullet per construct you want to test: links, tables, code, tasks, embeds, queries, and callouts.","title":"Feature showcase"},{"anchor":"b79","slug":"feature-showcase","text":"2. Keep each example small and label it with a heading so it is easy to scan.","title":"Feature showcase"},{"anchor":"b80","slug":"feature-showcase","text":"3. Add page properties such as title:: or icon:: at the top when the whole page needs metadata.","title":"Feature showcase"},{"anchor":"b81","slug":"feature-showcase","text":"4. What you should see: each example renders live while staying ordinary Logseq Markdown.","title":"Feature showcase"},{"anchor":"b0","slug":"features-formulas","text":"Formulas","title":"Features/Formulas"},{"anchor":"b1","slug":"features-formulas","text":"A formula column is an extra column whose value Tine works out for you from the other columns in the row. You never type the result — Tine recomputes it live, shows it on screen, and never writes it back onto your bullets. Open the same file in Logseq and you just see ordinary bullets with a harmless tine.formula.* property.","title":"Features/Formulas"},{"anchor":"b2","slug":"features-formulas","text":"A formula in action","title":"Features/Formulas"},{"anchor":"b3","slug":"features-formulas","text":"Sketch the outline","title":"Features/Formulas"},{"anchor":"b4","slug":"features-formulas","text":"Write the first draft","title":"Features/Formulas"},{"anchor":"b5","slug":"features-formulas","text":"The plan column is a formula. Tine reads hours from each row and shows focus block or quick task — you never type it, and it updates the moment hours changes.","title":"Features/Formulas"},{"anchor":"b6","slug":"features-formulas","text":"Add one yourself","title":"Features/Formulas"},{"anchor":"b7","slug":"features-formulas","text":"1. Make a table (see Features/Sheets) with at least one field to compute from, for example a hours=number column.","title":"Features/Formulas"},{"anchor":"b8","slug":"features-formulas","text":"2. Right-click a table column header — or right-click the table body / open its ⋮ menu — and choose Add formula…. Give it a short lowercase name like plan.","title":"Features/Formulas"},{"anchor":"b9","slug":"features-formulas","text":"3. The visual builder opens. You build the value by clicking faces — no syntax to memorize. Press Save and a read-only column appears, filling in live.","title":"Features/Formulas"},{"anchor":"b10","slug":"features-formulas","text":"4. To change it later, right-click the formula column and choose Edit formula….","title":"Features/Formulas"},{"anchor":"b11","slug":"features-formulas","text":"The building blocks","title":"Features/Formulas"},{"anchor":"b12","slug":"features-formulas","text":"Value face — click it to open a picker with these sections:","title":"Features/Formulas"},{"anchor":"b13","slug":"features-formulas","text":"Field — one of your own columns (or type a custom field name).","title":"Features/Formulas"},{"anchor":"b14","slug":"features-formulas","text":"Formula — another formula column on the same table, shown as formula.<name>.","title":"Features/Formulas"},{"anchor":"b15","slug":"features-formulas","text":"Literal — a fixed number, a bit of text, or True / False / Empty.","title":"Features/Formulas"},{"anchor":"b16","slug":"features-formulas","text":"Function — if condition, is empty, now, today.","title":"Features/Formulas"},{"anchor":"b17","slug":"features-formulas","text":"Transform — tweaks like lowercase, trim, round, year, format date, length.","title":"Features/Formulas"},{"anchor":"b18","slug":"features-formulas","text":"IF / THEN / ELSE — pick the if condition function on any value to branch: IF a condition THEN one value ELSE another value.","title":"Features/Formulas"},{"anchor":"b19","slug":"features-formulas","text":"Condition — compare two values with an operator (=, ≠, <, ≤, >, ≥), and join several with AND / OR.","title":"Features/Formulas"},{"anchor":"b20","slug":"features-formulas","text":"</> raw — type it directly","title":"Features/Formulas"},{"anchor":"b21","slug":"features-formulas","text":"The </> raw button at the top-right of the editor switches from clickable faces to a plain text box, where you can type the expression yourself — for example hours * 2 or if(hours > 3, \"focus block\", \"quick task\"). The chips below insert your fields, other formulas, and built-in functions at the cursor. Flip Builder back on whenever the text is something the faces can show again.","title":"Features/Formulas"},{"anchor":"b22","slug":"features-formulas","text":"Honest limits","title":"Features/Formulas"},{"anchor":"b23","slug":"features-formulas","text":"The visual builder handles one level: a single IF/THEN/ELSE, simple comparisons, and a value that is at most one arithmetic step of two simple values (like hours * 2).","title":"Features/Formulas"},{"anchor":"b24","slug":"features-formulas","text":"Anything more nested — a formula inside a THEN branch, or arithmetic of arithmetic like (hours + extra) * 2 — shows up as a small raw box instead of pretty faces. Use </> raw to type those directly; they still evaluate exactly the same, they just do not get a visual face.","title":"Features/Formulas"},{"anchor":"b25","slug":"features-formulas","text":"Formula values are read-only and are never saved onto your rows, so they always reflect the current data and round-trip cleanly back to Logseq.","title":"Features/Formulas"},{"anchor":"b26","slug":"features-formulas","text":"Create one yourself — formula","title":"Features/Formulas"},{"anchor":"b27","slug":"features-formulas","text":"1. Start from a table with a numeric or enum field.","title":"Features/Formulas"},{"anchor":"b28","slug":"features-formulas","text":"2. Right-click the column header and choose Add/Edit formula.","title":"Features/Formulas"},{"anchor":"b29","slug":"features-formulas","text":"3. Build the value from the faces — pick a field, add a comparison, wrap it in IF / THEN / ELSE.","title":"Features/Formulas"},{"anchor":"b30","slug":"features-formulas","text":"4. Use the </> raw toggle when you would rather type the expression, such as hours * 2.","title":"Features/Formulas"},{"anchor":"b31","slug":"features-formulas","text":"5. What you should see: a read-only computed column whose values evaluate live and are never written onto the rows.","title":"Features/Formulas"},{"anchor":"b0","slug":"features-pdf-annotation","text":"PDF annotation","title":"Features/PDF annotation"},{"anchor":"b1","slug":"features-pdf-annotation","text":"Open a PDF that lives in your graph's assets/ (or drop one in). On desktop it opens as a tab in a companion pane, keeping your notes visible. On a phone it opens in the same one-pane history.","title":"Features/PDF annotation"},{"anchor":"b2","slug":"features-pdf-annotation","text":"Opening and reading a PDF changes no graph files. Its highlight sidecar and notes page are created when you first highlight or annotate; existing highlights and notes stay available.","title":"Features/PDF annotation"},{"anchor":"b3","slug":"features-pdf-annotation","text":"Select text in the PDF to highlight it; click a highlight again to change its color.","title":"Features/PDF annotation"},{"anchor":"b4","slug":"features-pdf-annotation","text":"Hold Shift while dragging a rectangle on Linux or Windows, or Command on macOS, then choose a color to clip a figure or equation as an image highlight. Dismissing the color chooser writes nothing.","title":"Features/PDF annotation"},{"anchor":"b5","slug":"features-pdf-annotation","text":"Use the reader toolbar to choose a persistent Light, Warm, or Dark page theme, and open Outline to navigate a PDF's nested table of contents.","title":"Features/PDF annotation"},{"anchor":"b6","slug":"features-pdf-annotation","text":"Zoom, find text, and jump to a page from the toolbar. Your page and zoom are restored when you reopen the PDF. At high zoom, only visible page regions are rendered sharply.","title":"Features/PDF annotation"},{"anchor":"b7","slug":"features-pdf-annotation","text":"On a phone, select text or long-press a highlight to open its annotation actions.","title":"Features/PDF annotation"},{"anchor":"b8","slug":"features-pdf-annotation","text":"Every highlight becomes a block on a notes page named after the PDF, so you can write underneath it, link it, and reference it like any other bullet — and each note jumps straight back to its spot in the document.","title":"Features/PDF annotation"},{"anchor":"b9","slug":"features-pdf-annotation","text":"If the highlight file changes outside Tine, choose Keep mine to merge your edits or Use disk version to discard them. If the disk highlight file cannot be read, Discard my changes asks for confirmation, clears only your local highlight edits, and leaves the disk file untouched; an unused local area image may remain.","title":"Features/PDF annotation"},{"anchor":"b10","slug":"features-pdf-annotation","text":"If an area image cannot be cleaned up after a highlight saves, choose Retry cleanup in the PDF viewer. Closing or switching graphs waits until that cleanup succeeds.","title":"Features/PDF annotation"},{"anchor":"b11","slug":"features-pdf-annotation","text":"It's how you turn a paper into linked, searchable notes without ever leaving Tine.","title":"Features/PDF annotation"},{"anchor":"b12","slug":"features-pdf-annotation","text":"For the end-to-end path from dropping a PDF in to quoting its passages, see Workflows/Research a document.","title":"Features/PDF annotation"},{"anchor":"b13","slug":"features-pdf-annotation","text":"Create one yourself","title":"Features/PDF annotation"},{"anchor":"b14","slug":"features-pdf-annotation","text":"1. Put a PDF in your graph's assets/ folder, or drop it into a page.","title":"Features/PDF annotation"},{"anchor":"b15","slug":"features-pdf-annotation","text":"2. Open the PDF from its asset link. On desktop, its tab can be moved into another pane or split. On a phone, use Back to return to the page with the link.","title":"Features/PDF annotation"},{"anchor":"b16","slug":"features-pdf-annotation","text":"3. Select text to create a highlight, or hold Shift (Linux/Windows) or Command (macOS) and drag a rectangle for an area highlight, then choose its color.","title":"Features/PDF annotation"},{"anchor":"b17","slug":"features-pdf-annotation","text":"4. Write notes under the generated highlight blocks.","title":"Features/PDF annotation"},{"anchor":"b18","slug":"features-pdf-annotation","text":"5. What you should see: each highlight is a normal block that links back to the exact PDF location.","title":"Features/PDF annotation"},{"anchor":"b0","slug":"features-plugins","text":"Plugins","title":"Features/Plugins"},{"anchor":"b1","slug":"features-plugins","text":"Tine plugins are capability-limited WebAssembly guests. They are not Logseq or Obsidian plugins and cannot use those apps' plugin APIs.","title":"Features/Plugins"},{"anchor":"b2","slug":"features-plugins","text":"Plugins cannot directly access the DOM, Tauri, files, processes, the network, or arbitrary graph paths. Tine owns the commands, slash actions, decorations, settings controls, and any narrowly authorized block edit that a plugin can request.","title":"Features/Plugins"},{"anchor":"b3","slug":"features-plugins","text":"Workflows/Extend Tine walks the hands-on install → review → enable → disable path; this page remains the detailed reference.","title":"Features/Plugins"},{"anchor":"b4","slug":"features-plugins","text":"Browse and install","title":"Features/Plugins"},{"anchor":"b5","slug":"features-plugins","text":"Open Settings → Plugins → Browse for the signed community catalogue. Each entry shows its source, supported platforms, declared capabilities, publication review, and a digest-verified safety report.","title":"Features/Plugins"},{"anchor":"b6","slug":"features-plugins","text":"Choose Install on a compatible entry. Local developers can instead choose Install a local package and select its manifest.json and .wasm together.","title":"Features/Plugins"},{"anchor":"b7","slug":"features-plugins","text":"Tine supports plugin API 0.2 and 0.3. API 0.3 adds the color setting type for host-rendered color choices. The catalogue offers only versions your Tine can run, so an older Tine keeps the last compatible version of a plugin.","title":"Features/Plugins"},{"anchor":"b8","slug":"features-plugins","text":"Every version is installed disabled. Open Installed, review its identity and capabilities, then enable it explicitly.","title":"Features/Plugins"},{"anchor":"b9","slug":"features-plugins","text":"Control a plugin","title":"Features/Plugins"},{"anchor":"b10","slug":"features-plugins","text":"Open a plugin's Details or Settings page to change its host-rendered options. Plugins receive only validated scalar values; they do not draw their own settings UI.","title":"Features/Plugins"},{"anchor":"b11","slug":"features-plugins","text":"Disable a plugin at any time without removing it. Uninstall removes only that app-local package version and never changes your graph or notes.","title":"Features/Plugins"},{"anchor":"b12","slug":"features-plugins","text":"Signed revocations are checked before saved plugins start. A revoked version stays disabled even when the live catalogue is temporarily unavailable.","title":"Features/Plugins"},{"anchor":"b13","slug":"features-plugins","text":"Bullet threading highlights the focused block's continuous ancestor path even with All nested outlines selected. Its Settings offer line thickness from 0–10 px (0 hides the lines), a custom color (empty uses the current theme accent), and optional Color by hierarchy level, off by default. Disabling the plugin restores normal guides without changing your notes.","title":"Features/Plugins"},{"anchor":"b14","slug":"features-plugins","text":"Active ancestry only emphasizes the edited block's connectors in the theme accent color by default, following the path through its ancestors.","title":"Features/Plugins"},{"anchor":"b15","slug":"features-plugins","text":"Themes","title":"Features/Plugins"},{"anchor":"b16","slug":"features-plugins","text":"Declarative themes live under Settings → Appearance → Themes, separately from executable plugins. They contain validated colors and may select bounded Tine-owned presentation styles rather than running code: editorial reading type, a larger journal header, or a compact Today task count. Style (typography, journal headings and other presentation) and Color scheme (Default, Nord, Solarized, Gruvbox, Soft, or an installed package's colors) are chosen independently, so you can keep one package's style with another palette. They contain no scripts, selectors, imports, downloaded fonts, or remote assets, and no theme ever reads or writes your graph.","title":"Features/Plugins"},{"anchor":"b17","slug":"features-plugins","text":"A Today summary, when selected, is rendered by Tine from the journal page already on screen: it counts open task markers there and calls the DOING, NOW, STARTED, and IN-PROGRESS subset “in progress.” The theme receives neither those tasks nor a query interface.","title":"Features/Plugins"},{"anchor":"b18","slug":"features-plugins","text":"A selected theme remains subordinate to your graph's logseq/custom.css, so your own CSS still wins; Workflows/Customize Tine's look explains that file and the stable --tine-* tokens.","title":"Features/Plugins"},{"anchor":"b19","slug":"features-plugins","text":"Create one yourself","title":"Features/Plugins"},{"anchor":"b20","slug":"features-plugins","text":"1. Open Settings → Plugins → Browse.","title":"Features/Plugins"},{"anchor":"b21","slug":"features-plugins","text":"2. Inspect a plugin's capabilities and safety report, then install it.","title":"Features/Plugins"},{"anchor":"b22","slug":"features-plugins","text":"A command or slash action reads only the block you run it on. A decoration sees the text of visible blocks only if the plugin declares graph.read.visible.","title":"Features/Plugins"},{"anchor":"b23","slug":"features-plugins","text":"3. Switch to Installed, open its details, and enable it.","title":"Features/Plugins"},{"anchor":"b24","slug":"features-plugins","text":"4. What you should see: only the host-owned command, slash action, or decoration that the plugin declared; disabling it removes that behavior while leaving your graph readable.","title":"Features/Plugins"},{"anchor":"b25","slug":"features-plugins","text":"For authoring, packaging, API versioning, and registry submission, see the developer guide.","title":"Features/Plugins"},{"anchor":"b0","slug":"features-queries","text":"Queries","title":"Features/Queries"},{"anchor":"b1","slug":"features-queries","text":"A query block is a live list of every block (or page) in your graph that matches a filter. Write it once with {{query …}}; Tine keeps the results current as you edit, and the file stays an ordinary Logseq query block. Where an answer can differ from Logseq's, Reference/Tine query model says how and why.","title":"Features/Queries"},{"anchor":"b2","slug":"features-queries","text":"A query in action","title":"Features/Queries"},{"anchor":"b3","slug":"features-queries","text":"Every open task in this graph:","title":"Features/Queries"},{"anchor":"b5","slug":"features-queries","text":"Create one yourself","title":"Features/Queries"},{"anchor":"b6","slug":"features-queries","text":"1. Type /query and choose Query, or write {{query (task TODO)}} yourself. The slash command opens the query sheet on its empty condition list; press + Add condition to choose the first field.","title":"Features/Queries"},{"anchor":"b7","slug":"features-queries","text":"2. At rest a query block shows its title, result count and results. Click the title to rename it. Fold the query block's bullet to hide its results, as in Logseq. Hover over or focus the query to reveal ⋯; on touch screens the menu is visible. Open ⋯ → Edit for the inline builder, View for display choices, or Edit as text for TQL. Advanced datalog keeps its original block-text editor.","title":"Features/Queries"},{"anchor":"b8","slug":"features-queries","text":"3. The sheet says what the query finds — Find blocks ▾ where … — and shows one row per condition: a handle to drag it (or move it with the arrow keys), a box to select it, the field, operator and value, a switch that turns it off without removing it, a ⋮ for the rest, and an × to remove it. + Add condition adds one.","title":"Features/Queries"},{"anchor":"b9","slug":"features-queries","text":"4. Tick two or more rows in the same list and press Group selected ▾ to make them one All of, Any of or None of group. A group's ⋮ Ungroup puts its rows back.","title":"Features/Queries"},{"anchor":"b10","slug":"features-queries","text":"Drag a row's handle onto another group to move that condition into it; a group left with one condition dissolves into the list around it. The Task field has an Any status choice (every task marker), and In a journal page keeps only blocks that sit on a journal day. Scheduled and Deadline ranges read in plain words (Scheduled: next 7 days), and nothing the builder wrote is labelled advanced.","title":"Features/Queries"},{"anchor":"b11","slug":"features-queries","text":"While the inline builder is open, the real results below it follow every change you make, before you save. The builder stays in the outline, and only the latest answer is shown. A new empty query says Add a condition to see results. instead of listing every page. Removing the last condition returns to that same empty state, even if a sort remains.","title":"Features/Queries"},{"anchor":"b12","slug":"features-queries","text":"5. Press Done or Escape to close the inline editor; the title, count and results remain. The results show as blocks grouped by page, or as pages when the query finds pages; choose ⋯ → View → Search, List, Table or Board to change how they are shown — the matches stay the same. Matches that share a parent show that parent's breadcrumb once. A block that matches directly under another block that also matches is not a result of its own, as in Logseq: it shows inside its parent (the List draws the parent's children), and the count, Table and Board list the parent only; a match under a block that does not match is its own result. Search and List page results show the page title; press the pencil beside a result to edit its properties in the page's property panel (the change is written to the page's file, and the row updates). In Find blocks ▾ choose Pages and blocks to see both answers of the same conditions, Pages above Blocks; the builder then reads Find pages and blocks, the Blocks section follows the List, Table or Board you picked, and a section that a Sample cut short says More pages match than are shown (or blocks) (stored as tine.result-kinds:: pages-and-blocks; Logseq ignores that property and reads the query as before).","title":"Features/Queries"},{"anchor":"b13","slug":"features-queries","text":"Query text","title":"Features/Queries"},{"anchor":"b14","slug":"features-queries","text":"Renaming keeps the current results visible. An unsaved text draft leaves the results unchanged until Save query text. Saving keeps focus in the editor; Escape or Done closes it and returns focus to the query's ⋯ menu.","title":"Features/Queries"},{"anchor":"b15","slug":"features-queries","text":"Open search tab in Ctrl+K search for a friendly search tab with separate Pages and Blocks sections. An alias result opens its owner page. Choose Pages match to search names and aliases, containing block text, or both; saving that search writes tine.page-match-scope:: content or both beside the ordinary query block.","title":"Features/Queries"},{"anchor":"b16","slug":"features-queries","text":"Use each section's Display control independently. Sort orders all matching Pages or Blocks before that section's limit; Sample keeps the first N of that order, separately for each section. A Pages board groups adjacent results by its chosen field while keeping their sort order. A Pages table can show authored page properties as columns while Blocks use a different view. Save page stores the choices as tine.page-* and tine.block-* query block properties.","title":"Features/Queries"},{"anchor":"b17","slug":"features-queries","text":"The query text is hidden by default: press Edit as text in ⋯ to open the query text box: the same query the rows show, written in Tine's text query language (@block or @page, then conditions joined with and, or, not). Type in it and Tine re-reads it as you go; press Save query text to make it the block's query.","title":"Features/Queries"},{"anchor":"b18","slug":"features-queries","text":"When Tine cannot read the text it names the problem, and a Show me button selects the part of the text it points at when it knows where that is.","title":"Features/Queries"},{"anchor":"b19","slug":"features-queries","text":"A {{tine-query …}} block holds this language directly and runs like any other query block.","title":"Features/Queries"},{"anchor":"b20","slug":"features-queries","text":"When a query needs Tine features","title":"Features/Queries"},{"anchor":"b21","slug":"features-queries","text":"Some queries have no {{query}} spelling — scheduled/deadline date windows, grouping, column totals, typed comparisons. When you save one, Tine renames the block's macro from query to tine-query and moves the view choices into tine.* properties on the same block.","title":"Features/Queries"},{"anchor":"b22","slug":"features-queries","text":"For a scheduled window, use {{tine-query @block scheduled between today and '+7d'}}; use deadline for a deadline window. Logseq ignores scheduled/deadline date windows in {{query}}, so Tine shows a cue and refuses to run those blocks as written. Click Convert to keep the same date-window meaning in {{tine-query …}}; the change can be undone.","title":"Features/Queries"},{"anchor":"b23","slug":"features-queries","text":"A notice under the query says so: This query now uses Tine features Logseq can't read. Undo that change puts the block back to exactly the bytes it had; Keep it dismisses the notice.","title":"Features/Queries"},{"anchor":"b24","slug":"features-queries","text":"Simple queries","title":"Features/Queries"},{"anchor":"b25","slug":"features-queries","text":"The simple query language is Logseq's. Combine filters with (and …), (or …) and (not …):","title":"Features/Queries"},{"anchor":"b26","slug":"features-queries","text":"(task TODO DOING) — blocks with one of these task markers; (priority A) — by priority.","title":"Features/Queries"},{"anchor":"b27","slug":"features-queries","text":"(task) with no markers and (priority) with no levels add no condition, exactly as in OG Logseq: (and (task) [[x]]) finds what [[x]] finds, and a query with no other condition shows nothing. A note on the query says so and offers Open tasks (every block that has a task marker except DONE, CANCELED, or CANCELLED, so WAITING, STARTED and IN-PROGRESS count), Any task (every task marker), or A, B or C; each rewrites the clause to an explicit list and saves the block like any query edit. The visual builder always writes explicit marker lists such as (task TODO) or (task DONE), which keep their usual meaning.","title":"Features/Queries"},{"anchor":"b28","slug":"features-queries","text":"[[Page]], (page-ref Page), #tag — blocks that reference a page.","title":"Features/Queries"},{"anchor":"b29","slug":"features-queries","text":"(page \"Page\") — blocks on a page; (namespace Project) — blocks on the pages directly under a namespace (Project/Alpha, but not Project/Alpha/Beta; an advanced query's namespace clause matches every depth).","title":"Features/Queries"},{"anchor":"b30","slug":"features-queries","text":"(property status active), (page-property type book), (page-tags public) — by block or page properties and tags. (all-page-tags) lists the pages that some page uses as a tag. A page-level filter returns pages, not blocks.","title":"Features/Queries"},{"anchor":"b31","slug":"features-queries","text":"(between -7d today) — journal blocks in a date range. Dates are today, yesterday, tomorrow, 2026-01-31, a journal title like [[Jan 31st, 2026]], or an offset like -7d, +2w, -1m, +1y (lowercase units, at most 10,000 years).","title":"Features/Queries"},{"anchor":"b32","slug":"features-queries","text":"(between created-at -7d now) — blocks whose created-at:: (or created_at::) property falls in the range; last-modified-at works the same. The first bound is included and the second is not, and the two may be given in either order. Besides the date forms, these bounds also take now (the current moment) and offsets in hours h and minutes n such as +36h or -90n; day-based offsets and h/n count from the start of today, not from the current time. A bound that is not one of these makes the whole query invalid.","title":"Features/Queries"},{"anchor":"b33","slug":"features-queries","text":"(sort-by priority asc), (sample 10) — order the results (by priority, page, scheduled, deadline or any property; like Logseq, the order is descending unless you write asc), or keep a random N of the matches (chosen before sorting, so each run can show a different few). A query made only of these directives, with no condition, shows nothing. Without a sort, results are grouped by page: journal days newest first, then the other pages by name.","title":"Features/Queries"},{"anchor":"b34","slug":"features-queries","text":"A bare word or quoted text finds the raw block text, including property lines and drawers. Query text is case-sensitive and accent-sensitive, like Logseq: Alpha does not find alpha, and cafe does not find café. TQL content match uses search syntax with this same exact matching; content like is exact too. Ctrl+K, search tabs and in-page Find still ignore case and remove accents unless :feature/enable-search-remove-accents? false is configured.","title":"Features/Queries"},{"anchor":"b35","slug":"features-queries","text":"Property values ignore case: (property status Done) also finds status:: done. Commas split values only for tags, alias/aliases, and keys in :property/separated-by-commas in logseq/config.edn. Other values stay whole: (property list \"Foo, Bar\") finds list:: Foo, Bar, while (property list Foo) does not.","title":"Features/Queries"},{"anchor":"b36","slug":"features-queries","text":"Explicit #tags and [[page references]] are separate values even without commas, in page and block properties: tags:: #eng #exec #founder matches (page-tags eng) and (property tags eng). #[[multi word]] is one tag. In tags:: #a plain text #b, the plain text is also a value; in a custom property only the explicit references become values. Quoting the whole value keeps it literal.","title":"Features/Queries"},{"anchor":"b37","slug":"features-queries","text":"A block property on the query block itself can set the view: tine.sort:: priority desc and tine.sample:: 10 win over the same directive in the query text.","title":"Features/Queries"},{"anchor":"b38","slug":"features-queries","text":"Display and property types","title":"Features/Queries"},{"anchor":"b39","slug":"features-queries","text":"Open ⋯ → View to choose Search, List, Table or Board; add ordered sort fields and table columns, choose grouping, add count/sum/average summaries, or set a sample limit. The column picker offers only columns found in the current results, starts with the visible default columns checked and offers Select all and Select none. A saved column choice stays intact when that column disappears from the results; its checkbox returns when the column appears again. Choosing Page shows each block's owning page. The controls save on the query block as existing tine.* properties; tine.fields:: remains the table's schema and is not changed by a column choice.","title":"Features/Queries"},{"anchor":"b40","slug":"features-queries","text":"Scheduled and Deadline conditions offer >, >=, =, < and <=, with today, yesterday, tomorrow or today±N days (for example +5d). The Rust query engine decides which results match.","title":"Features/Queries"},{"anchor":"b41","slug":"features-queries","text":"Task checkboxes in Search, Table and Board edit the original block through its ordinary save path. Click a table title or board card to open its source. Board columns scroll when they cannot fit.","title":"Features/Queries"},{"anchor":"b42","slug":"features-queries","text":"In List view, ⋯ → Collapse all / Expand all is one toggle that folds the result trees together. This writes the source blocks' ordinary collapsed:: property and can be undone. ⋯ → Search opens the same query in a Search tab.","title":"Features/Queries"},{"anchor":"b43","slug":"features-queries","text":"Copy or revisit results","title":"Features/Queries"},{"anchor":"b44","slug":"features-queries","text":"Drag a List result's bullet to move that source block into your outline. Hold Alt when dropping one block to insert a block reference instead, leaving the source in place. The reference is inserted only after the source's ID has been saved. The same Alt gesture works on an ordinary outline bullet; a selection of several blocks still moves together.","title":"Features/Queries"},{"anchor":"b45","slug":"features-queries","text":"⋯ → Copy results opens the same Copy / export as… dialog as an outline selection, with Text, OPML and HTML options. Each result tree sits under its page title; journals use their date titles, and descendants keep their hierarchy. A descendant already inside a selected parent is copied once.","title":"Features/Queries"},{"anchor":"b46","slug":"features-queries","text":"In a Search tab, press Select results, tick the results you want (or Select all / Select none), then Copy results for the same dialog and format. Selection actions stay above the result rows, which keep their page or block labels. Press Select results again or Done to leave selection mode.","title":"Features/Queries"},{"anchor":"b47","slug":"features-queries","text":"External changes and structural edits refresh the query after pending changes settle. Until then, old results stay read-only. A task click, copy or bulk fold refuses the whole action when its selected results are no longer current; a notice asks you to run the query again. A block with a unique authored id:: can still be resolved by that identity.","title":"Features/Queries"},{"anchor":"b48","slug":"features-queries","text":"A saved Scheduled or Deadline comparison offers >, <, =, ≥ and ≤ in its operator menu, plus negation of the current comparison. Is not set tests an absent date in the date editor; it never means a negated date comparison.","title":"Features/Queries"},{"anchor":"b49","slug":"features-queries","text":"⋯ → Open in Search opens the query in a Search tab. View choices travel with it; results still come from the Rust engine.","title":"Features/Queries"},{"anchor":"b50","slug":"features-queries","text":"The full All pages view has a sortable Backlinks column: the number of referring blocks computed by the backend. All pages, Search and query blocks remain separate views.","title":"Features/Queries"},{"anchor":"b51","slug":"features-queries","text":"Search and List page results show the page title; press the pencil beside a result to open its full properties. Table columns stay in the Table view.","title":"Features/Queries"},{"anchor":"b52","slug":"features-queries","text":"Table titles are always shown and are listed as such in the column picker. Select all / Select none changes the other fields, preserving the meaning of existing column settings.","title":"Features/Queries"},{"anchor":"b53","slug":"features-queries","text":"A grouped summary says Grouped by and names the field. Choose ⋯ → View → Group by → None to remove grouping. When every result lacks that field, Tine shows the overall totals instead of a table containing only (none). Opening View or choosing a summary does not choose a grouping field.","title":"Features/Queries"},{"anchor":"b54","slug":"features-queries","text":"A query table's footer summarizes the query's complete sample, even when a table filter hides some rows. Sample limits the query before its totals are computed. Click a property total to choose Count, Sum, Average, or None; the choice is saved with the query's Display settings. Built-in columns such as Page and State have no property total. If statistics are unavailable, Tine leaves the total blank or shows why it is unavailable.","title":"Features/Queries"},{"anchor":"b55","slug":"features-queries","text":"A Logseq query written with {:table-view? true}, query-table:: true on its block, or a trailing table (for example {{query (task TODO) table}}) keeps its own table: the block's query-properties:: [:block :page :status] chooses the columns and their order, and query-sort-by:: status with query-sort-desc:: false sets the starting sort (descending unless you write false). Clicking a column heading re-sorts for as long as the page is open without changing the file. The List/Table toggle saves only tine.view and never adds query-table; an explicit tine.view:: list overrides an imported table choice.","title":"Features/Queries"},{"anchor":"b56","slug":"features-queries","text":"The condition picker lists properties found in this graph with their observed type and the number of blocks or pages that carry them. A key found on both blocks and pages has separate choices for those scopes. You can type a key that has not appeared yet.","title":"Features/Queries"},{"anchor":"b57","slug":"features-queries","text":"Beside a property condition, declare type… writes tine.type:: number, date, checkbox, ref or text on the page named for that property key. Select list of for multiple values, or remove the declaration. The badge distinguishes an observed type from a declared one and shows mismatches against a declaration.","title":"Features/Queries"},{"anchor":"b58","slug":"features-queries","text":"Advanced (datalog) queries","title":"Features/Queries"},{"anchor":"b59","slug":"features-queries","text":"{{query {:query [:find (pull ?b [*]) :where …]}}} and #+BEGIN_QUERY blocks run a supported subset of Logseq's datalog: task markers, priority, page references, properties, page, namespace, page tags, scheduled/deadline and journal date ranges.","title":"Features/Queries"},{"anchor":"b60","slug":"features-queries","text":"A query runs only if Tine can read every clause of it. If any clause is outside the supported subset (a :result-transform other than Logseq's default priority sort, an unsupported input, a rule Tine does not know), the whole query is refused: a notice names the clauses Tine could not run and shows no results, because an answer to part of a query would be wrong. String page/tag inputs and numeric or relative date windows are supported; Reference/Tine query model lists the exact shapes.","title":"Features/Queries"},{"anchor":"b61","slug":"features-queries","text":":inputs [:current-page] binds the page open in the focused pane, like Logseq: if no page is open it uses your configured home page, then today's journal. It is not the page the query block sits on.","title":"Features/Queries"},{"anchor":"b62","slug":"features-queries","text":"When a query shows nothing","title":"Features/Queries"},{"anchor":"b63","slug":"features-queries","text":"Query source could not be parsed means the macro itself is damaged. Edit the block text to repair it; the visual builder becomes available once the source is readable. A query with a title such as {{query (page-property tags gptpro) {:title \"gptpro\"}}} needs all three final braces: one closes the title options and two close the macro.","title":"Features/Queries"},{"anchor":"b64","slug":"features-queries","text":"If Tine cannot read part of a query, the block says so — Tine didn't understand part of this query, so it returned no results — followed by what it could not read. An empty list without that message means the query is valid and nothing matches yet.","title":"Features/Queries"},{"anchor":"b65","slug":"features-queries","text":"An empty result offers why empty?: a table of the query's top-level conditions with how many rows each matches alone and how many the query would match without it, so the condition that emptied it stands out.","title":"Features/Queries"},{"anchor":"b66","slug":"features-queries","text":"A query that would return more than 20,000 rows (or 32 MiB) is refused with a message instead of being cut short. Narrow it, or add (sample N).","title":"Features/Queries"},{"anchor":"b67","slug":"features-queries","text":"Publish a query","title":"Features/Queries"},{"anchor":"b68","slug":"features-queries","text":"Use ⋯ → Export… on a query. Review the complete pages selected by the result, then choose an external folder. Tine creates a new named site there, with a read-only browser view and static HTML fallback. A block result publishes its whole owner page, so review those pages before continuing. The built-in Scheduled & Deadline section has no Export button.","title":"Features/Queries"},{"anchor":"b69","slug":"features-queries","text":"In Settings → Graph → Publish live site, choose an external folder to publish pages marked public:: true. Include all pages is an explicit choice for a graph meant to be public; it still leaves out pages marked public:: false. The exported site can be served as ordinary static files.","title":"Features/Queries"},{"anchor":"b0","slug":"features-quick-capture","text":"Global quick-capture","title":"Features/Quick capture"},{"anchor":"b1","slug":"features-quick-capture","text":"A passing thought shouldn't make you switch windows. Bind a desktop shortcut and a small always-on-top capture box pops up over any app — with the full Tine editor — and files what you type straight into your graph. Tine doesn't even need to be focused.","title":"Features/Quick capture"},{"anchor":"b2","slug":"features-quick-capture","text":"What it looks like","title":"Features/Quick capture"},{"anchor":"b3","slug":"features-quick-capture","text":"The quick-capture window — note the optional page-title field at the top","title":"Features/Quick capture"},{"anchor":"b4","slug":"features-quick-capture","text":"Set it up (Linux, one time)","title":"Features/Quick capture"},{"anchor":"b5","slug":"features-quick-capture","text":"Tine listens for a launch with the --capture flag, so bind a global keyboard shortcut in your desktop environment to run tine --capture:","title":"Features/Quick capture"},{"anchor":"b6","slug":"features-quick-capture","text":"GNOME — Settings → Keyboard → View and Customize Shortcuts → Custom Shortcuts → +. Command: tine --capture. Pick a key like Super+N.","title":"Features/Quick capture"},{"anchor":"b7","slug":"features-quick-capture","text":"KDE — System Settings → Shortcuts → Add → Command/URL. Command: tine --capture.","title":"Features/Quick capture"},{"anchor":"b8","slug":"features-quick-capture","text":"Other desktops — add a custom keyboard shortcut that runs tine --capture. Use the binary's full path if it isn't on your PATH.","title":"Features/Quick capture"},{"anchor":"b9","slug":"features-quick-capture","text":"Now press your shortcut from anywhere — the box appears, you type, and it's saved.","title":"Features/Quick capture"},{"anchor":"b10","slug":"features-quick-capture","text":"Where your capture goes","title":"Features/Quick capture"},{"anchor":"b11","slug":"features-quick-capture","text":"Leave the title empty → the text is appended to today's journal. This is the fast path: hotkey, type, done.","title":"Features/Quick capture"},{"anchor":"b12","slug":"features-quick-capture","text":"Type a page title (the field at the top of the window) → it's filed to that page instead, created if it doesn't exist yet. Perfect for \"add this to my Reading notes\" without leaving what you're doing.","title":"Features/Quick capture"},{"anchor":"b13","slug":"features-quick-capture","text":"It's the real editor in there: [[ page links, # tags, / slash commands, and nested bullets all work.","title":"Features/Quick capture"},{"anchor":"b14","slug":"features-quick-capture","text":"Create one yourself","title":"Features/Quick capture"},{"anchor":"b15","slug":"features-quick-capture","text":"1. Open your desktop environment's keyboard-shortcut settings.","title":"Features/Quick capture"},{"anchor":"b16","slug":"features-quick-capture","text":"2. Add a custom shortcut whose command is tine --capture.","title":"Features/Quick capture"},{"anchor":"b17","slug":"features-quick-capture","text":"3. Press the shortcut while another app is focused, then type a quick note.","title":"Features/Quick capture"},{"anchor":"b18","slug":"features-quick-capture","text":"4. Leave the title empty for today's journal, or type a page title to file it there.","title":"Features/Quick capture"},{"anchor":"b19","slug":"features-quick-capture","text":"5. What you should see: the capture box saves real Logseq bullets into your graph without switching windows.","title":"Features/Quick capture"},{"anchor":"b20","slug":"features-quick-capture","text":"Tune the Enter key","title":"Features/Quick capture"},{"anchor":"b21","slug":"features-quick-capture","text":"By default Enter starts a new bullet and Ctrl+Shift+Enter files the capture (so you can jot several lines first). Prefer Enter-to-file? Open Settings and flip Quick-capture: Enter key.","title":"Features/Quick capture"},{"anchor":"b22","slug":"features-quick-capture","text":"If you unbind Quick-capture: file to today's journal in Keyboard Shortcuts, the capture box shows a File capture button so filing remains available without a key.","title":"Features/Quick capture"},{"anchor":"b23","slug":"features-quick-capture","text":"The box auto-grows as you type, and it keeps your draft if it loses focus — only Esc or filing it clears the text.","title":"Features/Quick capture"},{"anchor":"b24","slug":"features-quick-capture","text":"Where next","title":"Features/Quick capture"},{"anchor":"b25","slug":"features-quick-capture","text":"Captures land in today's journal or on a page you name — Workflows/Capture and plan your day builds the rest of the daily flow on top. This capture window is a desktop feature. On Android and iOS, the share sheet, the Quick capture shortcut and iOS Shortcuts file to the same place: Reference/Platforms and mobile covers them and what each platform ships.","title":"Features/Quick capture"},{"anchor":"b0","slug":"features-sheets","text":"Sheets","title":"Features/Sheets"},{"anchor":"b1","slug":"features-sheets","text":"Sheets turn ordinary outline branches into 2-D views — tables, boards, and grids. The same file still opens in Logseq as nested bullets with harmless tine.* properties.","title":"Features/Sheets"},{"anchor":"b2","slug":"features-sheets","text":"Wide Markdown, Org and sheet tables stay centered on the text column and use the free space in their pane. They scroll horizontally only when wider than the pane; tables inside a sheet cell stay within that cell.","title":"Features/Sheets"},{"anchor":"b3","slug":"features-sheets","text":"This page starts with the easiest path — viewing bullets you already have — and shows fields, formulas, and grids after.","title":"Features/Sheets"},{"anchor":"b4","slug":"features-sheets","text":"Start from bullets you already have","title":"Features/Sheets"},{"anchor":"b5","slug":"features-sheets","text":"Sheets never move your data: rows are child bullets, columns are their properties, cards are child bullets. Nothing is converted or copied.","title":"Features/Sheets"},{"anchor":"b6","slug":"features-sheets","text":"Right-click a parent bullet and choose Show children as → Grid or Table — or type /Grid, /Table, or /Board on that block.","title":"Features/Sheets"},{"anchor":"b7","slug":"features-sheets","text":"What Tine writes: plain block properties such as tine.view:: table on the view-owning block. Editing a sheet cell writes back into the underlying bullet, so the outline and the sheet always agree.","title":"Features/Sheets"},{"anchor":"b8","slug":"features-sheets","text":"Formula columns derive values live (the Typed reading list below computes effort from rating); derived values are shown, never written onto the rows.","title":"Features/Sheets"},{"anchor":"b9","slug":"features-sheets","text":"Positional grid","title":"Features/Sheets"},{"anchor":"b11","slug":"features-sheets","text":"Area","title":"Features/Sheets"},{"anchor":"b12","slug":"features-sheets","text":"Owner","title":"Features/Sheets"},{"anchor":"b13","slug":"features-sheets","text":"Notes","title":"Features/Sheets"},{"anchor":"b15","slug":"features-sheets","text":"Spec","title":"Features/Sheets"},{"anchor":"b16","slug":"features-sheets","text":"Martin","title":"Features/Sheets"},{"anchor":"b17","slug":"features-sheets","text":"Nested sub-grid","title":"Features/Sheets"},{"anchor":"b19","slug":"features-sheets","text":"Risk","title":"Features/Sheets"},{"anchor":"b20","slug":"features-sheets","text":"Mitigation","title":"Features/Sheets"},{"anchor":"b22","slug":"features-sheets","text":"Scope drift","title":"Features/Sheets"},{"anchor":"b23","slug":"features-sheets","text":"Keep v1 narrow","title":"Features/Sheets"},{"anchor":"b25","slug":"features-sheets","text":"Build","title":"Features/Sheets"},{"anchor":"b26","slug":"features-sheets","text":"Codex","title":"Features/Sheets"},{"anchor":"b27","slug":"features-sheets","text":"Ragged rows are fine","title":"Features/Sheets"},{"anchor":"b29","slug":"features-sheets","text":"Empty middle cell","title":"Features/Sheets"},{"anchor":"b31","slug":"features-sheets","text":"Still round-trips","title":"Features/Sheets"},{"anchor":"b32","slug":"features-sheets","text":"Create one yourself — grid","title":"Features/Sheets"},{"anchor":"b33","slug":"features-sheets","text":"1. On an empty block, type /Grid and pick Grid. Tine seeds one editable cell — just start typing.","title":"Features/Sheets"},{"anchor":"b34","slug":"features-sheets","text":"2. Grow it by its edges: hover the grid and click the + on the right edge for a new column, or the + on the bottom edge for a new row. Drag row or cell bullets to reshape it; the grid follows the tree.","title":"Features/Sheets"},{"anchor":"b35","slug":"features-sheets","text":"3. Already have an outline? Right-click its parent bullet and choose Show children as → Grid (or run /Grid on that block) to turn the existing bullets into a grid in place.","title":"Features/Sheets"},{"anchor":"b36","slug":"features-sheets","text":"4. What you should see: a live grid whose cells are still ordinary Logseq bullets.","title":"Features/Sheets"},{"anchor":"b37","slug":"features-sheets","text":"5. Under the hood: the block just carries tine.view:: grid (plus optional tine.header:: true for a label row and tine.col-widths::). You never have to type those by hand.","title":"Features/Sheets"},{"anchor":"b38","slug":"features-sheets","text":"Task table","title":"Features/Sheets"},{"anchor":"b39","slug":"features-sheets","text":"Draft the sheet docs #sheets-demo","title":"Features/Sheets"},{"anchor":"b40","slug":"features-sheets","text":"Polish cell menus #sheets-demo","title":"Features/Sheets"},{"anchor":"b41","slug":"features-sheets","text":"Add aggregate footer #sheets-demo","title":"Features/Sheets"},{"anchor":"b42","slug":"features-sheets","text":"Create one yourself — table","title":"Features/Sheets"},{"anchor":"b43","slug":"features-sheets","text":"1. On a block, type /Table and pick Table (or right-click an existing outline and choose Show children as → Table).","title":"Features/Sheets"},{"anchor":"b44","slug":"features-sheets","text":"2. Use the ghost + Add row and + Add column buttons to build it out. Each row is a child bullet; each column is a property such as owner:: or estimate::, edited right in the cells.","title":"Features/Sheets"},{"anchor":"b45","slug":"features-sheets","text":"A field rename preserves query aggregate configuration too: bare count, average, repeated aggregate entries, and unrelated segments stay in their original order.","title":"Features/Sheets"},{"anchor":"b46","slug":"features-sheets","text":"3. Right-click a children-backed column header or double-click its name to rename the field and its dependent filter, group, aggregate, and formula references together. Ambiguous or colliding names are refused.","title":"Features/Sheets"},{"anchor":"b47","slug":"features-sheets","text":"Drag the narrow handle at a Table column's right edge to resize it. Double-click the handle to restore its automatic width. Tine stores widths by column identity in tine.table-widths::, so reordering columns keeps their sizes.","title":"Features/Sheets"},{"anchor":"b48","slug":"features-sheets","text":"The + Add row label stays at the visible edge when a wide table scrolls sideways. Copy / export… can produce HTML from the same table content.","title":"Features/Sheets"},{"anchor":"b49","slug":"features-sheets","text":"4. Press Tab after editing a cell to commit its value and move to the next cell.","title":"Features/Sheets"},{"anchor":"b50","slug":"features-sheets","text":"5. What you should see: each child bullet becomes a row, and properties become editable table columns.","title":"Features/Sheets"},{"anchor":"b51","slug":"features-sheets","text":"6. Under the hood: the block carries tine.view:: table (with optional tine.fields:: to type columns and tine.col-aggregates:: prop:estimate=sum to total a numeric column in the footer). The ghost buttons write these for you.","title":"Features/Sheets"},{"anchor":"b52","slug":"features-sheets","text":"Typed reading list","title":"Features/Sheets"},{"anchor":"b53","slug":"features-sheets","text":"Bases study","title":"Features/Sheets"},{"anchor":"b54","slug":"features-sheets","text":"CSV import notes","title":"Features/Sheets"},{"anchor":"b55","slug":"features-sheets","text":"Create one yourself — formula","title":"Features/Sheets"},{"anchor":"b56","slug":"features-sheets","text":"1. Start with a table that has a numeric or enum field, for example rating=number.","title":"Features/Sheets"},{"anchor":"b57","slug":"features-sheets","text":"2. Right-click a column header and choose Add/Edit formula, then build the value from the visual faces (or the </> raw box).","title":"Features/Sheets"},{"anchor":"b58","slug":"features-sheets","text":"3. What you should see: a read-only computed column whose values evaluate live and are not written onto the rows.","title":"Features/Sheets"},{"anchor":"b59","slug":"features-sheets","text":"4. For the full walkthrough — the value picker, IF / THEN / ELSE, transforms, and when to reach for </> raw — see Features/Formulas.","title":"Features/Sheets"},{"anchor":"b60","slug":"features-sheets","text":"Task board","title":"Features/Sheets"},{"anchor":"b62","slug":"features-sheets","text":"Create one yourself — query","title":"Features/Sheets"},{"anchor":"b63","slug":"features-sheets","text":"1. Type /Query and create a query for the blocks you want, such as tasks tagged #sheets-demo.","title":"Features/Sheets"},{"anchor":"b64","slug":"features-sheets","text":"2. Keep the query in one block, then run /Table or /Board on that same block to view the results.","title":"Features/Sheets"},{"anchor":"b65","slug":"features-sheets","text":"3. For a board, use the Group by dropdown (see below) to pick the column axis.","title":"Features/Sheets"},{"anchor":"b66","slug":"features-sheets","text":"In a query table, a sort that cannot be saved with the query is labeled Table-only sort. Click that label to clear that local order; the saved query order stays as it was.","title":"Features/Sheets"},{"anchor":"b67","slug":"features-sheets","text":"4. What you should see: query results render as a live sheet view without copying the source blocks.","title":"Features/Sheets"},{"anchor":"b68","slug":"features-sheets","text":"Create one yourself — board","title":"Features/Sheets"},{"anchor":"b69","slug":"features-sheets","text":"1. On a block, type /Board and pick Board (/Kanban finds it too).","title":"Features/Sheets"},{"anchor":"b70","slug":"features-sheets","text":"2. Choose the column axis with the Group by dropdown in the board header, or right-click and use Group by → to pick State, Tags, Priority, or any field. On a query's board the same menu also offers No grouping: one column holding every result.","title":"Features/Sheets"},{"anchor":"b71","slug":"features-sheets","text":"3. Add child bullets, or run /Board on a query block to board over query results.","title":"Features/Sheets"},{"anchor":"b72","slug":"features-sheets","text":"4. What you should see: cards group into columns while staying normal outline blocks underneath.","title":"Features/Sheets"},{"anchor":"b73","slug":"features-sheets","text":"5. Under the hood: the dropdown just writes tine.view:: board and tine.group-by:: state (or your chosen axis) for you.","title":"Features/Sheets"},{"anchor":"b74","slug":"features-sheets","text":"Topic board","title":"Features/Sheets"},{"anchor":"b75","slug":"features-sheets","text":"Schema menu polish #schema #sheets-demo","title":"Features/Sheets"},{"anchor":"b76","slug":"features-sheets","text":"CSV drop walkthrough #interop #sheets-demo","title":"Features/Sheets"},{"anchor":"b0","slug":"features-tips-shortcuts","text":"Tips & shortcuts","title":"Features/Tips & shortcuts"},{"anchor":"b1","slug":"features-tips-shortcuts","text":"A quick tour of the things that aren't obvious on day one. (Shortcuts are remappable in Settings.)","title":"Features/Tips & shortcuts"},{"anchor":"b2","slug":"features-tips-shortcuts","text":"With a non-Latin keyboard layout, shortcuts and recording use the physical key's Latin letter or digit: Ctrl+K still works when that key types л. Latin layouts such as AZERTY and Dvorak keep their letter-based shortcuts. Text you type keeps the selected language.","title":"Features/Tips & shortcuts"},{"anchor":"b3","slug":"features-tips-shortcuts","text":"Find anything — Ctrl+K","title":"Features/Tips & shortcuts"},{"anchor":"b4","slug":"features-tips-shortcuts","text":"Ctrl+K opens the quick switcher: jump to a page, search the text of any block, or run a command — all from one box. Ctrl+Shift+P opens the command palette (commands only).","title":"Features/Tips & shortcuts"},{"anchor":"b5","slug":"features-tips-shortcuts","text":"Search page names searches only page names and aliases; Search block content searches only block text. Both commands start unbound: assign keys in Settings → Shortcuts, or run them from the command palette.","title":"Features/Tips & shortcuts"},{"anchor":"b6","slug":"features-tips-shortcuts","text":"Use Ctrl+Shift+K to search only the focused page, including children hidden under folded bullets. In the ordinary Ctrl+K switcher, press Shift+Enter on a page or block to send it to the right sidebar without leaving your current page.","title":"Features/Tips & shortcuts"},{"anchor":"b7","slug":"features-tips-shortcuts","text":"Use Search syntax for phrases, alternatives, exclusions, and regular expressions. Choose Open search tab to keep the complete search in a graph-specific tab instead of choosing only one hit. To open a blank search tab directly in the focused pane, assign a key to Open search tab (go/search-tab) in Settings → Shortcuts; it is unbound by default.","title":"Features/Tips & shortcuts"},{"anchor":"b8","slug":"features-tips-shortcuts","text":"The result tab separates Pages and Blocks. Pages match names and aliases by default; choose Pages match → Block content to find pages containing a matching block, or Names or content for both. Blocks still show the matching text. The choice stays with the tab and a saved search uses tine.page-match-scope:: content or both on its query block.","title":"Features/Tips & shortcuts"},{"anchor":"b9","slug":"features-tips-shortcuts","text":"Each section has its own Display control: show Pages as a table with columns from authored page properties while Blocks stay a list, for example. Name the search and choose Save page to keep both choices on an ordinary query page. The compact filter button handles friendly fields and date ranges; Query builder opens the deeper visual editor when needed.","title":"Features/Tips & shortcuts"},{"anchor":"b10","slug":"features-tips-shortcuts","text":"Page-title matching keeps exact, prefix, substring, and fuzzy results in that order. Repeated choices may break ties inside one class using device-local history; disable or reset this under Search settings if you prefer fixed ordering.","title":"Features/Tips & shortcuts"},{"anchor":"b11","slug":"features-tips-shortcuts","text":"Ctrl+F searches the main and split panes and expanded right-sidebar items in that order; Enter / Shift+Enter move forward / backward through matches. The arrow at the left of the find bar adds Replace and Replace all for the page you opened Find in.","title":"Features/Tips & shortcuts"},{"anchor":"b12","slug":"features-tips-shortcuts","text":"In a Search tab, clicking a result opens a new tab and keeps the search available; right-click a page result for the switcher's page actions.","title":"Features/Tips & shortcuts"},{"anchor":"b13","slug":"features-tips-shortcuts","text":"In the quick switcher or a Search tab, Ctrl/Cmd-click a result to open it in a background tab, Shift-click for the right sidebar, or Alt-click for another pane.","title":"Features/Tips & shortcuts"},{"anchor":"b14","slug":"features-tips-shortcuts","text":"The quick switcher, page search, suggestions, and find-in-page ignore accents, case, and compatibility-width differences by default: cafe finds café, lodz finds Łódź, and Tine finds Ｔｉｎｅ. Marks that form another letter stay significant (か and が differ). To require accents in these searches, set :feature/enable-search-remove-accents? false in logseq/config.edn. This changes matching only; page names and Markdown keep their original spelling.","title":"Features/Tips & shortcuts"},{"anchor":"b15","slug":"features-tips-shortcuts","text":"Follow a link without the mouse — Ctrl+O","title":"Features/Tips & shortcuts"},{"anchor":"b16","slug":"features-tips-shortcuts","text":"With the caret inside a [[link]] or a #tag, Ctrl+O opens that page and Ctrl+Shift+O opens it in the right sidebar. This works while you are editing, so you can follow a name you just typed without reaching for the mouse.","title":"Features/Tips & shortcuts"},{"anchor":"b17","slug":"features-tips-shortcuts","text":"Select whole blocks — Ctrl+A","title":"Features/Tips & shortcuts"},{"anchor":"b18","slug":"features-tips-shortcuts","text":"While editing, Ctrl+A first selects the block's text; press it again to select the block with its children, and keep pressing to widen the selection to each parent and finally the whole page. Shift+Up onto a parent always takes all of that parent's children with it.","title":"Features/Tips & shortcuts"},{"anchor":"b19","slug":"features-tips-shortcuts","text":"Edit selected block returns one selected block to editing. It starts unbound; assign a key in Settings → Shortcuts. You can bind it to Escape if you prefer that way back into editing; without that binding, Escape keeps its ordinary selection steps.","title":"Features/Tips & shortcuts"},{"anchor":"b20","slug":"features-tips-shortcuts","text":"Copy a link to a block — Ctrl+C","title":"Features/Tips & shortcuts"},{"anchor":"b21","slug":"features-tips-shortcuts","text":"With several blocks selected, right-click any selected bullet: Copy blocks, Cut blocks, and Delete blocks act on the selection; Copy as ▸ holds Copy block refs, Copy block embeds, and Copy link for the same selection. Cut and delete take one Undo step; cutting keeps the complete subtrees for pasting. Right-clicking an unselected bullet acts on that bullet.","title":"Features/Tips & shortcuts"},{"anchor":"b22","slug":"features-tips-shortcuts","text":"While editing with no text selected, Ctrl/Cmd+C copies a reference ((id)) to the block and Ctrl/Cmd+Shift+C copies an embed {{embed ((id))}}. With text selected, both keep their ordinary copy meaning.","title":"Features/Tips & shortcuts"},{"anchor":"b23","slug":"features-tips-shortcuts","text":"Insert a block above","title":"Features/Tips & shortcuts"},{"anchor":"b24","slug":"features-tips-shortcuts","text":"To put a bullet above an existing one, press Enter with the caret at its very start. Some bullets keep Enter for themselves — inside a code block it adds a line of code — so for those, right-click the bullet's dot and choose Insert block above. That works on any bullet, including the first one on a page.","title":"Features/Tips & shortcuts"},{"anchor":"b25","slug":"features-tips-shortcuts","text":"Paste plain text, or paste as a link","title":"Features/Tips & shortcuts"},{"anchor":"b26","slug":"features-tips-shortcuts","text":"Ctrl/Cmd+Shift+V pastes the clipboard as plain text inside the current block: copied web headings, bold runs and lists are not converted, and multiline text stays in one block instead of becoming several. Ordinary Ctrl/Cmd+V keeps converting copied web content and outlines.","title":"Features/Tips & shortcuts"},{"anchor":"b27","slug":"features-tips-shortcuts","text":"Paste as link turns what you copied into a link without typing the syntax. Copy a URL or a block reference, select some words in a block you are editing, and run it: see context becomes [context](https://…) or [context](((id))). With nothing selected the link is inserted bare. It ships without a key, so assign one under Settings → Shortcuts (the command palette lists it too, but opening the palette leaves the editor, so use the key). Ordinary paste over a selection is unchanged.","title":"Features/Tips & shortcuts"},{"anchor":"b28","slug":"features-tips-shortcuts","text":"Block commands you can bind","title":"Features/Tips & shortcuts"},{"anchor":"b29","slug":"features-tips-shortcuts","text":"These commands ship without a key, so nothing you already use changes. Assign keys under Settings → Shortcuts; each acts on the selected blocks, or on the block you are editing when nothing is selected.","title":"Features/Tips & shortcuts"},{"anchor":"b30","slug":"features-tips-shortcuts","text":"Duplicate block below (with children) puts a copy, children included, right under the block, and the caret follows it, so pressing it again stacks copies. The copy gets its own ids; one Undo removes it.","title":"Features/Tips & shortcuts"},{"anchor":"b31","slug":"features-tips-shortcuts","text":"Duplicate block above (with children) does the same above the original. The caret follows the new copy, so repeated presses stack copies upwards. It also ships without a key; bind it under Settings → Shortcuts.","title":"Features/Tips & shortcuts"},{"anchor":"b32","slug":"features-tips-shortcuts","text":"Insert child block adds an empty last child under the block and starts editing it, which works where Enter then Tab cannot, such as an embedded block with no children yet. A folded block opens so the new child shows.","title":"Features/Tips & shortcuts"},{"anchor":"b33","slug":"features-tips-shortcuts","text":"Collapse (one level) folds the immediate children of the block, and folds the block itself once its children are all folded (or have no children of their own). Expand (one level) works the other way: a folded block opens by itself first, with its children still folded; each further press opens the next level with folded children, ignoring leaves, until everything is expanded, and each press is one Undo step. With nothing selected they start at the page's top-level blocks.","title":"Features/Tips & shortcuts"},{"anchor":"b34","slug":"features-tips-shortcuts","text":"Copy block refs of the selected blocks copies a ((id)) reference for each selected block, one per line in the order you see them, the same text as Copy as ▸ → Copy block refs in the block context menu.","title":"Features/Tips & shortcuts"},{"anchor":"b35","slug":"features-tips-shortcuts","text":"Search for the selected text opens search with the selection already typed in. The ready-made key for it, Ctrl/Cmd+Shift+F, is Logseq's toggle favorite, so it is left for you to choose.","title":"Features/Tips & shortcuts"},{"anchor":"b36","slug":"features-tips-shortcuts","text":"Create one yourself","title":"Features/Tips & shortcuts"},{"anchor":"b37","slug":"features-tips-shortcuts","text":"1. Press Ctrl+K.","title":"Features/Tips & shortcuts"},{"anchor":"b38","slug":"features-tips-shortcuts","text":"2. Type part of a page name, a block phrase, or a command such as Open Guide.","title":"Features/Tips & shortcuts"},{"anchor":"b39","slug":"features-tips-shortcuts","text":"3. Press Enter on the highlighted result.","title":"Features/Tips & shortcuts"},{"anchor":"b40","slug":"features-tips-shortcuts","text":"4. What you should see: Tine jumps to the page/block or runs the command without leaving your graph.","title":"Features/Tips & shortcuts"},{"anchor":"b41","slug":"features-tips-shortcuts","text":"Slash commands — /","title":"Features/Tips & shortcuts"},{"anchor":"b42","slug":"features-tips-shortcuts","text":"Type / at the start of a bullet for a menu: tasks, headings, a code block, a /calc live calculator (hover a result to copy it), dates (Scheduled / Deadline), callouts, queries, a math block, asset upload, and more. /Code block opens a language picker; typing a language after an opening backtick or tilde fence offers the same completion.","title":"Features/Tips & shortcuts"},{"anchor":"b43","slug":"features-tips-shortcuts","text":"On a journal page, /That day inserts a link to that journal's date, even when it is an older day. /Today inserts today's date. Both use your graph's journal title format.","title":"Features/Tips & shortcuts"},{"anchor":"b44","slug":"features-tips-shortcuts","text":"With Simplified Chinese selected, each built-in slash row shows its English keyword followed by a Chinese gloss in parentheses. English typing still finds the same commands; Chinese glosses are searchable too. Selecting a row inserts the original syntax.","title":"Features/Tips & shortcuts"},{"anchor":"b45","slug":"features-tips-shortcuts","text":"Journal days","title":"Features/Tips & shortcuts"},{"anchor":"b46","slug":"features-tips-shortcuts","text":"g j opens the Journals feed. g h opens the graph's home page, chosen in Settings → Graph or set as :default-home {:page \"Page name\"} in logseq/config.edn; Tine also opens it when it opens a graph without a saved session. With a saved session, Tine restores every tab's last page, order and pin state, and the same active tab. Renaming the home page (or a namespace it lives in) keeps it the home page; merging it into another page does not. With no home page set, or when that page no longer exists, g h opens the Journals feed. g n and g p move to the next or previous calendar day from the journal you are viewing. From another page, they start at today.","title":"Features/Tips & shortcuts"},{"anchor":"b47","slug":"features-tips-shortcuts","text":"A configured default journal template is inserted once for each new day, including when Tine stays open through local midnight. Choose a journal display date format in Settings; the three dotted day-month-year patterns are available there too. The display format does not rename journal files.","title":"Features/Tips & shortcuts"},{"anchor":"b48","slug":"features-tips-shortcuts","text":"Opening a graph never renames journal files. If some are named by title instead of by date, their days look empty; Settings → Backups & recovery lists them under Journal files named by title with a Rename to date names button, which takes a snapshot first.","title":"Features/Tips & shortcuts"},{"anchor":"b49","slug":"features-tips-shortcuts","text":"Hover a journal title row or focus one of its controls with the keyboard to reveal the carry buttons, in the feed and on a journal page. On touch devices without hover they stay visible. The buttons under today's journal pull unfinished tasks from earlier days. After midnight, yesterday's button changes to Carry unfinished tasks → today.","title":"Features/Tips & shortcuts"},{"anchor":"b50","slug":"features-tips-shortcuts","text":"Tabs","title":"Features/Tips & shortcuts"},{"anchor":"b51","slug":"features-tips-shortcuts","text":"Middle-click any bullet, page, or search result to open it in a background tab. Double-click a tab to pin it, drag to reorder, Ctrl+W to close. Your tabs come back next launch. In a split view, a pane's only tab still has a close button (it closes the pane) unless it shows the journals.","title":"Features/Tips & shortcuts"},{"anchor":"b52","slug":"features-tips-shortcuts","text":"Bind Activate tab 1 through Activate tab 8, or Activate last tab, in Settings → Shortcuts to jump within the focused pane's tab order. They start unbound because Ctrl/Cmd+1–9 already focus panes. A numbered slot with no tab does nothing.","title":"Features/Tips & shortcuts"},{"anchor":"b53","slug":"features-tips-shortcuts","text":"Numbered tab/pane commands and sidebar/pane resize commands stay bindable in Settings → Shortcuts and are omitted from the command palette. Carry unfinished tasks: last N days uses the day count in Settings → Journals.","title":"Features/Tips & shortcuts"},{"anchor":"b54","slug":"features-tips-shortcuts","text":"Page links, block references, an outline bullet's dot, backlink headers, the sidebar and query results all take the same modified clicks: Shift-click opens the right sidebar, Ctrl/Cmd-click or middle-click opens a background tab, and Alt-click opens the other pane (splitting one off if you have only one).","title":"Features/Tips & shortcuts"},{"anchor":"b55","slug":"features-tips-shortcuts","text":"When a pane has more tabs than fit, use its tab-overview button to see every full title, activate or pin a tab, close it, or reorder it with the drag handle / Alt+Up/Down without guessing from truncated labels.","title":"Features/Tips & shortcuts"},{"anchor":"b56","slug":"features-tips-shortcuts","text":"Use the command palette to Toggle maximize active pane and use the pane-size commands to grow or shrink the active pane with the keyboard. Run Reset interface zoom to return to normal scale.","title":"Features/Tips & shortcuts"},{"anchor":"b57","slug":"features-tips-shortcuts","text":"The sidebars","title":"Features/Tips & shortcuts"},{"anchor":"b58","slug":"features-tips-shortcuts","text":"Assign keys in Settings → Shortcuts to Grow left sidebar width (sidebar/grow-width), Shrink left sidebar width (sidebar/shrink-width), Grow right sidebar width (right-sidebar/grow-width), and Shrink right sidebar width (right-sidebar/shrink-width). All four start unbound. Each press changes the width by 48 px within the same limits as dragging, and the width is remembered on this device.","title":"Features/Tips & shortcuts"},{"anchor":"b59","slug":"features-tips-shortcuts","text":"Hover over a truncated page title in the left sidebar to see its full title. Titles that fit show no tooltip.","title":"Features/Tips & shortcuts"},{"anchor":"b60","slug":"features-tips-shortcuts","text":"Below a page, Linked References and Unlinked References show where it is mentioned, including plain mentions in code and math. Use the copy button at the right edge of either header to select visible results and open the shared Copy / export dialog; an Org source stays Org in source export. An expanded section stays open when the page view remounts. A page with many backlinks opens Linked References folded; Logseq's :ref/linked-references-collapsed-threshold in config.edn sets where that starts (default 100), and 0 starts every page folded. In Linked References, a reference must match every included chip and none of the excluded chips; typed text narrows both results and available chips. The block-reference locations panel can collapse or expand all source groups.","title":"Features/Tips & shortcuts"},{"anchor":"b61","slug":"features-tips-shortcuts","text":"t l toggles the left sidebar — journals, favorites, recents, all pages, and a namespace tree. Favorites and Recent can be folded independently. Choose + New group to arrange favorites under plain-text labels, then drag a row up or down to reorder it, right to nest it under the row above (to any depth), or left to lift it out; deleting a group keeps what it held one level up. Tine keeps that arrangement on an ordinary editable page called Favorites (marked tine/favorites:: true) and still writes config.edn :favorites as the flat list Logseq reads.","title":"Features/Tips & shortcuts"},{"anchor":"b62","slug":"features-tips-shortcuts","text":"Right-click a graph in the left sidebar to copy its folder path, show it in your file manager, open another window, or remove it from the recent graph list.","title":"Features/Tips & shortcuts"},{"anchor":"b63","slug":"features-tips-shortcuts","text":"t r toggles the right sidebar; Shift-click any bullet's dot to open it there and keep it beside your work. Each right-sidebar item can be folded independently, and its menu can collapse, expand, or close them all. Drag an item by its header to reorder the list.","title":"Features/Tips & shortcuts"},{"anchor":"b64","slug":"features-tips-shortcuts","text":"On a phone-width window (below 640 px), either sidebar opens over the page. Tap the shaded outside edge, use the close button, press Esc, or press Android Back to return to the page. Wider tablet and desktop windows keep the ordinary persistent, resizable sidebars.","title":"Features/Tips & shortcuts"},{"anchor":"b65","slug":"features-tips-shortcuts","text":"Click the vertical outline guide below a bullet to expand its complete descendant subtree when anything inside is folded, or collapse all of those descendants when everything is open. The bullet itself keeps its ordinary one-level action.","title":"Features/Tips & shortcuts"},{"anchor":"b66","slug":"features-tips-shortcuts","text":"Focus mode & dimming — t f / t b","title":"Features/Tips & shortcuts"},{"anchor":"b67","slug":"features-tips-shortcuts","text":"t f (focus mode) hides the sidebars and toolbar so the screen is just your text; layered Esc steps back out.","title":"Features/Tips & shortcuts"},{"anchor":"b68","slug":"features-tips-shortcuts","text":"t b (dim inactive blocks) fades everything except the bullet you're editing — a typewriter-style spotlight. Use it on its own, or let focus mode turn it on for you.","title":"Features/Tips & shortcuts"},{"anchor":"b69","slug":"features-tips-shortcuts","text":"Sync copies and merge conflicts","title":"Features/Tips & shortcuts"},{"anchor":"b70","slug":"features-tips-shortcuts","text":"When Syncthing or Dropbox leaves a conflict copy of a page, or a git or Fossil merge leaves <<<<<<< merge markers in a file, an N conflicts badge appears at the bottom of the left sidebar. It opens the Conflicts page, which lists every page that needs a decision; Discard copy moves a sync copy to the graph trash (recoverable). The list comes from your files, not from a list Tine keeps in your graph: to avoid re-reading every page at launch, Tine remembers which pages it has already seen without merge markers in its own disposable launch cache, and reads any page it has not seen from the file.","title":"Features/Tips & shortcuts"},{"anchor":"b71","slug":"features-tips-shortcuts","text":"Open a listed page to resolve it there, block by block: keep one side, the other, or both. Where the merge markers carry the common ancestor, Tine pre-selects the side that actually changed; nothing is applied until you choose Apply resolution.","title":"Features/Tips & shortcuts"},{"anchor":"b72","slug":"features-tips-shortcuts","text":"Tine refuses to save a page that still contains merge markers, because rewriting it would re-indent the markers and silently lose one side. Apply resolution is the one save that may replace such a file; the file as it was first goes to the graph trash. A merged sync copy goes to the trash too.","title":"Features/Tips & shortcuts"},{"anchor":"b73","slug":"features-tips-shortcuts","text":"A few more worth knowing","title":"Features/Tips & shortcuts"},{"anchor":"b74","slug":"features-tips-shortcuts","text":"Use the … beside an ordinary page title for its complete actions menu: open the source file, copy/export, inspect properties, rename, carry tasks, or delete. It is the same menu as right-click and works from the keyboard and touch.","title":"Features/Tips & shortcuts"},{"anchor":"b75","slug":"features-tips-shortcuts","text":"In Copy / Export, choose Plain text for the text as displayed, without markup markers, or Markdown (Org on an Org page) to keep the original syntax: bold, highlighting, links, and properties.","title":"Features/Tips & shortcuts"},{"anchor":"b76","slug":"features-tips-shortcuts","text":"Right-click a block and choose Open in new tab to keep that block in its own tab (on a computer; phones and tablets have no tab strip and offer Open in sidebar instead).","title":"Features/Tips & shortcuts"},{"anchor":"b77","slug":"features-tips-shortcuts","text":"In Settings → Shortcuts, search by command or key and choose Unbind to remove a shortcut; the command stays available from places such as the command palette, and Reset restores its default instead. Settings → Appearance offers Light, Dark, and System themes. The Settings window can be maximized; it remembers that choice on this device.","title":"Features/Tips & shortcuts"},{"anchor":"b78","slug":"features-tips-shortcuts","text":"Settings → Help & diagnostics creates a privacy-safe diagnostic report of this run and the previous one to attach to a bug report: operation names, outcomes, timings, counts, platform and build, never page content, titles, file paths or queries. If Tine did not close cleanly last time, it says so when it starts. Review the report and choose Copy report, or on desktop Save report…; nothing is uploaded, and the recorder keeps at most 1 MiB in Tine's own app data, never in your graph. The same tab also offers Rescan graph and Verify synchronized graph.","title":"Features/Tips & shortcuts"},{"anchor":"b79","slug":"features-tips-shortcuts","text":"Renaming a page to the name of another existing page offers to merge them, as Logseq does: the blocks move to the end of the page that remains, the aliases join, links to the old name point to it, and the merged file goes to the graph trash (recoverable).","title":"Features/Tips & shortcuts"},{"anchor":"b80","slug":"features-tips-shortcuts","text":"Tine saves pending edits before a rename. A page whose edits cannot be saved stops the rename only if the rename would change that page, or its unsaved text mentions the old name; the message names it. Other pages keep their unsaved edits through the rename. A page named by title::, or in Org by #+TITLE:, gets the new name in that line.","title":"Features/Tips & shortcuts"},{"anchor":"b81","slug":"features-tips-shortcuts","text":"Change capitalization directly with Rename, for example my note → My Note. The filename, title and references follow together; two distinct files claiming that name still block the rename.","title":"Features/Tips & shortcuts"},{"anchor":"b82","slug":"features-tips-shortcuts","text":"Carry unfinished tasks forward into today (from the command palette) — the last 7 / 30 / 365 days, optionally with their context.","title":"Features/Tips & shortcuts"},{"anchor":"b83","slug":"features-tips-shortcuts","text":"Export to PDF… saves pending page edits before preparing the printout. If a page cannot be saved, Tine stops the export and shows an error so the PDF does not silently omit your changes.","title":"Features/Tips & shortcuts"},{"anchor":"b84","slug":"features-tips-shortcuts","text":"Select several task bullets and press Ctrl/Cmd+Enter to advance each one through your workflow in a single Undo step. The selection toolbar can also wrap selected text as a page link or inline code.","title":"Features/Tips & shortcuts"},{"anchor":"b85","slug":"features-tips-shortcuts","text":"Undo is Ctrl/Cmd+Z and redo is Ctrl/Cmd+Shift+Z. On Windows and Linux Ctrl+Y also redoes, because that is the key most editors there use; the shortcuts list shows it beside the binding. It is a second default rather than a second command, so remapping Redo replaces both.","title":"Features/Tips & shortcuts"},{"anchor":"b86","slug":"features-tips-shortcuts","text":"Code blocks: type ``` (or choose Code block from the / menu) and Tine offers a language list; picking one fills in the opening fence and the closing fence for you. While editing, only the code itself is in the text box, so Enter adds a line of code instead of splitting the bullet. When prose and code share a bullet after Shift+Enter, clicking a code region edits only that region. Move the caret out of its body with an arrow key, or press Backspace at its start, to edit the whole bullet as source; surrounding text stays intact. To delete the whole code block, right-click its bullet and choose Delete block; on desktop, right-clicking inside the code with no text selected opens the same menu. Backspace in an empty code block without child bullets removes the wrapper; if it is the last block, it becomes a normal empty bullet. Code blocks show line numbers and a display-only language label. Hover the card to Copy code without its fences. Settings → Appearance → Wrap code lines controls wrapping for all code blocks, in both reading and editing; it is off by default and remembered on this device.","title":"Features/Tips & shortcuts"},{"anchor":"b87","slug":"features-tips-shortcuts","text":"Drag a bullet onto another bullet and move a little to the right (about 50 px into it) to make it that bullet's last child; nearer its left edge, the upper half places it before and the lower half after. A marker shows where it will land.","title":"Features/Tips & shortcuts"},{"anchor":"b88","slug":"features-tips-shortcuts","text":"Typing :: at the start of a line inside a bullet starts a property: the name goes to the left of the ::, Create is offered first, and after a comma the value list leaves out values already on the line.","title":"Features/Tips & shortcuts"},{"anchor":"b89","slug":"features-tips-shortcuts","text":"Namespaces: name a page Project/Roadmap and it nests under Project in the sidebar. This page lives under Features.","title":"Features/Tips & shortcuts"},{"anchor":"b90","slug":"features-tips-shortcuts","text":"Page names and files: put title:: Project/Roadmap above the first bullet to give an existing page that name, even when its filename differs. Tine keeps the file at its existing path; links and page search use the title. Markdown and Org pages in other graph folders, such as archive/, are pages too. New pages get portable filenames, including names with punctuation.","title":"Features/Tips & shortcuts"},{"anchor":"b91","slug":"features-tips-shortcuts","text":"Hidden graph paths: add :hidden [\"archive/private\"] to logseq/config.edn to exclude matching graph-relative path prefixes from pages and search. The files stay on disk. This also applies to pages outside the usual pages/ and journals/ folders.","title":"Features/Tips & shortcuts"},{"anchor":"b92","slug":"features-tips-shortcuts","text":"Page icons: add a property like icon:: 📚 at the very top of a page — that's where the ⌨️ on this one comes from. The icon property stays visible in the page-properties block; click its row to edit it.","title":"Features/Tips & shortcuts"},{"anchor":"b93","slug":"features-tips-shortcuts","text":"Page and block properties are editable from a form, not only as raw key:: value lines: use Page properties… in the page menu (or /page properties while editing), or right-click a block for Properties…. The form lists every property the page or block really has; a page's form always offers Aliases, Tags, Display title, Icon and Public. Any other property can be changed or removed, and Add a property takes any key you like — it does not have to be plain ASCII. id::, collapsed:: and tine. keys keep their own surfaces. Markdown writes key:: value, an Org page a #+key: value directive, and an Org block its :PROPERTIES: drawer. A read-only page offers no property editing at all.","title":"Features/Tips & shortcuts"},{"anchor":"b94","slug":"features-tips-shortcuts","text":"Interface zoom with Ctrl/Cmd + / - / 0 while the notes pane is focused. To return the whole interface to its default 100%, open the command palette (Ctrl/Cmd+Shift+P) and choose Reset interface zoom. This leaves PDF/image zoom and block zoom unchanged; a focused PDF keeps its own Ctrl/Cmd + / - / 0 controls.","title":"Features/Tips & shortcuts"},{"anchor":"b0","slug":"project-roadmap","text":"Project / Roadmap","title":"Project/Roadmap"},{"anchor":"b1","slug":"project-roadmap","text":"This page lives in the Project namespace, and it doubles as the target for the reference and the embed over on Welcome to Tine.","title":"Project/Roadmap"},{"anchor":"7a1c0f5e-0000-4000-8000-000000000001","slug":"project-roadmap","text":"Tine round-trips your files byte-for-byte, so you can always switch back to Logseq — nothing here is one-way.","title":"Project/Roadmap"},{"anchor":"b2","slug":"project-roadmap","text":"See the little count badge on the bullet above? That's how many blocks reference it — click the badge to see them.","title":"Project/Roadmap"},{"anchor":"b3","slug":"project-roadmap","text":"A few example tasks","title":"Project/Roadmap"},{"anchor":"b4","slug":"project-roadmap","text":"Write my first real note in Tine","title":"Project/Roadmap"},{"anchor":"b5","slug":"project-roadmap","text":"Set up the quick-capture hotkey — see Features/Quick capture","title":"Project/Roadmap"},{"anchor":"b6","slug":"project-roadmap","text":"Open my own Logseq graph and look around","title":"Project/Roadmap"},{"anchor":"b0","slug":"reference-command-line","text":"Command line","title":"Reference/Command line"},{"anchor":"b1","slug":"reference-command-line","text":"The installed desktop program also has a small command-line interface. Run tine --help for the current command list and tine --version (or tine version) for the exact build version.","title":"Reference/Command line"},{"anchor":"b2","slug":"reference-command-line","text":"Open Tine","title":"Reference/Command line"},{"anchor":"b3","slug":"reference-command-line","text":"tine open GRAPH opens a graph. The older shorthand tine GRAPH remains supported. If Tine is already running, the graph opens in a new window of that instance.","title":"Reference/Command line"},{"anchor":"b4","slug":"reference-command-line","text":"tine capture opens Quick Capture. The older tine --capture spelling remains supported, so existing desktop shortcuts keep working.","title":"Reference/Command line"},{"anchor":"b5","slug":"reference-command-line","text":"tine --debug turns on the diagnostic log for that run, exactly like TINE_DEBUG=1.","title":"Reference/Command line"},{"anchor":"b6","slug":"reference-command-line","text":"Publish a graph","title":"Reference/Command line"},{"anchor":"b7","slug":"reference-command-line","text":"tine export static GRAPH --output PARENT writes the static HTML publication. tine export live GRAPH --output PARENT writes the read-only Tine app and keeps the static HTML site as its no-JavaScript and file:// fallback.","title":"Reference/Command line"},{"anchor":"b8","slug":"reference-command-line","text":"PARENT must be an existing folder outside the graph, given as an absolute path. Tine creates one new child folder in it, named after the graph (or after --name), and refuses to replace an existing folder of that name.","title":"Reference/Command line"},{"anchor":"b9","slug":"reference-command-line","text":"Publication follows the graph's existing privacy settings: only pages with public:: true are included, unless :publishing/all-pages-public? is enabled. Add --all-pages to override that selection for one export.","title":"Reference/Command line"},{"anchor":"b10","slug":"reference-command-line","text":"Example: tine export live ~/notes --all-pages --output ~/Sites --name \"My notes\"","title":"Reference/Command line"},{"anchor":"b11","slug":"reference-command-line","text":"A live export opens on the configured home page when it is exported, then Welcome to Tine, then the first exported page. Use --home \"Page name\" to choose explicitly; a home page that is not exported is refused.","title":"Reference/Command line"},{"anchor":"b12","slug":"reference-command-line","text":"Check a graph","title":"Reference/Command line"},{"anchor":"b13","slug":"reference-command-line","text":"tine doctor GRAPH reads and parses the graph, reports how many pages and journals it found and the configured home page, names every unreadable page and every page name claimed by more than one file, and does not change the graph. It exits with status 1 when it finds a problem.","title":"Reference/Command line"},{"anchor":"b14","slug":"reference-command-line","text":"Read your graph from a terminal","title":"Reference/Command line"},{"anchor":"b15","slug":"reference-command-line","text":"On Linux and macOS, the graph read commands are read-only: they do not edit notes. They ask the graph's owner, so tine page show and tine journal include unsaved edits when the app holds that page; other reads use the graph's indexed view.","title":"Reference/Command line"},{"anchor":"b16","slug":"reference-command-line","text":"Choose a graph with --graph GRAPH (or -g GRAPH) on each read command. Otherwise Tine uses TINE_GRAPH, then the nearest folder around your working directory with a logseq/ subfolder. Example: tine page show \"Project notes\" --graph ~/notes.","title":"Reference/Command line"},{"anchor":"b17","slug":"reference-command-line","text":"tine status shows whether the app or serve owns the graph and what it is doing.","title":"Reference/Command line"},{"anchor":"b18","slug":"reference-command-line","text":"tine page show \"Page name\" reads a page's outline. tine journal reads today; tine journal 2026-10-13 reads a specific day that already exists.","title":"Reference/Command line"},{"anchor":"b19","slug":"reference-command-line","text":"tine block show UUID reads a block and its descendants using its persisted id:: UUID. tine refs \"Page name\" shows linked references; tine refs UUID --block finds references to a persisted block id.","title":"Reference/Command line"},{"anchor":"b20","slug":"reference-command-line","text":"tine search \"meeting\" searches page names and block text as the app does. --pages N and --blocks N set the result limits; 0 switches that category off.","title":"Reference/Command line"},{"anchor":"b21","slug":"reference-command-line","text":"tine query '(task TODO)' runs the text inside a Logseq simple or advanced query macro. tine query \"task = 'TODO'\" --tql runs the text inside a Tine query macro. Features/Queries explains the query forms and their supported scope; read diagnostics when a query cannot run whole.","title":"Reference/Command line"},{"anchor":"b22","slug":"reference-command-line","text":"tine pages lists existing pages, including journals. tine pages --namespace Projects limits it to that namespace and its descendants; aliases and names that only appear in references are not listed.","title":"Reference/Command line"},{"anchor":"b23","slug":"reference-command-line","text":"Who owns the graph?","title":"Reference/Command line"},{"anchor":"b24","slug":"reference-command-line","text":"When the app has the graph open, it answers these commands. With no app holding the graph, a read command automatically starts tine serve GRAPH in the background. You can also run that command yourself in a terminal; it owns the graph without opening a window and exits after 30 idle minutes.","title":"Reference/Command line"},{"anchor":"b25","slug":"reference-command-line","text":"When you open that graph in the app, serve finishes admitted work, stops and hands over ownership. The app shows Finishing the command line's work on this graph… while it waits. If the handover has not finished after 60 seconds, opening fails and names tine serve GRAPH --stop; the app does not take ownership on a timeout. Read commands retry through a busy handover for up to 30 seconds.","title":"Reference/Command line"},{"anchor":"b26","slug":"reference-command-line","text":"tine serve GRAPH --stop asks the command-line owner to finish and exit. It cannot stop an app owner.","title":"Reference/Command line"},{"anchor":"b27","slug":"reference-command-line","text":"On Windows, the owner endpoint is unavailable in this Beta: graph read commands report unsupported (with --json, a JSON error on stderr), and reads and tine serve exit 5. The app still opens graphs normally without that endpoint. The launch, capture, doctor and export commands above remain available on desktop; Android and iOS have no command-line interface.","title":"Reference/Command line"},{"anchor":"b28","slug":"reference-command-line","text":"Output for people and scripts","title":"Reference/Command line"},{"anchor":"b29","slug":"reference-command-line","text":"Read commands print text to stdout by default, with outline addresses such as 1.2 for a second child. Add --json for a single JSON result on stdout with schema tine.cli/1, for example tine pages --graph ~/notes --json.","title":"Reference/Command line"},{"anchor":"b30","slug":"reference-command-line","text":"Successful commands exit 0. Failed reads print errors to stderr; --json makes owner and connection errors a JSON error envelope there. Invalid usage exits 2, a missing or ambiguous page/block exits 3, a still-busy owner exits 4, and endpoint/startup failures exit 5. Check the exit status and read any diagnostics or truncation notices before treating results as complete.","title":"Reference/Command line"},{"anchor":"b31","slug":"reference-command-line","text":"The command-line output contract documents JSON fields, limits, error codes and the full exit-code table.","title":"Reference/Command line"},{"anchor":"b32","slug":"reference-command-line","text":"Full reference","title":"Reference/Command line"},{"anchor":"b33","slug":"reference-command-line","text":"Every command and subcommand has --help, for example tine export live --help. Linux .deb and .rpm packages also install the same generated reference for man tine.","title":"Reference/Command line"},{"anchor":"b0","slug":"reference-files-external-edits-and-backups","text":"Files, external edits, and backups","title":"Reference/Files, external edits, and backups"},{"anchor":"b1","slug":"reference-files-external-edits-and-backups","text":"If closing warns about unsaved changes: Tine tries to save everything before the window closes. If a conflict or a stuck save prevents it, a prompt says so and asks whether to close anyway. The prompt names each unsaved page. Choose No to stay: a panel lists those pages with Retry saving, open, and Copy draft. A failed save's message stays up with Review unsaved, which opens the same panel. If a page cannot be saved when you switch graphs, Tine stays on the current graph with your edit and says so. For a conflict, look for the conflict banner or the N conflicts badge (below) and resolve it before you close. If a page still cannot be saved after you close Tine's last window, Tine does not quit over it: after half a minute it opens that graph again, and a message names each page whose edits are not on disk yet, and why (changed on disk, or saving fails).","title":"Reference/Files, external edits, and backups"},{"anchor":"b2","slug":"reference-files-external-edits-and-backups","text":"If Tine crashes or quits while a page cannot be saved, that page's unsaved text is kept in Tine's app data (never in your graph). On the next start Tine puts it back on the page and saves it, and a message names those pages: “Recovered unsaved edits … — Tine is saving them”. If the file changed on disk in the meantime, the page shows the changed-on-disk banner instead (see Reference/Troubleshooting and recovery), so nothing is written over unseen. Text that saved normally is not kept there. Crash-recovery copies from an older Tine are left untouched as a backup; a message names their file once.","title":"Reference/Files, external edits, and backups"},{"anchor":"b3","slug":"reference-files-external-edits-and-backups","text":"Your graph content stays in ordinary files shared with Logseq. Tine also keeps device settings and launch snapshots outside the graph. This page maps what is written where, and the safety nets around it.","title":"Reference/Files, external edits, and backups"},{"anchor":"b4","slug":"reference-files-external-edits-and-backups","text":"What lands on disk","title":"Reference/Files, external edits, and backups"},{"anchor":"b5","slug":"reference-files-external-edits-and-backups","text":"Pages and journals — one Markdown or Org file per page. Existing files may live at the graph root or in nested folders; Tine saves each one back to its exact path. New files use the configured pages/ and journals/ folders.","title":"Reference/Files, external edits, and backups"},{"anchor":"b6","slug":"reference-files-external-edits-and-backups","text":"Assets — pasted and uploaded files in assets/. Deleting a block never deletes its media.","title":"Reference/Files, external edits, and backups"},{"anchor":"b7","slug":"reference-files-external-edits-and-backups","text":"Copy image on desktop offers the original asset file to your file manager without changing its bytes or imposing a file size limit. If an image is too large to preview, hover over Preview unavailable to use Copy image. This also works for {{img ...}} image macros. An already-open image viewer keeps copying the original file after an outside asset edit. Missing files keep their missing-image placeholder. Smaller images also offer a bitmap for chat apps and image editors; this compatibility copy keeps the 64 MiB encoded-data limit and decoded-memory limit, including PNG images. Paste files copied in Explorer, Finder, or a Linux file manager to import their original bytes unchanged. A screenshot or other pixel-only clipboard image is saved as PNG. Mobile and remote image copying keep their existing image clipboard behavior.","title":"Reference/Files, external edits, and backups"},{"anchor":"b8","slug":"reference-files-external-edits-and-backups","text":"Graph configuration — logseq/config.edn, shared with Logseq: journal date formats, macros, and UI choices such as :ui/show-brackets? live there.","title":"Reference/Files, external edits, and backups"},{"anchor":"b9","slug":"reference-files-external-edits-and-backups","text":"Tine's view config — harmless tine.* block properties on the view-owning block (see Features/Sheets). Everything else stays ordinary graph text.","title":"Reference/Files, external edits, and backups"},{"anchor":"b10","slug":"reference-files-external-edits-and-backups","text":"Saving","title":"Reference/Files, external edits, and backups"},{"anchor":"b11","slug":"reference-files-external-edits-and-backups","text":"You never press Save: edits are written automatically to the same file the page came from, a moment after you pause.","title":"Reference/Files, external edits, and backups"},{"anchor":"b12","slug":"reference-files-external-edits-and-backups","text":"Writes go through a guarded path: Tine checks that the file still matches what it read before it replaces it, and a save that would overwrite an outside change is refused rather than forced (see external edits below).","title":"Reference/Files, external edits, and backups"},{"anchor":"b13","slug":"reference-files-external-edits-and-backups","text":"A page rename finishes once it starts; it is not rolled back. Tine writes the page under its new name and every page-link and tag rewrite that points at it, and removes the old file last. If a file cannot be written yet, the message says the rename finishes once it can be, and Tine keeps trying; if Tine stops in the middle, it finishes the rename on the next start. A crash while the new file also cannot be written can leave the page briefly without a file: its text stays in logseq/.tine-trash/ or in Tine's crash-recovery copies until the write succeeds.","title":"Reference/Files, external edits, and backups"},{"anchor":"b14","slug":"reference-files-external-edits-and-backups","text":"A page that still carries unresolved git or Fossil merge markers is never rewritten by a rename: its links keep the old name, and a message lists those pages so you can update them after resolving the merge.","title":"Reference/Files, external edits, and backups"},{"anchor":"b15","slug":"reference-files-external-edits-and-backups","text":"Tine saves pending edits before a rename. A page whose edits cannot be saved stops the rename only if the rename would change that page, or its unsaved text mentions the old name; the message names it. Other pages keep their unsaved edits through the rename.","title":"Reference/Files, external edits, and backups"},{"anchor":"b16","slug":"reference-files-external-edits-and-backups","text":"An Org file is rewritten only when Tine can reproduce it byte-for-byte; one it cannot round-trip opens read-only so the graph cannot be corrupted.","title":"Reference/Files, external edits, and backups"},{"anchor":"b17","slug":"reference-files-external-edits-and-backups","text":"External edits","title":"Reference/Files, external edits, and backups"},{"anchor":"b18","slug":"reference-files-external-edits-and-backups","text":"Tine notices changes made outside it — Logseq, Syncthing, or another editor. Settings (t s) → Files → Watch for external edits: Live (inotify) (default, no idle wakeups) or Poll (3s) for filesystems where the OS watcher misses edits (some network mounts). Saved per device.","title":"Reference/Files, external edits, and backups"},{"anchor":"b19","slug":"reference-files-external-edits-and-backups","text":"A page updates in place automatically, also while one of its blocks is open in the editor: the editor stays on that block, and closes only if the change deleted it (while you are composing text with an input method, the update waits until you finish). A page with unsaved edits is never overwritten: Tine skips that page in future saves and shows a banner with Review, which opens the panel at the top of the page. There you compare your draft with the disk version block by block and choose Apply resolution. An outside change that holds exactly your unsaved text (often a sync tool delivering Tine's own write back) is not a conflict: Tine accepts it quietly and still saves your edit. The N conflicts page lists such pages under Unsaved drafts.","title":"Reference/Files, external edits, and backups"},{"anchor":"b20","slug":"reference-files-external-edits-and-backups","text":"Prefer to approve even clean external updates yourself? Turn on Settings → Backups & recovery → Always ask before applying an external change. Tine then holds the silent case and offers Reload from disk / Keep mine; changes that already conflict keep their existing safer handling.","title":"Reference/Files, external edits, and backups"},{"anchor":"b21","slug":"reference-files-external-edits-and-backups","text":"Returning to Tine asks the watcher for a fresh pass, covering network mounts, suspended apps, and sync tools that delivered no live filesystem event; typing waits until that pass is in. A large git checkout, fossil update, branch switch, or sync burst is grouped into one external revision instead of interrupting once per page. Changes inside .git/ or Syncthing's .stfolder/ are ignored.","title":"Reference/Files, external edits, and backups"},{"anchor":"b22","slug":"reference-files-external-edits-and-backups","text":"If the system refuses live file notifications (for example the per-user watch limit is reached), Tine says so and checks for external changes every 3 seconds instead, retrying live notifications as it goes.","title":"Reference/Files, external edits, and backups"},{"anchor":"b23","slug":"reference-files-external-edits-and-backups","text":"Files in assets/ are watched too. An image replaced outside Tine — by an editor, Syncthing, Dropbox, or another Tine window — refreshes where it is shown, without reloading the page, and one deleted outside shows its missing-image placeholder. This also covers an assets link to a folder outside the graph that you have approved. An open PDF, audio, or video is not swapped while you use it; it shows the new file the next time you open it.","title":"Reference/Files, external edits, and backups"},{"anchor":"b24","slug":"reference-files-external-edits-and-backups","text":"logseq/config.edn is live too. A change made in Logseq, a text editor, or delivered by a sync provider updates favorites, shortcuts, the home page, journal formats, and other shared settings during the session; reopening the graph is not required. A settings change made in Tine edits only its own entry, and is refused rather than written if config.edn is half-written or not a map, so a file still arriving from a sync provider is never overwritten.","title":"Reference/Files, external edits, and backups"},{"anchor":"b25","slug":"reference-files-external-edits-and-backups","text":"For file sync between devices, run one app at a time on the graph where you can, and let conflict copies (below) catch the rest.","title":"Reference/Files, external edits, and backups"},{"anchor":"b26","slug":"reference-files-external-edits-and-backups","text":"Snapshots — automatic backups","title":"Reference/Files, external edits, and backups"},{"anchor":"b27","slug":"reference-files-external-edits-and-backups","text":"Each time Tine opens your graph it snapshots every Markdown/Org page in the graph — pages and journals, and pages kept in other folders or at the graph root — plus logseq/config.edn and asset .edn sidecars, to a local folder outside the graph, once opening has gone quiet (a few seconds after startup finishes, at most three minutes) so the copy does not compete with your first page. Syncthing never syncs it. Binary assets, folders listed in :hidden, and Tine's own trash and backup folders are not copied.","title":"Reference/Files, external edits, and backups"},{"anchor":"b28","slug":"reference-files-external-edits-and-backups","text":"Settings → Backups & recovery → Snapshots to keep (default 12) controls how many survive; the oldest beyond the count are pruned.","title":"Reference/Files, external edits, and backups"},{"anchor":"b29","slug":"reference-files-external-edits-and-backups","text":"1. Pick a snapshot under Available snapshots and choose Restore, then confirm.","title":"Reference/Files, external edits, and backups"},{"anchor":"b30","slug":"reference-files-external-edits-and-backups","text":"2. What you should see: Tine saves pending edits, snapshots your current state first, restores backed-up graph text to its original paths, restores config and sidecars, and reloads the graph — a mistaken restore is itself reversible. Pages created after the snapshot are moved into the restore's recovery folder under logseq/.tine-trash/, not deleted. A snapshot from an older Tine covers only the pages and journals folders; one made under a different pages or journals folder setting is refused rather than restored into the wrong place.","title":"Reference/Files, external edits, and backups"},{"anchor":"b31","slug":"reference-files-external-edits-and-backups","text":"Trash","title":"Reference/Files, external edits, and backups"},{"anchor":"b32","slug":"reference-files-external-edits-and-backups","text":"Deleting a page or journal moves the file to logseq/.tine-trash/pages/ or logseq/.tine-trash/journals/, not permanent deletion. Its name gains a timestamp followed by __.","title":"Reference/Files, external edits, and backups"},{"anchor":"b33","slug":"reference-files-external-edits-and-backups","text":"Duplicate journal files you trash and unused media from an orphan scan land there too, and discarded sync-conflict copies and a file's pre-resolution version go to logseq/.tine-trash/conflicts/.","title":"Reference/Files, external edits, and backups"},{"anchor":"b34","slug":"reference-files-external-edits-and-backups","text":"To restore something, open the matching typed folder, remove the timestamp and __ from its name, then move it into pages/, journals/, or assets/ with your file manager. Tine picks it up like any external change.","title":"Reference/Files, external edits, and backups"},{"anchor":"b35","slug":"reference-files-external-edits-and-backups","text":"Settings → Files → Orphaned media (Scan for orphans) can find media no block links to (a deleted block keeps its files, so unused media accumulates) and trash it, and Empty asset trash deletes asset trash permanently — page, journal, and conflict recovery files are always kept.","title":"Reference/Files, external edits, and backups"},{"anchor":"b36","slug":"reference-files-external-edits-and-backups","text":"Sync tools and conflict copies","title":"Reference/Files, external edits, and backups"},{"anchor":"b37","slug":"reference-files-external-edits-and-backups","text":"Keep Syncthing or Dropbox on your graph — Tine is built to coexist with them. Two files that resolve to the same journal day are kept, not dropped: the day joins the N conflicts queue, where you fold them block by block on the day itself, and Settings → Backups & recovery → Duplicate journal days offers Open, Merge, Rename, or Trash per file.","title":"Reference/Files, external edits, and backups"},{"anchor":"b38","slug":"reference-files-external-edits-and-backups","text":"A *.sync-conflict-* (or (conflicted copy)) file never appears as a page. Files carrying unresolved git or Fossil merge markers are also quarantined from ordinary saves rather than rewritten.","title":"Reference/Files, external edits, and backups"},{"anchor":"b39","slug":"reference-files-external-edits-and-backups","text":"Both kinds appear in one N conflicts badge in the sidebar. Open a conflicted page to compare the two versions block by block: choose Mine, Theirs, or both for each differing block, accept a suggested Merged version when both sides edited separate parts of one block, then Apply resolution. A pinned notice keeps the review reachable while you scroll: tap it to unroll the review in place. Nothing is auto-merged or auto-deleted.","title":"Reference/Files, external edits, and backups"},{"anchor":"b40","slug":"reference-files-external-edits-and-backups","text":"Choosing the N conflicts badge opens the Conflicts page: every page that needs a decision, grouped by source, with how many blocks are left (\"—\" when not counted). Click a page to resolve it, or shift-click to open it in the right sidebar and keep the list in view. Discard copy moves a provider conflict copy to the trash, including a copy whose page no longer exists.","title":"Reference/Files, external edits, and backups"},{"anchor":"b41","slug":"reference-files-external-edits-and-backups","text":"Journal files named by title","title":"Reference/Files, external edits, and backups"},{"anchor":"b42","slug":"reference-files-external-edits-and-backups","text":"Tine does not silently rename journal files when a graph opens. If an otherwise valid journal uses its display title as its filename (for example Jun 18th, 2026.md), the day may look empty because the filename cannot be matched to its date.","title":"Reference/Files, external edits, and backups"},{"anchor":"b43","slug":"reference-files-external-edits-and-backups","text":"Settings → Backups & recovery → Journal files named by title lists these files. Review the list and choose Rename to date names; Tine takes a snapshot first.","title":"Reference/Files, external edits, and backups"},{"anchor":"b44","slug":"reference-files-external-edits-and-backups","text":"Export","title":"Reference/Files, external edits, and backups"},{"anchor":"b45","slug":"reference-files-external-edits-and-backups","text":"Settings → Graph → Export HTML and read-only app… exports your public:: true pages as a standalone site. Give the export a name and choose a destination folder outside the graph; tick Include every page not marked public:: false to export pages that carry no public:: property as well. A page marked public:: false is never exported, not even with that box ticked or with :publishing/all-pages-public? true in config.edn, and its blocks never appear in another page's embeds, queries or references. A graph with no public:: true page exports 0 pages, and the result line says that only public:: true pages are exported. Nothing is uploaded, and your graph is not touched.","title":"Reference/Files, external edits, and backups"},{"anchor":"b46","slug":"reference-files-external-edits-and-backups","text":"Export… in a query's header exports the pages its results live on as a standalone site. Pages marked public:: false stay out even when the query matches them, and so do their results. Review the page list first; Tine writes the export to published-queries/<folder>/ inside your graph. If that folder exists, choose Replace (the previous export is kept in recovery and its path is reported) or Create a separate export. A query about blocks exports whole pages, not just the matched blocks, and the dialog asks you to confirm that.","title":"Reference/Files, external edits, and backups"},{"anchor":"b47","slug":"reference-files-external-edits-and-backups","text":"Queries inside a query export show only results on the exported pages; they do not report how many results were left out on other pages.","title":"Reference/Files, external edits, and backups"},{"anchor":"b48","slug":"reference-files-external-edits-and-backups","text":"A query export carries referenced local assets in its own assets/ folder, so you can move or share the whole export folder. Missing assets are reported as warnings. Settings → Graph → Query export size limit sets the copied-asset budget for this device (default 1 GiB). An export that exceeds it stops before replacing any previous export, with Adjust limit in Settings… to raise it.","title":"Reference/Files, external edits, and backups"},{"anchor":"b49","slug":"reference-files-external-edits-and-backups","text":"published-queries/ output never becomes graph pages and is excluded from graph backups. Back up an export folder separately if you want to retain it.","title":"Reference/Files, external edits, and backups"},{"anchor":"b50","slug":"reference-files-external-edits-and-backups","text":"Serve an export folder over HTTP (any static host, or python3 -m http.server inside it) to open it as a read-only app; opening index.html straight from disk, or adding ?static to the address, shows the plain static site instead.","title":"Reference/Files, external edits, and backups"},{"anchor":"b51","slug":"reference-files-external-edits-and-backups","text":"Sheets on an exported page (tables, boards and grids) come out as the same tables, boards and grids you see in the app, including formula columns, filters and aggregate footers: Tine computes them with the app's own sheet code before it writes the export, in Export HTML and read-only app…, a query's Export… and Export to PDF… alike. The command-line export (tine export static or tine export live) has no app to compute them, so it writes a sheet as the plain outline of its rows. A sheet that cannot be computed, or that changed while the export was being prepared, is written the same way with a visible note, and the export still succeeds. A table or board that shows a query's results is written the same way — the query's own columns and its rows on the page they came from — when the block holds just that one query; a result on a page the export does not publish is left out of the table (and of its counts and totals), and if the results changed while the export was being prepared the block is written as the query's usual result list instead. A query table's exported totals summarize only the rows it exports, so they can differ from the live footer's totals over the query's complete sample.","title":"Reference/Files, external edits, and backups"},{"anchor":"b52","slug":"reference-files-external-edits-and-backups","text":"If a query exceeds the Print query limit, PDF export names the reason and stops before opening the print dialog. Narrow the query and try again. Starting another PDF export supersedes the pending export; only the latest request may open its printout.","title":"Reference/Files, external edits, and backups"},{"anchor":"b53","slug":"reference-files-external-edits-and-backups","text":"Right-click a page title → Export to PDF… prints one page on a light background. It is offered on desktop only: printing is unavailable inside a mobile WebView, so Android and iOS do not show it. Export HTML and read-only app… works on every platform.","title":"Reference/Files, external edits, and backups"},{"anchor":"b54","slug":"reference-files-external-edits-and-backups","text":"To find HTML export quickly, open the command palette and run Export graph as HTML and read-only app…; it opens the same Graph settings export control. The folder picker starts at your last successful export destination on this device. The result shows the exported site's path; on desktop, Show in folder reveals it in the file manager. Mobile keeps its existing folder picker behaviour and does not offer the desktop reveal action.","title":"Reference/Files, external edits, and backups"},{"anchor":"b55","slug":"reference-files-external-edits-and-backups","text":"Export cleanup removes selected links, tags and emphasis from ordinary text. Text inside inline code and fenced code stays literal in Text, OPML and HTML exports, even when it contains [[links]], #tags or emphasis markers.","title":"Reference/Files, external edits, and backups"},{"anchor":"b56","slug":"reference-files-external-edits-and-backups","text":"Copy / export as… on a block or page offers Plain text (without formatting markers) or Markdown / Org (with formatting preserved), then Text / OPML / HTML destinations with cleanup and depth controls. Markdown, Org, HTML and OPML resolve block references and expand page and block embeds, without adding source captions. Embedded outlines keep their children; expansion stops after five nested embeds. Internal properties such as id:: are hidden. Text exports keep user properties as key:: value unless Remove properties is selected; page properties are omitted.","title":"Reference/Files, external edits, and backups"},{"anchor":"b0","slug":"reference-journals-tasks-and-scheduling","text":"Journals, tasks, and scheduling","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b1","slug":"reference-journals-tasks-and-scheduling","text":"Everything dated lives here: one journal page per day, tasks as plain-text markers at the start of a block, [#A]–[#C] priorities, and SCHEDULED:/DEADLINE: planning lines with calendar pickers. This page maps the shipped behavior; Workflows/Capture and plan your day walks through using it, and Feature showcase shows each construct rendered.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b2","slug":"reference-journals-tasks-and-scheduling","text":"Journals","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b3","slug":"reference-journals-tasks-and-scheduling","text":"A date mentioned by another block appears even without a journal file, at any distance in the past or future. Past days appear in chronological order; unreferenced days without files stay out of the feed. Viewing a fileless day creates no file: typing into its empty body creates it through the usual save path. Upcoming is off by default. Add a block containing {{upcoming}} to the Journal sections page to show referenced future days in a collapsed Upcoming group at that position, nearest first. Expand a day to see its Linked References, or click its title to open the day page. Adding or removing the last mention updates the feed; deleting a journal file keeps its day listed while another block still references it.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b4","slug":"reference-journals-tasks-and-scheduling","text":"The Journals entry in the left sidebar (or g j) opens a multi-day feed — one continuous, editable list, newest day first. Today's journal is always shown at the top of the feed. With no daily template, its file is created lazily on your first edit: the feed shows the day, but no file exists until you type.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b5","slug":"reference-journals-tasks-and-scheduling","text":"\"Today\" follows the calendar of the machine's local time zone as Tine's backend reads it, so today's journal rolls over at local midnight — including when Tine stays open overnight or resumes from sleep — and the Agenda, carry-over and the Go to date calendar all use that same day.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b6","slug":"reference-journals-tasks-and-scheduling","text":"g n and g p step to the next or previous calendar day from the journal you are viewing (from another page they start at today, and they open that day even if it has no file yet). The calendar button in the top bar (Go to date) opens a month grid — days that already have an entry are marked — to jump to any day's journal.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b7","slug":"reference-journals-tasks-and-scheduling","text":"Linked References appears beneath each day in the Journals feed when other blocks link to that journal, with a count and the same filter, expand, and edit controls as an individually opened page. References load as you scroll to the day. Empty sections stay hidden; the graph’s linked-reference collapse threshold controls whether they start folded.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b8","slug":"reference-journals-tasks-and-scheduling","text":"Settings → Journals → Journal date format controls the display titles and how new [[date]] titles are written (saved to :journal/page-title-format, traveling with the graph). The choices match Logseq’s built-in formats, including weekday and yyyy年MM月dd日 titles. E, EE, and EEE show abbreviated weekdays (such as Fri); EEEE shows the full name (Friday). Graphs using the older :date-formatter setting are also supported: :journal/page-title-format takes precedence when both are present, and opening a graph keeps the legacy setting untouched. It renames no files: journal file names are untouched and existing journals keep working. If some journal files are named after their title instead of their date, their days look empty; Settings → Backups & recovery lists them under Journal files named by title with a Rename to date names button, which never runs on its own. For files, duplicate days, and the on-disk layout in general, see Reference/Files, external edits, and backups.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b9","slug":"reference-journals-tasks-and-scheduling","text":"Settings → Journals → New-journal template inserts a template into each new day (:default-templates {:journals …} in config.edn); “(none)” means blank days, the default. Make a template from a block's right-click menu (Make a template…). A page can be a template too: put template:: Name among the page's own property lines at its top (the lines before the first bullet), and /Name inserts those property lines (without template::) as one block, as in Logseq.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b10","slug":"reference-journals-tasks-and-scheduling","text":"Task markers","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b11","slug":"reference-journals-tasks-and-scheduling","text":"For a checklist inside one block, put * [ ] item on a continuation line with Shift+Enter (use + [ ] item in Org). Click its checkbox to tick just that item without opening the editor. Nested checklist items use the same indent step as child blocks. Collapsing the block hides child blocks; its own inline checklist stays visible, matching Logseq's default.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b12","slug":"reference-journals-tasks-and-scheduling","text":"The marker set is TODO, DOING, NOW, LATER, WAITING, WAIT, STARTED, IN-PROGRESS, DONE, CANCELED, CANCELLED — stored as the plain first word of the block's first line, like Logseq.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b13","slug":"reference-journals-tasks-and-scheduling","text":"Settings → Journals → Task workflow chooses between two cycling lanes, TODO / DOING and NOW / LATER (:preferred-workflow, traveling with the graph); NOW / LATER is the default.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b14","slug":"reference-journals-tasks-and-scheduling","text":"Click the marker chip for Logseq's two-state toggle: TODO ↔ DOING or LATER ↔ NOW (a chip click never clears DONE). Ctrl+Enter (Cmd on Mac) uses the full keyboard cycle TODO → DOING → DONE → none, or LATER → NOW → DONE → none, applied to every selected task when several blocks are selected.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b15","slug":"reference-journals-tasks-and-scheduling","text":"Every open task also shows a checkbox in front of it: click to mark DONE, click again to reopen to the workflow's open marker (TODO or LATER). DONE shows a checked box; CANCELED/CANCELLED show none. The same live checkbox edits the source block inside query results, linked references, embeds, and inline ((block references)): ticking it there completes the referenced task on its own page.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b16","slug":"reference-journals-tasks-and-scheduling","text":"Queries filter on markers with a task clause, e.g. (task TODO DOING) in {{query }}, or as a Task condition in the visual query builder.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b17","slug":"reference-journals-tasks-and-scheduling","text":"Priorities","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b18","slug":"reference-journals-tasks-and-scheduling","text":"[#A], [#B], [#C] sit directly after the task marker; a block without a task marker can carry one too. Type slash, choose Priority A (or B, C), and the chip updates in place.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b19","slug":"reference-journals-tasks-and-scheduling","text":"Queries can filter on priority with a (priority A) clause; the Feature showcase shows the constructs rendered.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b20","slug":"reference-journals-tasks-and-scheduling","text":"Scheduled and deadline dates","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b21","slug":"reference-journals-tasks-and-scheduling","text":"A block's plan is a SCHEDULED: and/or DEADLINE: line with an Org-style timestamp <2026-07-07 Tue>, optionally with a clock time <2026-07-07 Tue 14:30>. Convention: use SCHEDULED for the day you intend to work on something, DEADLINE for the day it must be done.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b22","slug":"reference-journals-tasks-and-scheduling","text":"While editing, type / and choose Scheduled or Deadline. Click a day to select it, then optionally use + Add time for HH:mm and the repeat menu (No repeat / Daily / Weekly / Monthly / Yearly, with from completion). Done or clicking outside applies the chosen date, time, and repeat together. Escape cancels all pending changes and returns to the editor at the same caret. The calendar takes keyboard focus: Left/Right move one day, Up/Down move one week, and Enter applies the focused day (or the chosen date when entering a time). Its first weekday follows Settings → Journals → First day of week. Today selects today; Clear removes an existing date. The block gains a calendar date chip — click it to edit the date, time, or repeat with the same Done/outside/Escape rules.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b23","slug":"reference-journals-tasks-and-scheduling","text":"/Date picker opens the same calendar to insert a [[date]] link at the cursor in your graph's journal title format. Choose a day, then use Done, Enter, or click outside to insert it; Escape cancels. /Today, /Tomorrow, and /Yesterday insert the corresponding journal date directly; /That day inserts the containing journal's date.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b24","slug":"reference-journals-tasks-and-scheduling","text":"You may also type a planning line anywhere in the block: on leaving the editor it moves to its canonical spot — right after the first line, before any properties, SCHEDULED before DEADLINE — like Logseq. A SCHEDULED: inside inline code or a code fence stays literal content and is never moved.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b25","slug":"reference-journals-tasks-and-scheduling","text":"The same chips and pickers appear wherever the block does — in linked references, query results, and embeds.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b26","slug":"reference-journals-tasks-and-scheduling","text":"Agenda","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b27","slug":"reference-journals-tasks-and-scheduling","text":"Today's journal ends with a Scheduled & Deadline list of open items whose date falls inside the Agenda window — by default 7 days back and 7 ahead. Settings → Journals → Agenda window adjusts both on this device; :scheduled/future-days in logseq/config.edn, when set, controls days ahead for the whole graph instead. The list disappears when nothing matches. Set :feature/disable-scheduled-and-deadline-query? true to hide it.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b28","slug":"reference-journals-tasks-and-scheduling","text":":default-queries {:journals [...]} adds queries beneath today's blocks, before the agenda, in the order written. Each uses the same query renderer as a query block; a failing or unsupported query shows its own error while its neighbours remain usable, and a query with no results shows nothing, as in Logseq. String titles and static text in hiccup vectors appear as plain text. :collapsed? true starts a query folded. Config edits apply live; malformed journal settings show a config diagnostic. Graph code is never executed; supported advanced query shapes match Reference/Queries.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b29","slug":"reference-journals-tasks-and-scheduling","text":"Logseq's stock NOW query lists recent journal tasks in priority order, with missing priorities last. NEXT also supports older saved configurations that list NOW, LATER and TODO tasks directly referencing a journal day strictly after today and strictly before 14 days ahead. A reference on a parent block does not include its children. The 0.10.9 default instead selects tasks on journal pages strictly between today and 7 days ahead. Unsupported config queries show their title and a plain explanation; expand Technical details to inspect the clauses and source.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b30","slug":"reference-journals-tasks-and-scheduling","text":"Today's sections page. To choose what shows under today's journal without editing config.edn, hover today's journal and click Customize today's sections…. Tine creates a page named Journal sections (marked tine/journal-sections:: true) holding your current sections: each :default-queries entry as a #+BEGIN_QUERY block, then the Scheduled & Deadline agenda as a query block. The generated page does not include Upcoming. Today's journal shows query blocks and the Upcoming macro in outline order, including nested blocks; reorder, edit, delete or add them like on any page, and the change shows on today's journal at once. Supported sections are {{query …}}, {{tine-query …}}, #+BEGIN_QUERY blocks, the agenda query seeded by Customize, and {{upcoming}}. Other text on the page is just notes. The page can be renamed; the marker is what counts. Delete the page, or set the marker to false, to go back to config.edn, with Upcoming hidden. Logseq ignores the page and keeps using :default-queries, and Tine never writes to config.edn for this. While the page exists, the Agenda window setting no longer applies: edit the agenda query on the page instead. The small header on this page opens this Guide in the right sidebar. On ordinary pages, {{upcoming}} remains an unknown macro.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b31","slug":"reference-journals-tasks-and-scheduling","text":"To add Upcoming, copy this as a block on the sections page: {{upcoming}}","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b32","slug":"reference-journals-tasks-and-scheduling","text":"Add these entries inside the existing config map (use false to keep the built-in agenda): :feature/disable-scheduled-and-deadline-query? false :scheduled/future-days 7 :default-queries {:journals [{:title \"Priority A tasks\" :query (and (task TODO DOING) (priority A)) :collapsed? false} {:title [:span \"Open tasks\"] :query [:find (pull ?b [*]) :where [?b :block/marker \"TODO\"]] :inputs [] :collapsed? true}]}","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b33","slug":"reference-journals-tasks-and-scheduling","text":"Keyed off the scheduled/deadline date itself, not the page's journal day, over the whole graph: an unfinished item on an old page still shows while its date is in range. A saved equivalent uses Tine's query language: {{tine-query @block (scheduled between '-7d' and '+7d' or deadline between '-7d' and '+7d') and not task in ('DONE', 'CANCELED', 'CANCELLED')}}. OG Logseq's simple query language has no scheduled/deadline window condition.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b34","slug":"reference-journals-tasks-and-scheduling","text":"Finished tasks (DONE, CANCELED, CANCELLED) never appear, matching Logseq.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b35","slug":"reference-journals-tasks-and-scheduling","text":"Time tracking and the logbook","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b36","slug":"reference-journals-tasks-and-scheduling","text":"With Settings → Journals → Time tracking on (the default), moving into DOING / NOW records a clock-in and moving back to TODO / LATER or into DONE records a clock-out, as OG-compatible :LOGBOOK: CLOCK: rows (seconds on by default via :logbook/settings). Saved to :feature/enable-timetracking?.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b37","slug":"reference-journals-tasks-and-scheduling","text":"Blocks with clock rows show a small elapsed-time badge with a Type / Start / End / Span tooltip; the :LOGBOOK: drawer itself stays hidden by default, like Logseq.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b38","slug":"reference-journals-tasks-and-scheduling","text":"Toggled off, markers change without writing log rows.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b39","slug":"reference-journals-tasks-and-scheduling","text":"Repeating tasks","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b40","slug":"reference-journals-tasks-and-scheduling","text":"Put a repeater inside the timestamp, e.g. <2026-07-07 Tue +1w> (or pick one in the calendar popup); the units are d, w, m, y for days, weeks, months, years.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b41","slug":"reference-journals-tasks-and-scheduling","text":"Marking a repeating task done does not close it: the date advances to the next occurrence and the marker resets to the workflow's open state (TODO, or LATER under NOW / LATER). This works from the checkbox, the marker chip, and Ctrl+Enter.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b42","slug":"reference-journals-tasks-and-scheduling","text":"A timed repeater such as <2026-09-30 Wed 09:00 +1w> advances to the next date while keeping 09:00; the date picker keeps that time and repeater when you re-pick its date.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b43","slug":"reference-journals-tasks-and-scheduling","text":"+1w advances from the stored date; .+1w counts from the day you complete it; ++1w skips missed occurrences, landing past today. The repeater survives date re-picks in the calendar.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b44","slug":"reference-journals-tasks-and-scheduling","text":"Carry-over","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b45","slug":"reference-journals-tasks-and-scheduling","text":"In the feed and on a journal page, hover the day's title row or focus a title-row control with the keyboard to reveal the carry buttons. On touch devices without hover they stay visible.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b46","slug":"reference-journals-tasks-and-scheduling","text":"On a past day, Carry unfinished tasks → today moves its open tasks (every marker except DONE / CANCELED / CANCELLED) to today. On today, Carry from previous day pulls from the most recent day that has content and Carry last N days goes further back. The same action is on a past journal day's right-click menu, and the command palette (Ctrl+Shift+P) has last-7 / 30 / 365-day presets.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b47","slug":"reference-journals-tasks-and-scheduling","text":"Settings → Journals tunes it: Show carry-over buttons, Carry-over keeps context (on: move whole blocks that contain an open task; off: pull out just the task), Carry-over header (add a “Carried over” heading), and Carry “last N days”.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b48","slug":"reference-journals-tasks-and-scheduling","text":"Settings quick map","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b49","slug":"reference-journals-tasks-and-scheduling","text":"Settings → Journals collects every control above: Journal date format, First day of week, the carry-over controls, Task workflow, Time tracking, New-journal template, and Agenda window. For the ones in use, see Workflows/Capture and plan your day.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b0","slug":"reference-pages-links-references-and-search","text":"Pages, links, references, and search","title":"Reference/Pages, links, references, and search"},{"anchor":"b1","slug":"reference-pages-links-references-and-search","text":"The precise rules behind the moving parts: pages and aliases, links and tags, block references and embeds, the two reference panels on every page, and every search surface from the switcher to the saved-search page. Workflows/Find and revisit walks through using them in order; Feature showcase shows each construct rendered.","title":"Reference/Pages, links, references, and search"},{"anchor":"b2","slug":"reference-pages-links-references-and-search","text":"Pages and namespaces","title":"Reference/Pages, links, references, and search"},{"anchor":"b3","slug":"reference-pages-links-references-and-search","text":"With a Chinese IME, type 【【 for [[]] or （（ for (()): the caret lands inside the ASCII reference and the usual page or block search becomes active. Conversion waits until composition finishes, so it does not interrupt choosing a character. Typing 【 or （ around selected text wraps it with ASCII brackets or parentheses; a second opener makes a reference. At the start of a line, 《〈 becomes < and opens the block command menu.","title":"Reference/Pages, links, references, and search"},{"anchor":"b4","slug":"reference-pages-links-references-and-search","text":"A page is any name you link to. Type [[ while editing and completion offers existing pages and their aliases; an alias row is labelled alias of its page, so you can tell it from an ordinary page with a similar name. Whether Enter prefers the strongest existing match or exactly what you typed is Settings → Editor → Advanced → Link autocomplete default (OG adaptive, Prefer existing, Prefer exactly what I typed), and an exact existing name always selects the existing page.","title":"Reference/Pages, links, references, and search"},{"anchor":"b5","slug":"reference-pages-links-references-and-search","text":"A page link whose page does not exist yet renders in a dimmed link color with a dotted underline, still readable and still clearly a link. It still works — opening it lets you create the page. Tags are never dimmed, because most tags in a normal graph have no page of their own. Tine marks the difference on purpose; Logseq only dims untitled pages.","title":"Reference/Pages, links, references, and search"},{"anchor":"b6","slug":"reference-pages-links-references-and-search","text":"A link to the web or to a file is underlined with a solid line, as in Logseq; a link to a page has no underline, and a block reference is underlined in the link color. Each kind has its own CSS class, and the underline and the missing-page color are --tine-* tokens, so your custom.css can restyle them: see Workflows/Customize Tine's look.","title":"Reference/Pages, links, references, and search"},{"anchor":"b7","slug":"reference-pages-links-references-and-search","text":"A page with an icon:: property (an emoji, such as icon:: 🏁) shows it on its title, in links to it, and in front of its name in the sidebar's Favorites, Recent and All pages lists and in the right sidebar. A favorite without an icon keeps the star. The icon:: property stays visible in the page-properties block; click its row to edit it.","title":"Reference/Pages, links, references, and search"},{"anchor":"b8","slug":"reference-pages-links-references-and-search","text":"To set an icon without knowing the property syntax, open Page actions (the ⋯ beside the title), then Set page icon… below Page properties…. Enter an emoji or short text such as AB, then press Enter or Save icon. On Windows, Win + . opens the native emoji picker; on macOS, use Control + Command + Space. Remove page icon clears it. Icons in the sidebar lists follow edits immediately, including external file changes. Markdown stores icon::; Org stores #+icon: through the same page-property editor.","title":"Reference/Pages, links, references, and search"},{"anchor":"b9","slug":"reference-pages-links-references-and-search","text":"Page names ignore letter case: [[foo]] and [[Foo]] open one page. On a case-insensitive disk that page opens under the spelling its file already has, so a differently cased link never creates a second page.","title":"Reference/Pages, links, references, and search"},{"anchor":"b10","slug":"reference-pages-links-references-and-search","text":"A link to a page that does not exist yet is not broken — opening it gives you an empty page, and its file is written only when you first type something into it.","title":"Reference/Pages, links, references, and search"},{"anchor":"b11","slug":"reference-pages-links-references-and-search","text":"A name with slashes, like Project/Roadmap, is a namespace: it nests under Project in the sidebar's collapsible namespace tree, and a namespaced page gains an automatic Hierarchy section listing its descendant pages.","title":"Reference/Pages, links, references, and search"},{"anchor":"b12","slug":"reference-pages-links-references-and-search","text":"Journals are pages too — one per day, reachable from Journals in the sidebar. Their formats, templates, tasks, and agenda are mapped in Reference/Journals, tasks, and scheduling.","title":"Reference/Pages, links, references, and search"},{"anchor":"b13","slug":"reference-pages-links-references-and-search","text":"The application chrome — toolbar, sidebars, buttons — is not text-selectable, so a stray drag never starts a selection there; page content and editors stay selectable.","title":"Reference/Pages, links, references, and search"},{"anchor":"b14","slug":"reference-pages-links-references-and-search","text":"Links and tags","title":"Reference/Pages, links, references, and search"},{"anchor":"b15","slug":"reference-pages-links-references-and-search","text":"[[Page]] links and #tag tags run on the same machinery: a tag links and collects references like any page, and a tag with no page of its own is perfectly normal. A page's tags:: property values render as navigable links too.","title":"Reference/Pages, links, references, and search"},{"anchor":"b16","slug":"reference-pages-links-references-and-search","text":"A labelled page link such as read the welcome shows your words while opening the page. External [label](https://…) links are ordinary Markdown, bare URLs and emails autolink, and Mod+L inserts a link around the selection. http, https and mailto links open in your browser or mail app. A file: link — [Test](file:///home/you/report.odt), or [Test](file://D:\\test.txt) on Windows — opens that file or folder in whatever application your system uses for it, on desktop; a file that is no longer there is reported instead of doing nothing. A file path is read from the graph folder, from any page or journal: [report](files/report.pdf) opens files/report.pdf inside the graph, while [report](../files/report.pdf) opens a file in the sibling files folder outside the graph. Parent steps such as ../../ are preserved. Absolute paths such as /home/you/report.pdf and D:\\notes\\report.pdf also open through the same desktop file opener as file: links. These links look ordinary and show the resolved path on hover. Use [spaced](<../files/my file.txt>) for spaces. Links into the graph's assets folder keep Logseq's established graph asset route. Opening local files is available on desktop only, including for file: URLs; Android and iOS report the refusal. Tine does not rewrite links when you move files or graphs. A link to another app, such as zotero://…, obsidian://… or shortcuts://… on iOS, first asks whether to open it, showing the whole link, and then opens it in that app. javascript: and data: links never open.","title":"Reference/Pages, links, references, and search"},{"anchor":"b17","slug":"reference-pages-links-references-and-search","text":"Click a link to follow it. Shift+click opens it in the right sidebar, Ctrl/Cmd+click opens it in the other pane, and middle-click opens it in a background tab. While editing, Ctrl+O opens the link at the caret and Ctrl+Shift+O opens it in the right sidebar — matching Logseq's shortcuts, no mouse needed.","title":"Reference/Pages, links, references, and search"},{"anchor":"b18","slug":"reference-pages-links-references-and-search","text":"Aliases","title":"Reference/Pages, links, references, and search"},{"anchor":"b19","slug":"reference-pages-links-references-and-search","text":"Put alias:: Another name, Third name among the page properties at the top of a page — as Feature showcase does with alias:: Kitchen sink (features) — and links under those names land on the same page.","title":"Reference/Pages, links, references, and search"},{"anchor":"b20","slug":"reference-pages-links-references-and-search","text":"The page then shows aka chips for every name it answers to (\"Also known as — other names that link here\"); click one to edit the header. The raw alias:: property stays out of the under-title property list.","title":"Reference/Pages, links, references, and search"},{"anchor":"b21","slug":"reference-pages-links-references-and-search","text":"Page and block properties","title":"Reference/Pages, links, references, and search"},{"anchor":"b22","slug":"reference-pages-links-references-and-search","text":"Rendered block properties use a separate row for each key; click the key to open its page. The earliest property group supplies the display, with the last value for a repeated key. Later groups remain in the file even when they are not displayed.","title":"Reference/Pages, links, references, and search"},{"anchor":"b23","slug":"reference-pages-links-references-and-search","text":"Properties are the key:: value lines at the top of a page and under a block's first line, and every one of them is editable from a form — not only by typing raw lines. Click Page actions beside a page's title (or right-click the title) and choose Page properties…, or type /page properties while editing; right-click a block for Properties…. The form lists the properties that page or block really has.","title":"Reference/Pages, links, references, and search"},{"anchor":"b24","slug":"reference-pages-links-references-and-search","text":"A page's form always offers Aliases, Tags, Display title, Icon and Public, even when the page has none of them yet. Every other property the page carries follows, each under its own key and each removable outright. Add a property takes any key you like.","title":"Reference/Pages, links, references, and search"},{"anchor":"b25","slug":"reference-pages-links-references-and-search","text":"Machine-managed properties stay out of the form: id:: and collapsed:: are never listed, and the tine. keys behind Sheets and saved searches are edited from those surfaces instead.","title":"Reference/Pages, links, references, and search"},{"anchor":"b26","slug":"reference-pages-links-references-and-search","text":"Each property is written in the form its own file uses. A Markdown page gets key:: value; an Org page gets a #+key: value file directive, and an Org block its :PROPERTIES: drawer — the shapes Logseq itself reads back.","title":"Reference/Pages, links, references, and search"},{"anchor":"b27","slug":"reference-pages-links-references-and-search","text":"A key does not have to be plain ASCII. klíč:: hodnota is an ordinary property: it can be added, changed, and removed again like any other.","title":"Reference/Pages, links, references, and search"},{"anchor":"b28","slug":"reference-pages-links-references-and-search","text":"A read-only page — a bundled Guide page — offers no property editing at all, rather than a form whose writes would be dropped.","title":"Reference/Pages, links, references, and search"},{"anchor":"b29","slug":"reference-pages-links-references-and-search","text":"Block references and embeds","title":"Reference/Pages, links, references, and search"},{"anchor":"b30","slug":"reference-pages-links-references-and-search","text":"Page and block menus keep reference, embed and link copying under Copy as ▸. Open that submenu to choose the form you need.","title":"Reference/Pages, links, references, and search"},{"anchor":"b31","slug":"reference-pages-links-references-and-search","text":"Settings → Editor → Click a block reference to zoom in makes a plain reference click zoom into its source block, including on another page.","title":"Reference/Pages, links, references, and search"},{"anchor":"b32","slug":"reference-pages-links-references-and-search","text":"Fold a page embed with the host bullet's arrow or the ordinary Collapse/Expand keyboard commands. Only its page-name line remains; expanding restores its content. The choice is saved on the host block, never the embedded page. If the host has children, the same fold hides those too. This works in the main pane and right sidebar.","title":"Reference/Pages, links, references, and search"},{"anchor":"b33","slug":"reference-pages-links-references-and-search","text":"Hover a page link or block reference for a read-only preview. An alias shows its source page's title and page properties. Click the title to open that page in a new tab, a block bullet to open that block in a new tab, or Open source to open the preview's source. These actions switch to the new tab. The preview stays open while its … → Page actions menu is open. Editing requires opening the source.","title":"Reference/Pages, links, references, and search"},{"anchor":"b34","slug":"reference-pages-links-references-and-search","text":"A context menu's Open in new tab keeps your current tab active and confirms Opened in a new tab. Phones and tablets have no tab strip, so their menus omit Open in new tab and offer Open in sidebar; Ctrl/Cmd-click and middle-click there open the link in place.","title":"Reference/Pages, links, references, and search"},{"anchor":"b35","slug":"reference-pages-links-references-and-search","text":"Settings → Appearance → Advanced → Fine-tuning → Block embed breadcrumbs optionally shows the source page and parent trail above a block embed. It starts off and is saved on this device.","title":"Reference/Pages, links, references, and search"},{"anchor":"b36","slug":"reference-pages-links-references-and-search","text":"A block embed has a subtle shaded background in both light and dark themes, so you can distinguish the embedded occurrence from an ordinary block.","title":"Reference/Pages, links, references, and search"},{"anchor":"b37","slug":"reference-pages-links-references-and-search","text":"Type (( while editing: the popup searches blocks, and choosing one inserts a durable ((reference)). Tine first writes a stable id:: on the source block, so the reference survives renames, reloads, and restarts.","title":"Reference/Pages, links, references, and search"},{"anchor":"b38","slug":"reference-pages-links-references-and-search","text":"The reference renders as a link-styled copy of the source text and stays in sync: edit the source and every reference updates. A referenced task keeps its marker and checkbox; tick the checkbox inside the reference to complete or reopen the source task. A per-block reference-count badge reveals the referencing blocks.","title":"Reference/Pages, links, references, and search"},{"anchor":"b39","slug":"reference-pages-links-references-and-search","text":"Deleting referenced blocks or merging them with Backspace/Delete shows a notice about references that broke or now point to the surviving block, with Undo to restore the blocks and their ids.","title":"Reference/Pages, links, references, and search"},{"anchor":"b40","slug":"reference-pages-links-references-and-search","text":"Click a reference to go to the block; Shift+click opens it in the right sidebar and Ctrl/Cmd+click in the other pane. Right-click an inline reference for Open in sidebar, Go to block, Copy block ref, and Copy block embed; with nothing selected, Mod+C copies a reference to the block you're editing and Mod+Shift+C copies an embed.","title":"Reference/Pages, links, references, and search"},{"anchor":"b41","slug":"reference-pages-links-references-and-search","text":"{{embed [[Page]]}} and {{embed ((id))}} inline a whole page or a block with its context. A page embed's bullet row carries the page's name as a link (with a page glyph), and the page's blocks sit one indent step below it, on the same outline grid as ordinary children, under an accent-colored guide. Embeds are live editing surfaces: edit inside an embed and the source changes. A block embed follows its source's fold state live; folding the embedded block inside one embed is remembered by that embed alone (as a collapsed:: property on the block holding the {{embed}}), never on the source or on another embed of it. When a block contains only a block embed, drag its visible root bullet to move the embed on the host page; clicking that bullet still zooms into the source block. Move block up/down on an embed's top block moves the source block among its own siblings, as in Logseq; since the embed looks the same afterwards, a short notice says which page it moved in, with Show to open it there. The same notice appears when a move from Linked References or a query result takes the block out of what that panel shows.","title":"Reference/Pages, links, references, and search"},{"anchor":"b42","slug":"reference-pages-links-references-and-search","text":"The reference panels on every page","title":"Reference/Pages, links, references, and search"},{"anchor":"b43","slug":"reference-pages-links-references-and-search","text":"Pages tagged with \"X\" appears on page X before Linked References when other pages include X in their page-level tags:: property. It lists the tagged pages as links and can be folded. Inline block tags still belong to Linked References.","title":"Reference/Pages, links, references, and search"},{"anchor":"b44","slug":"reference-pages-links-references-and-search","text":"Linked References sits at the bottom of the page (and of a page opened in the right sidebar): every block that links here, grouped by source page, with a count in its header. It's live — edit in place. A page that links here from its page properties (such as tags::) is listed as its properties row; click the row to fix a property name or value right there, as you would on that page. The funnel button opens a filter: a Search reference text box, a Clear button, an \"N of M references\" count, and page/tag chips, listed alphabetically with their counts, that cycle include → exclude → off (hover a chip for the reminder).","title":"Reference/Pages, links, references, and search"},{"anchor":"b45","slug":"reference-pages-links-references-and-search","text":"A page and its aliases share one chip labelled with the page's canonical name. Its count is the number of reference blocks using that page or any alias; a block using two aliases counts once. Include or exclude applies to every alias. As in Logseq, a reference must carry every included chip and none of the excluded ones. Linked References saves these choices in the page's Logseq-compatible filters:: property; an older filter naming an alias selects the same canonical chip. Unlinked References shares the alias chips but keeps its choices on this device.","title":"Reference/Pages, links, references, and search"},{"anchor":"b46","slug":"reference-pages-links-references-and-search","text":"One bulk button folds every group at once: it shows Expand all if any group is folded, otherwise Collapse all. Each group has its own disclosure. The block reference-count panel uses the same toggle.","title":"Reference/Pages, links, references, and search"},{"anchor":"b47","slug":"reference-pages-links-references-and-search","text":"A page with a lot of backlinks opens its Linked References folded, so the outline stays reachable. Logseq's :ref/linked-references-collapsed-threshold in config.edn sets where \"a lot\" starts (Logseq's default is 100); set it to 0 if you would rather every page start folded and open the panel yourself.","title":"Reference/Pages, links, references, and search"},{"anchor":"b48","slug":"reference-pages-links-references-and-search","text":"Unlinked References, folded by default: plain-text mentions of the page title that were never linked — the fastest way to find where a name was written without brackets. Each mention is highlighted inside its excerpt, and the highlight is clickable: it opens the source page with that exact mention selected, ready to link or edit. Show full block / Show excerpt toggles the whole block and marks every mention; a block whose mentions do not all fit the excerpt also gets a numbered jump row. The block's bullet opens the source block (Shift+click: right sidebar, Ctrl/Cmd+click: new tab, Alt+click: other pane).","title":"Reference/Pages, links, references, and search"},{"anchor":"b49","slug":"reference-pages-links-references-and-search","text":"Both panels have their own Copy / export action. The currently visible entries start selected; uncheck any you do not need, then export the selected blocks grouped by source page as Text, OPML, or HTML. Linked References exports its filtered set, and ordinary page export remains separate.","title":"Reference/Pages, links, references, and search"},{"anchor":"b50","slug":"reference-pages-links-references-and-search","text":"Hover previews show surrounding context without leaving the page.","title":"Reference/Pages, links, references, and search"},{"anchor":"b51","slug":"reference-pages-links-references-and-search","text":"Finding things","title":"Reference/Pages, links, references, and search"},{"anchor":"b52","slug":"reference-pages-links-references-and-search","text":"Ctrl+K, the quick switcher, searches page titles plus the visible text of blocks. Sections are Pages, Create, Commands, Blocks and — inside a page — Current page; with an empty query it lists recent pages. Enter opens the highlighted result; Shift+Enter opens it in the right sidebar; Ctrl/Cmd+Enter opens it in a background tab and keeps the switcher open; Alt+Enter opens it in another pane; middle-click opens a background tab. Load more results… appears when more are available.","title":"Reference/Pages, links, references, and search"},{"anchor":"b53","slug":"reference-pages-links-references-and-search","text":"Ctrl+Shift+K searches only the open page's blocks. Mod+F searches all open main and split panes and expanded right-sidebar items, in pane order then sidebar stack order. The in-page find bar offers next (Enter) / previous (Shift+Enter) and a \"1 / N\" count; folded branches are expanded before the match is highlighted, and the match itself is scrolled into view even inside a block taller than the window.","title":"Reference/Pages, links, references, and search"},{"anchor":"b54","slug":"reference-pages-links-references-and-search","text":"Find and replace. The arrow at the left of the find bar opens a Replace with row. Replace (or Enter in that field) changes the highlighted match and moves to the next; Replace all (or Ctrl/Cmd+Enter) changes every match on the page you opened Find in — not the right sidebar, query results or other pages — as one Undo step. Matching ignores case and accents exactly as Find does. It edits the text you see, as typing would: a link's address and hidden properties such as id:: are never changed, and a match Tine cannot tie to editable text (inside a link's markup, say) is left alone and counted in the message. On a phone, open Find from the page's ⋯ menu → Find in page.","title":"Reference/Pages, links, references, and search"},{"anchor":"b55","slug":"reference-pages-links-references-and-search","text":"The five Search syntax forms, listed in the switcher footer: foo bar (both terms), foo OR bar (either), foo -draft (exclude), \"exact phrase\", and /[A-Z]{3}/ (case-sensitive regular expression).","title":"Reference/Pages, links, references, and search"},{"anchor":"b56","slug":"reference-pages-links-references-and-search","text":"Title matches rank exact, then prefix, then substring, then fuzzy, with block text after them. After you deliberately open the same result more than once for a query, it may break ties among equally strong matches; that history stays on this device, and Settings → Editor → Advanced → Learn Ctrl+K choices disables it, with Reset ranking to clear it.","title":"Reference/Pages, links, references, and search"},{"anchor":"b57","slug":"reference-pages-links-references-and-search","text":"Search ignores accent marks and compatibility-width differences as well as case, so cafe finds café, lodz finds Łódź and Tine finds Ｔｉｎｅ. Set :feature/enable-search-remove-accents? false in config.edn to turn that off. Marks that make a different letter still count: か does not find が, и does not find й, and क does not find कु; елка finds ёлка. Page identity stays narrower: those spellings may still be separate pages.","title":"Reference/Pages, links, references, and search"},{"anchor":"b58","slug":"reference-pages-links-references-and-search","text":"Search scans your loaded graph text directly, so results are always current with your own edits; while it works the switcher says Searching…, an empty answer says No matched results, and More matches exist — narrow your query to see them. means the list was cut short.","title":"Reference/Pages, links, references, and search"},{"anchor":"b59","slug":"reference-pages-links-references-and-search","text":"To find Chinese page titles or aliases without changing your input method, enable Settings → Editor → Advanced → Match Chinese page names by Pinyin. In Ctrl+K or [[ completion, beijing, bei jing or bj finds 北京. Native name matches always come first; block text is not transliterated. This device preference defaults on for a Chinese UI or system language, otherwise off; Reset Pinyin matching to language default restores that default. Turning it off refreshes open Ctrl+K results immediately.","title":"Reference/Pages, links, references, and search"},{"anchor":"b60","slug":"reference-pages-links-references-and-search","text":"Mandarin matching uses one default dictionary reading per character, so polyphonic names may need that reading (重慶 uses zhongqing). Traditional characters also work. Japanese kanji receive Mandarin readings (東京 matches dongjing, not tokyo). Names sharing Pinyin remain separate results in a stable order.","title":"Reference/Pages, links, references, and search"},{"anchor":"b61","slug":"reference-pages-links-references-and-search","text":"Search tabs and saved searches","title":"Reference/Pages, links, references, and search"},{"anchor":"b62","slug":"reference-pages-links-references-and-search","text":"From the search box, press ArrowDown to highlight the first result. ArrowUp / ArrowDown move through page and block results and scroll the highlighted row into view. Enter opens it in a new tab; Shift+Enter opens the right sidebar, Ctrl/Cmd+Enter opens a background tab, and Alt+Enter opens another pane. ArrowUp on the first result returns to the search box, so you can keep typing; the list does not wrap around at either end.","title":"Reference/Pages, links, references, and search"},{"anchor":"b63","slug":"reference-pages-links-references-and-search","text":"Open search tab in the switcher footer turns the current search into a graph-scoped search tab titled \"Search: …\" with its own search box. The tab survives restarts and writes nothing to your graph until you name it. Clicking a result opens a new tab and keeps Search unchanged. Middle-click or Ctrl/Cmd-click opens a background tab; Shift-click opens the right sidebar and Alt-click opens another pane. Page results offer the same right-click menu as the switcher.","title":"Reference/Pages, links, references, and search"},{"anchor":"b64","slug":"reference-pages-links-references-and-search","text":"Search / List / Table / Board are presentations of one result membership: switching the view never changes which blocks matched. Filters / Advanced narrows by friendly fields — all words, any words, an exact phrase, excluded words, a regular expression — and Edit as visual query opens the row-by-row builder; Explain query shows what Tine understood. Choosing blocks and choosing a presentation are separate steps — see Workflows/Structure repeated information for that split in action.","title":"Reference/Pages, links, references, and search"},{"anchor":"b65","slug":"reference-pages-links-references-and-search","text":"A text search returns pages and blocks, shown as two sections in that order, each with its own count and its own display control (Display pages for the pages, Display for the blocks). An empty section says No matching pages. or No matching blocks. rather than hiding.","title":"Reference/Pages, links, references, and search"},{"anchor":"b66","slug":"reference-pages-links-references-and-search","text":"Pages match takes three values: Names and aliases (the default — exact, prefix, substring, fuzzy and regular-expression matching, not exact equality only), Block content (a page counts when one of its own blocks matches the same search), and Names or content (the union). It changes page membership only; the Blocks section evaluates the same block search either way. The choice is saved as tine.page-match-scope.","title":"Reference/Pages, links, references, and search"},{"anchor":"b67","slug":"reference-pages-links-references-and-search","text":"The Display panel offers View, Group by, Sort, Columns, Summarize (count, sum, average) and Sample, then Done.","title":"Reference/Pages, links, references, and search"},{"anchor":"b68","slug":"reference-pages-links-references-and-search","text":"Naming a search tab — typing into \"Name this search to save it as a page\" and pressing Save page — creates one ordinary page whose only block is a {{query}} plus the tine.view::, tine.page-match-scope:: and tine.page-* / tine.block-* display lines the two sections were using. From then on it behaves like any page: linkable, searchable, always fresh. A page that already exists with the chosen name or alias is never overwritten — you pick another name (\"Choose another title\"). The saved block is a single result list with one Display control; the two-section Pages / Blocks layout belongs to the search tab.","title":"Reference/Pages, links, references, and search"},{"anchor":"b69","slug":"reference-pages-links-references-and-search","text":"A {{query [[Page]]}} block uses Logseq's path-refs rule: a block matches when it mentions the page, when a bullet it lives under does, or when it sits on that page — so the page's own outline always appears. The backlinks-only answer to the same question is the page's Linked References panel.","title":"Reference/Pages, links, references, and search"},{"anchor":"b70","slug":"reference-pages-links-references-and-search","text":"A query that asks about pages rather than blocks — (page-property …), (page-tags …), (namespace …) — lists the pages themselves.","title":"Reference/Pages, links, references, and search"},{"anchor":"b71","slug":"reference-pages-links-references-and-search","text":"{{query (all-page-tags)}} lists every page that some page uses as a tag.","title":"Reference/Pages, links, references, and search"},{"anchor":"b72","slug":"reference-pages-links-references-and-search","text":"A query's text is edited at the foot of its sheet, in TQL — SQLite expression syntax over a fixed vocabulary of block and page fields, prop('key'), page references and the any/every/off forms. The compact reference is Workflows/Find and revisit → Query text (TQL). A word Tine cannot read is named, and the query returns no results rather than a shorter answer.","title":"Reference/Pages, links, references, and search"},{"anchor":"b73","slug":"reference-pages-links-references-and-search","text":"When a query finds nothing, why empty? under the result asks which condition emptied it: for each condition, how many blocks it matches on its own and how many the query would match without it. That is usually enough to see which one to loosen.","title":"Reference/Pages, links, references, and search"},{"anchor":"b74","slug":"reference-pages-links-references-and-search","text":"Related","title":"Reference/Pages, links, references, and search"},{"anchor":"b75","slug":"reference-pages-links-references-and-search","text":"Workflows/Find and revisit — the task-first path over these pieces.","title":"Reference/Pages, links, references, and search"},{"anchor":"b76","slug":"reference-pages-links-references-and-search","text":"Features/Tips & shortcuts — the wider shortcut map: tabs, sidebars, focus mode.","title":"Reference/Pages, links, references, and search"},{"anchor":"b77","slug":"reference-pages-links-references-and-search","text":"Feature showcase — every construct above, rendered live.","title":"Reference/Pages, links, references, and search"},{"anchor":"b0","slug":"reference-platforms-and-mobile","text":"Platforms and mobile","title":"Reference/Platforms and mobile"},{"anchor":"b1","slug":"reference-platforms-and-mobile","text":"\"Does this work on my phone?\" hides two different questions: what changes because a window is narrow, and what changes because Tine is running as the Android app instead of a desktop one. This page keeps them apart and maps what current releases ship on each side.","title":"Reference/Platforms and mobile"},{"anchor":"b2","slug":"reference-platforms-and-mobile","text":"Question 1 — is the window narrow?","title":"Reference/Platforms and mobile"},{"anchor":"b3","slug":"reference-platforms-and-mobile","text":"Below a 640 px window width — on any device, including a desktop window you shrank yourself — the left and right sidebars stop squeezing the page and become drawers over it. Dismiss one by tapping the shaded outside edge, using its close control, pressing Esc, or pressing Android Back.","title":"Reference/Platforms and mobile"},{"anchor":"b4","slug":"reference-platforms-and-mobile","text":"At 640 px and wider — including tablets — both sidebars are persistent panes that can stay open together and keep their resize controls.","title":"Reference/Platforms and mobile"},{"anchor":"b5","slug":"reference-platforms-and-mobile","text":"The boundary is width, nothing else: it follows the window, not the device, so the same desktop shows both faces as you resize it.","title":"Reference/Platforms and mobile"},{"anchor":"b6","slug":"reference-platforms-and-mobile","text":"Question 2 — which app is running?","title":"Reference/Platforms and mobile"},{"anchor":"b7","slug":"reference-platforms-and-mobile","text":"Some behavior keys off Tine detecting a native mobile platform, whatever the window width. On a phone-sized screen (shorter edge under 700 px) the Android app hides the tab strip and disables split panes, so one page keeps the phone screen. Tablets have room for two documents and keep split panes.","title":"Reference/Platforms and mobile"},{"anchor":"b8","slug":"reference-platforms-and-mobile","text":"The desktop apps (Linux, macOS, Windows) keep the full window model — tabs, pinned tabs, split panes, saved workspaces, and multiple windows — toured in Workflows/Keep context visible.","title":"Reference/Platforms and mobile"},{"anchor":"b9","slug":"reference-platforms-and-mobile","text":"In both cases your graph is the same ordinary Markdown/Org files, so these are interface and surface differences, never different content formats.","title":"Reference/Platforms and mobile"},{"anchor":"b10","slug":"reference-platforms-and-mobile","text":"On Android","title":"Reference/Platforms and mobile"},{"anchor":"b11","slug":"reference-platforms-and-mobile","text":"Sidebar, Search, Back and Forward are in the top bar, in the same place whether or not you are editing, as on the desktop apps. On a very narrow phone (about 320 px wide) Back and Forward fold into the ⋯ menu. To have them within thumb reach, turn on Settings → Appearance → Navigation buttons at the bottom (off by default, this device only): the four buttons then sit in a row at the bottom of the screen, which gives way to the editing toolbar while the keyboard is up. When you close the keyboard with Back or the keyboard's hide key, the row comes back at once, although the block stays in editing; tap the block to bring the keyboard and the editing toolbar back. The same setting exists on iOS. The editing actions stay in their separate horizontal toolbar above the keyboard; there are no vertical toolbar pages.","title":"Reference/Platforms and mobile"},{"anchor":"b12","slug":"reference-platforms-and-mobile","text":"Your graph is a real folder on the device's own storage. On first run you grant \"All files access\" and pick the graph folder (a Syncthing folder works), and Tine reads and writes that folder directly — coexisting with the Logseq mobile app on one graph. Cloud document providers such as Nextcloud can't be opened directly: use your provider's sync-to-local-folder feature, then pick that local folder in Open graph. The file watcher polls there by default (Settings → Files → Watch for external edits), so external edits appear shortly after they land.","title":"Reference/Platforms and mobile"},{"anchor":"b13","slug":"reference-platforms-and-mobile","text":"An editing toolbar docks above the on-screen keyboard with the actions a keyboard lacks: Outdent / Indent, Move block up / down, Soft newline, TODO, Camera, Voice memo, Undo / Redo, Date picker, [[ ]] and (( )), the Slash menu, and a hide-keyboard button. Undo uses an arrow bending left; Redo uses an arrow bending right.","title":"Reference/Platforms and mobile"},{"anchor":"b14","slug":"reference-platforms-and-mobile","text":"Camera and Voice memo capture a photo or an .m4a recording straight into the graph's assets/ folder and insert the link at the caret — permission-prompted on first use. One that finishes after you switch graphs is saved into the graph it was started in and not inserted; Tine names the graph and the file.","title":"Reference/Platforms and mobile"},{"anchor":"b15","slug":"reference-platforms-and-mobile","text":"Share to Tine from any app. Pick Tine in Android's share sheet to send text, a link, or one or more images. The item becomes a new block at the bottom of today's journal, the same place quick capture files to, and Tine shows Captured to today's journal. Shared images are copied into the graph's assets/ folder. If Tine can't add the item yet, for example because no graph is open or saving fails, it keeps the item and tries again the next time you open or return to Tine. Retrying never loses the item. It can add it twice in one rare case: Tine closed or crashed just after the journal was saved and before it noted the item as done. Reopening an old share from the recent-apps list after Tine was closed or the phone restarted can also add it again. Sharing the same thing twice adds it twice. Tine saves a share whole or not at all: if it can't take every part, for example more than 32 images, a file over 64 MiB, a file that isn't an image, or a file from Tine itself, it says so and saves nothing.","title":"Reference/Platforms and mobile"},{"anchor":"b16","slug":"reference-platforms-and-mobile","text":"Launcher shortcuts and a Quick Settings tile. Long-press Tine's launcher icon for Today, Quick capture and Search. Add the Quick capture tile from the Quick Settings editor. Quick capture opens today's journal with an empty block at the bottom, ready for typing.","title":"Reference/Platforms and mobile"},{"anchor":"b17","slug":"reference-platforms-and-mobile","text":"Hardware Back navigates within Tine — dismissing a dialog or drawer first and stepping back through page history, exiting to the system only at the root.","title":"Reference/Platforms and mobile"},{"anchor":"b18","slug":"reference-platforms-and-mobile","text":"PDFs use that same one-pane history. Open a PDF link in place, press Notes to visit its highlights page, and use Hardware Back to return first to the PDF and then to the source page. Desktop-style PDF tabs and companion splits stay off on a phone.","title":"Reference/Platforms and mobile"},{"anchor":"b19","slug":"reference-platforms-and-mobile","text":"Plugins and themes follow the same lifecycle as desktop — install (always disabled at first), review capabilities, enable, settings, disable, uninstall — and a package that did not declare Android shows Unavailable on it. The hands-on path is Workflows/Extend Tine.","title":"Reference/Platforms and mobile"},{"anchor":"b20","slug":"reference-platforms-and-mobile","text":"The whole interface scales through Interface size (saved per device) and the native status/navigation icons follow your selected theme.","title":"Reference/Platforms and mobile"},{"anchor":"b21","slug":"reference-platforms-and-mobile","text":"Touch gestures on a phone","title":"Reference/Platforms and mobile"},{"anchor":"b22","slug":"reference-platforms-and-mobile","text":"Swipe a block to restructure it. Swipe a block right to indent it, left a short way to outdent it, and left a longer way to select it and open its action menu. A revealed arrow shows indent or outdent before you let go; it switches to a circled more icon when the swipe will open actions. An unavailable indent or outdent has no arrow. The left-swipe outdent band is 40–139 px; actions start at 140 px, giving you more room to outdent. Short or mostly-vertical movements are ordinary scrolling and do nothing. Swiping is off while you are typing in the block, inside tables, code blocks, queries, drawings and media, and with more than one finger, so it never fights text selection or panning.","title":"Reference/Platforms and mobile"},{"anchor":"b23","slug":"reference-platforms-and-mobile","text":"Swipe in from the left edge to open the left drawer; a swipe that starts elsewhere, or that is mostly vertical, does not.","title":"Reference/Platforms and mobile"},{"anchor":"b24","slug":"reference-platforms-and-mobile","text":"Back is one ladder everywhere. It dismisses an open dialog, menu or image first, then closes an open drawer, then steps back through page history. On Android the hardware or system Back gesture climbs that ladder and exits only at the root. Where Tine takes Back from the screen edge instead (iOS), the same left-edge swipe goes Back when there is something to go back to, following your finger and snapping back if you let go early; otherwise it opens the drawer.","title":"Reference/Platforms and mobile"},{"anchor":"b25","slug":"reference-platforms-and-mobile","text":"The image viewer takes touch. Pinch to zoom, double-tap to zoom in and out, drag a zoomed image to pan it (keep dragging past its edge to reach the next image), swipe sideways to move between the page's images, and drag up or down to close. A single tap shows or hides the buttons instead of closing; use the × button, drag the image up or down, or press Back to close.","title":"Reference/Platforms and mobile"},{"anchor":"b26","slug":"reference-platforms-and-mobile","text":"Turn the block swipe off for chosen pages. To stop swipes from acting inside blocks that reference particular pages (a kanban board, say), list their names in config.edn: :mobile {:gestures/disabled-in-block-with-tags [\"kanban\" \"board\"]}. A block that references a listed page, and everything nested under it, ignores the swipe. This is the same setting Logseq uses.","title":"Reference/Platforms and mobile"},{"anchor":"b27","slug":"reference-platforms-and-mobile","text":"What stays different on Android","title":"Reference/Platforms and mobile"},{"anchor":"b28","slug":"reference-platforms-and-mobile","text":"The always-on-top capture window is desktop-only. The tine --capture desktop shortcut and its window over other apps have no phone counterpart. On a phone, capture with the share sheet, the Quick capture shortcut or tile, or iOS Shortcuts and Siri, described above and under iOS below. The desktop setup lives on Features/Quick capture.","title":"Reference/Platforms and mobile"},{"anchor":"b29","slug":"reference-platforms-and-mobile","text":"One route at a time on a phone — pages and PDF readers share one history, with no tab strip, split panes, or second windows; the desktop multi-window model does not exist here.","title":"Reference/Platforms and mobile"},{"anchor":"b30","slug":"reference-platforms-and-mobile","text":"Long-press a page reference or tag to preview its page without navigating away. Choose the … button in the preview header for Page actions, the same menu offered by a desktop right-click. Tap outside the preview to dismiss it; a quick tap still follows the link. Other links keep their long-press context menu, and holding ordinary text keeps the system's text selection and selection toolbar.","title":"Reference/Platforms and mobile"},{"anchor":"b31","slug":"reference-platforms-and-mobile","text":"Export to PDF is desktop-only — printing is unavailable inside a mobile WebView, so the page menu does not offer it here.","title":"Reference/Platforms and mobile"},{"anchor":"b32","slug":"reference-platforms-and-mobile","text":"Updates come through your install channel. The in-app update checker and installer are off on mobile: a sideloaded release-signed APK is replaced by taking each new APK from the GitHub releases page, an F-Droid install updates through F-Droid, and a Google Play install updates through Google Play. The F-Droid build omits the network plugin/theme catalogue and keeps local sideloading.","title":"Reference/Platforms and mobile"},{"anchor":"b33","slug":"reference-platforms-and-mobile","text":"On desktop (Linux, macOS, Windows)","title":"Reference/Platforms and mobile"},{"anchor":"b34","slug":"reference-platforms-and-mobile","text":"Everything the phone skips is here: tabs with pin, reorder, and reopen, split panes, saved workspaces, multiple windows, the modifier-click gestures, and global quick capture. Releases cover Linux and Windows on x64 and ARM64, and macOS as one universal app.","title":"Reference/Platforms and mobile"},{"anchor":"b35","slug":"reference-platforms-and-mobile","text":"In-app updates run on Windows, Linux and macOS — the app checks once per launch and Settings → About → Check for updates offers Install update, which downloads, verifies and installs in place after saving your changes. Windows and Linux relaunch immediately; macOS offers Restart after installation, saving any further changes before restarting. Releases ship signed macOS updater archives for Intel and Apple Silicon from the signed and notarized universal application. If the updater cannot fetch, verify or install an update, Tine opens the releases page so you can download and replace the app manually. If a failed macOS installation cannot restore the previous app, look beside the original app or in your home folder for Tine (previous version).app (or Tine Beta (previous version).app). If neither folder is writable, the updater keeps its temporary backup. The updater shows the saved location when it reports one; open that bundle to recover or download and replace the app manually.","title":"Reference/Platforms and mobile"},{"anchor":"b36","slug":"reference-platforms-and-mobile","text":"Installed from the Microsoft Store (MSIX)? Then the Store keeps Tine up to date: Settings → About says \"Updates come from the Microsoft Store.\", and Tine's own update checker and installer stay off on that install.","title":"Reference/Platforms and mobile"},{"anchor":"b37","slug":"reference-platforms-and-mobile","text":"Running the portable ZIP (Windows)? Tine keeps its settings, sessions, backups, plugins and WebView2 data in the tine-data folder beside Tine.exe, never in AppData, and it updates by download: quit Tine and extract the new ZIP into the same folder, keeping tine-data. A first portable launch starts with fresh settings; to bring the settings of an installed Tine along, quit Tine and copy %APPDATA%\\<app id> to tine-data\\<app id>\\roaming and %LOCALAPPDATA%\\<app id> to tine-data\\<app id>\\local (<app id> is page.tine.Tine, or page.tine.TineBeta for Tine Beta). Your notes stay in your graph folder.","title":"Reference/Platforms and mobile"},{"anchor":"b38","slug":"reference-platforms-and-mobile","text":"Automatic checks are ON by default. In Settings → About, turn off Check for updates automatically to stop startup checks and update notifications on this device. You can still use Check for updates manually; turning automatic checks off does not change how package-manager or manual-download installs receive updates.","title":"Reference/Platforms and mobile"},{"anchor":"b39","slug":"reference-platforms-and-mobile","text":"Install as a Flatpak (Linux, Beta). Each Beta release also carries a Flatpak bundle for 64-bit Intel/AMD, named like Tine-Beta_<version>_x86_64.flatpak, among the other downloads on the Beta release page. Install the downloaded file with flatpak install --user Tine-Beta_<version>_x86_64.flatpak, then start it from your app menu (flatpak list shows its application id for flatpak run). It installs next to a stable Tine Flatpak and keeps its own settings, and it can read and write graph folders inside your home folder only: a graph on another disk or under /mnt or /media is out of its reach, unlike the other Linux builds. Updates are manual: the in-app updater does not apply to it (it offers a download link instead of installing), so download the new bundle from the release page and run the same command again.","title":"Reference/Platforms and mobile"},{"anchor":"b40","slug":"reference-platforms-and-mobile","text":"System tray (optional). In Settings → Appearance, turn on Show Tine in the system tray to get a tray, notification-area or menu-bar icon. Its menu has Open Tine, Quick Capture and Quit; clicking the icon shows and focuses the main window, or hides it when it is already in front. Two more switches appear once the icon is on: Minimize to tray makes minimizing the main window hide it (instead of leaving it in the taskbar) until you open it from the tray, and Start minimized to tray launches Tine with the main window hidden (your graph still loads, so it is ready the moment you open it). All three are off by default and apply to this device only. Closing the main window still quits Tine, and other windows are never hidden by the tray. If your desktop has no tray (some Linux desktops need an AppIndicator or StatusNotifier extension), Tine says so under the switch, shows its window as usual, and ignores the two minimize options until a tray exists. If the tray disappears while Tine is running (the panel that hosted it quits), Tine shows its window again and turns the two minimize options off until you re-apply the setting. A start-minimized launch at login waits a few seconds for a late tray before it gives up and shows the window. The tray needs the system's libayatana-appindicator3 library; the .deb and .rpm recommend it, the Flatpak bundle carries its own, and the AppImage uses the one on your system. Starting Tine again shows the main window if the tray had hidden it, and opening a graph or link always shows it.","title":"Reference/Platforms and mobile"},{"anchor":"b41","slug":"reference-platforms-and-mobile","text":"Any folder on your disk can be a graph — choose it with the ordinary folder picker; there is no sandboxed document picker.","title":"Reference/Platforms and mobile"},{"anchor":"b42","slug":"reference-platforms-and-mobile","text":"On macOS, Tine draws its window with the system's web engine — the same one Safari uses — and needs the engine of Safari 15.4 or later, which means macOS 12.3 (Monterey) or later. Apps get the engine that came with macOS: updating the Safari app on an older Mac leaves the one Tine uses unchanged, so the app bundle declares 12.3 as its minimum system version. If the web engine is too old, Tine explains this at startup instead of opening half-working. Opening PDFs needs Safari 17.4 or later; the rest of Tine does not.","title":"Reference/Platforms and mobile"},{"anchor":"b43","slug":"reference-platforms-and-mobile","text":"iOS today","title":"Reference/Platforms and mobile"},{"anchor":"b44","slug":"reference-platforms-and-mobile","text":"A public beta is on TestFlight: install Apple's TestFlight app, then open that link. An App Store install updates through the App Store.","title":"Reference/Platforms and mobile"},{"anchor":"b45","slug":"reference-platforms-and-mobile","text":"Graphs live in the app's own folders. Open or create a graph inside On My iPhone → TineOutline or iCloud Drive → TineOutline; Tine refuses folders from other Files providers for now and says so. Creating a graph asks for its name after you choose the parent folder, and creates a child folder with that name. An iCloud graph is downloaded to the device before it opens, and a remembered graph reopens after an app update.","title":"Reference/Platforms and mobile"},{"anchor":"b46","slug":"reference-platforms-and-mobile","text":"The iPhone and iPad app uses the same mobile interface as Android, so the notes above about one route at a time, bullet context menus and desktop-only features apply there too.","title":"Reference/Platforms and mobile"},{"anchor":"b47","slug":"reference-platforms-and-mobile","text":"Share to Tine. Pick Tine in the share sheet to send text, a web page, a link, or up to five images. The sheet confirms Saved to Tine. The next time you open Tine, the item becomes a block at the bottom of today's journal, exactly as on Android.","title":"Reference/Platforms and mobile"},{"anchor":"b48","slug":"reference-platforms-and-mobile","text":"Spotlight finds your pages. Pages of the graph open in Tine show up in iPhone search by title, with a short excerpt, and tapping one opens it in Tine. Hidden pages are never added. Only the current graph is indexed, and switching graphs replaces the index.","title":"Reference/Platforms and mobile"},{"anchor":"b49","slug":"reference-platforms-and-mobile","text":"Shortcuts, Siri and the Home Screen. The Shortcuts app and Siri offer Add to Tine journal (it saves without opening Tine, and the block appears the next time you open it), Search Tine and Open page. Long-press the app icon for Today's journal, Quick capture and Search.","title":"Reference/Platforms and mobile"},{"anchor":"b50","slug":"reference-platforms-and-mobile","text":"Plugins do not run on iOS yet. Themes work; downloadable WebAssembly plugins stay off until Tine has the extra review surface Apple requires for them.","title":"Reference/Platforms and mobile"},{"anchor":"b51","slug":"reference-platforms-and-mobile","text":"Shaping a shared item","title":"Reference/Platforms and mobile"},{"anchor":"b52","slug":"reference-platforms-and-mobile","text":"When an Android share brings Tine forward, Tine opens the journal where it saved the item and reveals the shared block, like following a block reference. With several shares, it reveals the last item in the batch. The Captured to today's journal notice stays. Retries leave your current page open, as do iOS shares and App Intents saved without opening Tine. In-app quick capture keeps the page you are editing open.","title":"Reference/Platforms and mobile"},{"anchor":"b53","slug":"reference-platforms-and-mobile","text":"Shared items follow Logseq's mobile rules for each platform. On Android a link becomes a titled link, YouTube and similar video links become {{video …}}, posts on X or Twitter become {{twitter …}}, and text highlighted in a browser goes before its link. On iOS the shared text is kept as it is and the link follows it unchanged, as Logseq's iOS share does. Images follow as asset links, one per line.","title":"Reference/Platforms and mobile"},{"anchor":"b54","slug":"reference-platforms-and-mobile","text":"The block uses Logseq's :quick-capture-templates from config.edn. The default text template is **{time}** [[quick capture]]: {text} {url}, and on Android :media sets the template for a single shared image. {time} is when you shared the item, and {date} is the date of the journal it is added to.","title":"Reference/Platforms and mobile"},{"anchor":"b55","slug":"reference-platforms-and-mobile","text":"The same destinations open from tine://today, tine://capture, tine://search?q=… and tine://page/<name> (a page of the open graph). Each one only opens something in Tine and never writes to your graph.","title":"Reference/Platforms and mobile"},{"anchor":"b56","slug":"reference-platforms-and-mobile","text":"Where next","title":"Reference/Platforms and mobile"},{"anchor":"b57","slug":"reference-platforms-and-mobile","text":"Workflows/Keep context visible for tabs, panes, sidebars and workspaces (desktop), Features/Quick capture for the desktop capture window, Workflows/Extend Tine for the plugin and theme lifecycle, and Features/PDF annotation for the full reader tour.","title":"Reference/Platforms and mobile"},{"anchor":"b0","slug":"reference-tine-query-model","text":"Tine query model","title":"Reference/Tine query model"},{"anchor":"b1","slug":"reference-tine-query-model","text":"Tine reads Logseq's query syntax — {{query …}} blocks and the common advanced (datalog) queries — but runs them on its own engine, not on a datalog database. This page lists every place where the answer can differ from Logseq's, and why. How to write and display queries is on Features/Queries.","title":"Reference/Tine query model"},{"anchor":"b2","slug":"reference-tine-query-model","text":"This page describes Tine Beta. Tine 0.6 (stable) gets several of these wrong in ways Beta has fixed; see the last section.","title":"Reference/Tine query model"},{"anchor":"b3","slug":"reference-tine-query-model","text":"The rule","title":"Reference/Tine query model"},{"anchor":"b4","slug":"reference-tine-query-model","text":"A query in Tine finds everything the same query finds in Logseq, and may find more — never less. Someone moving a graph over from Logseq should never lose a result.","title":"Reference/Tine query model"},{"anchor":"b5","slug":"reference-tine-query-model","text":"Looking at results never changes your files. Sorting by a column heading, collapsing a query or opening a result changes only what you see; only settings you save on purpose (Display, the query text) are written to the block.","title":"Reference/Tine query model"},{"anchor":"b6","slug":"reference-tine-query-model","text":"Where Tine behaves exactly like Logseq","title":"Reference/Tine query model"},{"anchor":"b7","slug":"reference-tine-query-model","text":"Text is exact. A bare word or quoted text in a query matches the raw block text, property lines included, with case and accents significant: Alpha does not find alpha, and cafe does not find café. A query is a deliberate filter, so it matches what you wrote. Ctrl+K, search tabs and in-page Find are for finding things quickly, and ignore case and accents.","title":"Reference/Tine query model"},{"anchor":"b8","slug":"reference-tine-query-model","text":"References include the outline above a block. [[x]], #x and (page-ref x) match a block that references x, and also its child blocks, because a child sits under that reference. #x and [[x]] mean the same.","title":"Reference/Tine query model"},{"anchor":"b9","slug":"reference-tine-query-model","text":"Page properties count as properties. (property type book) also matches the first block of a page whose header says type:: book, as in Logseq. Use (page-property type book) to ask about pages.","title":"Reference/Tine query model"},{"anchor":"b10","slug":"reference-tine-query-model","text":"Commas split only list properties. tags, alias and keys listed in :property/separated-by-commas are lists; every other value is one piece of text, so (property list \"Foo, Bar\") finds list:: Foo, Bar.","title":"Reference/Tine query model"},{"anchor":"b11","slug":"reference-tine-query-model","text":"Results sort newest first unless you write asc, (sample N) picks before it sorts, and a query of only sort-by/sample shows nothing.","title":"Reference/Tine query model"},{"anchor":"b12","slug":"reference-tine-query-model","text":"Table settings from Logseq are read: query-table::, a query ending in table, query-properties:: and query-sort-by:: / query-sort-desc::.","title":"Reference/Tine query model"},{"anchor":"b13","slug":"reference-tine-query-model","text":"(task) with no markers and (priority) with no levels add no condition. Logseq drops such a filter, so (and (task) [[x]]) finds what [[x]] finds, and a query left with no condition shows nothing; Tine does the same. A note on the query says so and offers to rewrite the clause to open tasks, any task, or priorities A, B or C.","title":"Reference/Tine query model"},{"anchor":"b14","slug":"reference-tine-query-model","text":"Where Tine finds more","title":"Reference/Tine query model"},{"anchor":"b15","slug":"reference-tine-query-model","text":"Property values ignore case. (property status Done) also finds status:: done. Logseq requires the exact spelling.","title":"Reference/Tine query model"},{"anchor":"b16","slug":"reference-tine-query-model","text":"Property names ignore case. (property Status x) works; Logseq's parser lowercases names anyway, so this rarely shows.","title":"Reference/Tine query model"},{"anchor":"b17","slug":"reference-tine-query-model","text":"Numbers and dates compare as numbers and dates when a property holds them (or its page declares tine.type::), so count:: 01 equals 1. Logseq compares the stored value.","title":"Reference/Tine query model"},{"anchor":"b18","slug":"reference-tine-query-model","text":"A single word finds every block containing it. Logseq's desktop app runs a search instead and shows its top 30 hits.","title":"Reference/Tine query model"},{"anchor":"b19","slug":"reference-tine-query-model","text":"(sort-by …) knows built-in fields: priority, page, scheduled and deadline as well as any property. Logseq sorts only by a property of that name.","title":"Reference/Tine query model"},{"anchor":"b20","slug":"reference-tine-query-model","text":"What Tine does not run","title":"Reference/Tine query model"},{"anchor":"b21","slug":"reference-tine-query-model","text":"There is no datalog engine. An advanced query runs only if Tine understands every clause: task markers, priorities, page references, properties, pages, namespaces, page tags, scheduled and deadline, and journal dates. If any clause is outside that, the whole query is refused and the notice names the clauses — half an answer would look complete and be wrong.","title":"Reference/Tine query model"},{"anchor":"b22","slug":"reference-tine-query-model","text":"Advanced-query shapes that run: marker and priority triples (literal, variable, _ or omitted value), contains? marker sets and their negation, attribute comparisons, missing scheduled/deadline checks, block-to-journal-page joins, and the built-in task, priority, between, page-ref, property, page and namespace rules. A named page joined through :block/page, :block/refs or :block/path-refs accepts a literal name or a string input. :block/refs means direct references only; :block/path-refs and the page-ref rule also include ancestors and the owning page. TQL's direct_ref('project') preserves the direct form. A simple query in an EDN :query map, such as (and (todo DOING) (priority A)), uses the existing simple-query engine.","title":"Reference/Tine query model"},{"anchor":"b23","slug":"reference-tine-query-model","text":"Tagged-page name results run for [?t :block/name ?tag] [?p :block/tags ?t] [?p :block/name ?name] with :find ?name and a string :inputs binding. They show pages once each, using Tine's own display. Ordinary strings retain case: \"programming\" matches a stored page name, \"Programming\" does not; \"[[Programming]]\" and :current-page are lowercased like Logseq.","title":"Reference/Tine query model"},{"anchor":"b24","slug":"reference-tine-query-model","text":"Date windows accept numeric yyyymmdd inputs, :today, :yesterday, :tomorrow, signed day/week/month/year offsets, and Logseq's older :7d, :7d-before, :7d-after spellings. Comparisons preserve strict > / < and inclusive >= / <=. The common (or [?b :block/scheduled ?d] [?b :block/deadline ?d]) shape applies both bounds to each alternative's date. The advanced between rule includes both bounds in authored order; reversed bounds return nothing.","title":"Reference/Tine query model"},{"anchor":"b25","slug":"reference-tine-query-model","text":"The rest refuses whole: arbitrary joins, authored rules, multiple find columns, aggregates, custom pull projections, timestamp inputs, and :current-block, :parent-block or :query-page. An unfiltered page-name query also includes Logseq's reference-only page entities and is not translated. One :result-transform runs: Logseq's default NOW query sort, (fn [result] (sort-by (fn [h] (get h :block/priority \"Z\")) result)), which orders rows by priority with a missing one last. Any other refused :result-transform with translatable underlying rows suggests their TQL filter; choose Tine's Display settings for sorting or totals. The suggestion does not execute automatically.","title":"Reference/Tine query model"},{"anchor":"b26","slug":"reference-tine-query-model","text":":view and :result-transform never run as code, because they are ClojureScript functions. Tine will not run them; it only recognises the exact priority sort above and performs it itself. Its own Display choices (List, Table, Board, grouping, totals) cover the common uses.","title":"Reference/Tine query model"},{"anchor":"b27","slug":"reference-tine-query-model","text":"A query that would return more than 20,000 rows or 32 MiB is refused, with a message to narrow it or add (sample N). Logseq has no such limit; Tine stops instead of freezing.","title":"Reference/Tine query model"},{"anchor":"b28","slug":"reference-tine-query-model","text":"Where Tine keeps things on your device instead of in the file","title":"Reference/Tine query model"},{"anchor":"b29","slug":"reference-tine-query-model","text":"Clicking a table heading sorts for as long as the page is open. Logseq writes query-sort-by:: into the file.","title":"Reference/Tine query model"},{"anchor":"b30","slug":"reference-tine-query-model","text":"Collapsing a query is remembered on this device. Logseq writes collapsed:: true into the file.","title":"Reference/Tine query model"},{"anchor":"b31","slug":"reference-tine-query-model","text":"Other differences","title":"Reference/Tine query model"},{"anchor":"b32","slug":"reference-tine-query-model","text":"Queries are always live. Logseq stops refreshing a query that takes longer than 50 ms and shows a refresh button; Tine keeps every query current.","title":"Reference/Tine query model"},{"anchor":"b33","slug":"reference-tine-query-model","text":":current-page in a split view is the page in the pane you used last.","title":"Reference/Tine query model"},{"anchor":"b34","slug":"reference-tine-query-model","text":"Pages and blocks are separate answers. A query finds blocks or pages. To see both from the same conditions, choose Pages and blocks in the query sheet.","title":"Reference/Tine query model"},{"anchor":"b35","slug":"reference-tine-query-model","text":"Tine-only features (scheduled and deadline ranges, grouping, totals, typed comparisons, inline-tag and parent, child or descendant conditions, a bare has-a-scheduled-date or has-a-deadline check, search, content-regex) have no equivalent {{query}} spelling. Saving one turns the block into {{tine-query …}}, says so, and offers Undo that change. For example, {{tine-query @block scheduled between today and '+7d'}} checks a scheduled date; OG Logseq drops the condition in (between scheduled …) or (between deadline …).","title":"Reference/Tine query model"},{"anchor":"b36","slug":"reference-tine-query-model","text":"Tine 0.6 (stable)","title":"Reference/Tine query model"},{"anchor":"b37","slug":"reference-tine-query-model","text":"Tine 0.6 differs from this page where it has known bugs, fixed in Beta: it sorts ascending by default; (sample N) sorts first; a query of only directives returns everything; (namespace x) matches every depth; (all-page-tags) returns the tagged pages; not with several operands, (priority [A]), (between created-at …) and page-header properties misbehave; journal groups run oldest first; an advanced query with an unknown clause runs the clauses it understands; query text ignores case and accents; every property value is split on commas; Logseq's table settings are ignored.","title":"Reference/Tine query model"},{"anchor":"b0","slug":"reference-troubleshooting-and-recovery","text":"Troubleshooting and recovery","title":"Reference/Troubleshooting and recovery"},{"anchor":"b1","slug":"reference-troubleshooting-and-recovery","text":"Only recovery paths Tine actually ships, each as numbered actions with the outcome to expect. For where everything lives, see Reference/Files, external edits, and backups.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b2","slug":"reference-troubleshooting-and-recovery","text":"“Changed on disk” banner","title":"Reference/Troubleshooting and recovery"},{"anchor":"b3","slug":"reference-troubleshooting-and-recovery","text":"Meaning: the file changed elsewhere (a sync tool or another editor) while you had unsaved edits. The banner reads “Page changed on disk. Your unsaved changes weren't written.” Nothing was written over — your unsaved text is still on screen.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b4","slug":"reference-troubleshooting-and-recovery","text":"If the banner reads “Page changed on disk while you were editing it” and offers only Review, choose it and continue at step 3: Tine never overwrites the file with a draft you have not compared.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b5","slug":"reference-troubleshooting-and-recovery","text":"1. If the disk version is the one you want, choose Use disk version — Tine re-reads the file. Copy your unsaved text somewhere first if you still need parts of it.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b6","slug":"reference-troubleshooting-and-recovery","text":"2. If your version is right, choose Keep mine (overwrite) — Tine writes yours over the file.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b7","slug":"reference-troubleshooting-and-recovery","text":"3. To keep parts of both, open the page: a panel at its top compares Your unsaved edits with The file on disk now block by block. Choose per block, then Apply resolution. When Tine still has the version you started editing from, it pre-selects each side's own change. If the file changes again before you apply, nothing is written and the comparison refreshes.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b8","slug":"reference-troubleshooting-and-recovery","text":"4. What you should see: the banner clears and the page saves normally again. Until you choose, that page is skipped by saving rather than silently clobbered. If Tine closes first, your unsaved text is kept, and the same comparison appears on that page after the next start, with the same banner until you choose. If the file was deleted on disk, the banner reads “Page was deleted on disk”: Use disk version accepts the deletion, and Keep mine (overwrite) writes your text back as the file.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b9","slug":"reference-troubleshooting-and-recovery","text":"Restore a deleted page or journal","title":"Reference/Troubleshooting and recovery"},{"anchor":"b10","slug":"reference-troubleshooting-and-recovery","text":"1. Open logseq/.tine-trash/pages/ or logseq/.tine-trash/journals/ inside your graph. Deleted files have a timestamp followed by __ before their original name.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b11","slug":"reference-troubleshooting-and-recovery","text":"2. Remove the timestamp and __, then move the file into the configured pages or journals folder. For a page that originally lived elsewhere, you may return it to that location instead.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b12","slug":"reference-troubleshooting-and-recovery","text":"3. What you should see: Tine notices the restored file like any external change, and the page reappears.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b13","slug":"reference-troubleshooting-and-recovery","text":"Restore an earlier state of the graph","title":"Reference/Troubleshooting and recovery"},{"anchor":"b14","slug":"reference-troubleshooting-and-recovery","text":"1. Open Settings (t s) → Backups & recovery and find the snapshot from before the damage under Available snapshots. (Tine snapshots your Markdown/Org files on every launch; Snapshots to keep controls how many survive.)","title":"Reference/Troubleshooting and recovery"},{"anchor":"b15","slug":"reference-troubleshooting-and-recovery","text":"2. Choose Restore beside it and confirm.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b16","slug":"reference-troubleshooting-and-recovery","text":"3. What you should see: your current state is snapshotted first, backed-up graph text returns to its original paths, config and sidecars are restored, and the graph reloads — so even a mistaken restore can be undone by restoring the snapshot it just made.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b17","slug":"reference-troubleshooting-and-recovery","text":"Resolve a sync or version-control conflict","title":"Reference/Troubleshooting and recovery"},{"anchor":"b18","slug":"reference-troubleshooting-and-recovery","text":"1. Choose the N conflicts badge in the sidebar to open the Conflicts page, then choose the page to resolve. Tine uses the same queue for sync-provider conflict copies and files carrying unresolved git or Fossil merge markers.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b19","slug":"reference-troubleshooting-and-recovery","text":"2. On the page, compare the two versions block by block. For each differing block choose Mine, Theirs, or Both; when both sides edited separate parts of one block, Tine may offer a combined Merged version. Apply all suggested re-applies Tine's own suggestions, and the page's own properties have a separate choice. Then choose Apply resolution.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b20","slug":"reference-troubleshooting-and-recovery","text":"3. What you should see: the chosen page is saved through the normal guarded path. A provider conflict copy moves to the trash; before a version-control page is written without conflict markers, its exact pre-resolution file is kept in recoverable trash. If a conflict copy's original page no longer exists, use Discard copy on the Conflicts page.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b21","slug":"reference-troubleshooting-and-recovery","text":"Reconcile a duplicate journal day","title":"Reference/Troubleshooting and recovery"},{"anchor":"b22","slug":"reference-troubleshooting-and-recovery","text":"1. Choose the N conflicts badge and open the day from the Duplicate journal days group, or open the day itself. Tine compares its two files block by block, the same review as a sync conflict, and lists each file with Open, Rename, and Trash actions. The same list stays in Settings → Backups & recovery → Duplicate journal days, which also offers Merge.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b23","slug":"reference-troubleshooting-and-recovery","text":"2. Choose which version of each differing block to keep (or keep both), then Apply resolution. Where the two files hold different blocks, the pre-selected choice keeps everything, as Merge does. A Markdown file and an Org file for one day cannot be folded together; use the file actions instead.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b24","slug":"reference-troubleshooting-and-recovery","text":"3. What you should see: the kept content saved as the day and the other file moved to logseq/.tine-trash/, where you can still recover it. Tine kept both source files until you decided rather than dropping one.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b25","slug":"reference-troubleshooting-and-recovery","text":"Journal days look empty","title":"Reference/Troubleshooting and recovery"},{"anchor":"b26","slug":"reference-troubleshooting-and-recovery","text":"Meaning: the journal file may be named after its title (for example Jun 18th, 2026.md) instead of its date, so Tine cannot place it in the feed.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b27","slug":"reference-troubleshooting-and-recovery","text":"1. Open Settings → Backups & recovery → Journal files named by title.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b28","slug":"reference-troubleshooting-and-recovery","text":"2. Review the listed renames and choose Rename to date names.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b29","slug":"reference-troubleshooting-and-recovery","text":"3. What you should see: a snapshot is taken first, the files take their date names, and the days appear in the journal feed.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b30","slug":"reference-troubleshooting-and-recovery","text":"Tine will not start","title":"Reference/Troubleshooting and recovery"},{"anchor":"b31","slug":"reference-troubleshooting-and-recovery","text":"1. Set TINE_DEBUG=1 in the environment when you launch Tine, reproduce the problem, then quit.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b32","slug":"reference-troubleshooting-and-recovery","text":"2. By default the log is tine-debug.log in your platform's temporary folder (portable Windows Tine: in tine-data\\<app id>\\local\\logs beside Tine.exe); TINE_DEBUG_LOG=/path overrides it.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b33","slug":"reference-troubleshooting-and-recovery","text":"3. What you should see: a timestamped trace covering the environment, startup milestones, and any panic with a backtrace. It records no note content — send that file with your report.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b34","slug":"reference-troubleshooting-and-recovery","text":"4. On Linux, if the window never appears at all, launch once with TINE_GPU=0: a rare GPU/WebKitGTK rendering failure then falls back to software rendering.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b35","slug":"reference-troubleshooting-and-recovery","text":"Tine could not open your last graph","title":"Reference/Troubleshooting and recovery"},{"anchor":"b36","slug":"reference-troubleshooting-and-recovery","text":"Meaning: at launch Tine tried to reopen the graph you last used and failed. The Welcome screen shows Tine could not open your last graph with the graph's path and the reason.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b37","slug":"reference-troubleshooting-and-recovery","text":"1. Try again — attempt the same open again. This is safe to repeat.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b38","slug":"reference-troubleshooting-and-recovery","text":"2. Copy details — copies the path and reason for an issue report. Use this before anything else if you plan to report it.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b39","slug":"reference-troubleshooting-and-recovery","text":"3. Or open a different graph from the same screen and leave this one untouched.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b40","slug":"reference-troubleshooting-and-recovery","text":"4. What you should see: the card says nothing was changed on disk, and that is the case — retrying, opening another graph, or relaunching Tine are all safe before any manual recovery.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b41","slug":"reference-troubleshooting-and-recovery","text":"Part of the window says it could not be displayed","title":"Reference/Troubleshooting and recovery"},{"anchor":"b42","slug":"reference-troubleshooting-and-recovery","text":"Meaning: one region — a page or PDF pane, a sidebar item, query results, a dialog, plugin settings, or the conflict panel — hit an error it could not render through. Tine reports it in place with a Retry button instead of blanking the app, and the rest of the window keeps working.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b43","slug":"reference-troubleshooting-and-recovery","text":"Copy details — copies the region and error details for a report. Review the copied text before sharing: an error may include a file path or your own content.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b44","slug":"reference-troubleshooting-and-recovery","text":"1. Retry — re-renders just that region. A failure caused by something transient, such as a command that lost a race with a slow startup, usually clears on the first retry.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b45","slug":"reference-troubleshooting-and-recovery","text":"2. If the card says Tine is still waiting on operations that have been running for a while, give it a moment and retry again: the region is failing because the backend has not answered yet, not because anything is wrong with your notes.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b46","slug":"reference-troubleshooting-and-recovery","text":"3. If it comes back every time, use Create a privacy-safe diagnostic report below and include the message shown in the region.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b47","slug":"reference-troubleshooting-and-recovery","text":"4. What you should see: your notes on disk are untouched either way — a region that cannot be displayed is a display failure, not a data failure.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b48","slug":"reference-troubleshooting-and-recovery","text":"A panel says it could not load something","title":"Reference/Troubleshooting and recovery"},{"anchor":"b49","slug":"reference-troubleshooting-and-recovery","text":"Meaning: a panel could not fetch what it needed, and says so instead of drawing itself empty, because an empty panel would tell you there is nothing there, which is a different thing from not being able to find out. Linked and Unlinked References say “Couldn’t load references”; the references under a block say “Couldn’t load references to this block” with a Retry button; Search says “Couldn’t load search results” instead of “No matched results”; a page in the right sidebar says “Could not load this sidebar page. Collapse and expand to retry.”","title":"Reference/Troubleshooting and recovery"},{"anchor":"b50","slug":"reference-troubleshooting-and-recovery","text":"1. Where the panel has a Retry button, press it: it re-fetches just that panel. For a sidebar page, collapse and expand its entry to try again. For Linked and Unlinked References, reopen the page or navigate away and back.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b51","slug":"reference-troubleshooting-and-recovery","text":"2. Smaller pieces degrade quietly rather than saying anything: a code block that could not be highlighted shows as plain text, a formula that could not be typeset shows its LaTeX, a preview that could not load shows nothing in its place. These are display-only, and reopening the page tries them again.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b52","slug":"reference-troubleshooting-and-recovery","text":"3. If it keeps failing, create a diagnostic report as described below.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b53","slug":"reference-troubleshooting-and-recovery","text":"4. What you should see: the rest of the window is unaffected, and nothing on disk changes.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b54","slug":"reference-troubleshooting-and-recovery","text":"A red error message appears","title":"Reference/Troubleshooting and recovery"},{"anchor":"b55","slug":"reference-troubleshooting-and-recovery","text":"Meaning: something actually went wrong — a save, a read, or a check Tine could not finish. A red message stays on screen until you close it, so there is time to read it; the brief states Tine passes through while it starts or opens a graph never show one.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b56","slug":"reference-troubleshooting-and-recovery","text":"1. Choose Copy on the message to copy its full text for a report.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b57","slug":"reference-troubleshooting-and-recovery","text":"2. Close it with × once you have what you need. If you closed it too soon, Settings → Help & diagnostics → Recent error messages lists the last 20 of this session, newest first, each with Copy; they are kept in memory only and are gone when Tine closes.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b58","slug":"reference-troubleshooting-and-recovery","text":"3. What you should see: the message stays until you close it; if the same error happens again it shows a count (×2, ×3) instead of a second message. The privacy-safe diagnostic report below notes that it appeared (not its text), and with TINE_DEBUG=1 its full text is also in the detailed debug log.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b59","slug":"reference-troubleshooting-and-recovery","text":"Create a privacy-safe diagnostic report","title":"Reference/Troubleshooting and recovery"},{"anchor":"b60","slug":"reference-troubleshooting-and-recovery","text":"1. Open Settings → Help & diagnostics and choose Create diagnostic report. Tine previews its bounded flight recorder for the current and previous run: fixed operation names, outcomes, timings, counts, platform, version, and build information.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b61","slug":"reference-troubleshooting-and-recovery","text":"2. Review the report, then choose Copy report (or Save report… on desktop). Nothing is uploaded automatically. The recorder excludes graph content, paths, page titles, queries, URLs, credentials, and the opt-in detailed debug log.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b62","slug":"reference-troubleshooting-and-recovery","text":"3. What you should see: a report you can attach to an issue without first setting up adb, SSH, or a terminal. Clear recorded events removes the retained flight-recorder history after you are done.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b63","slug":"reference-troubleshooting-and-recovery","text":"4. For a graph that opens or saves slowly, the report's graphs section is the part to attach. It holds, for the last time the graph was opened, how long each step took (listing the folder, checking file dates, reading files, parsing, building the index, becoming ready) with how many files and bytes each step handled, so a slow disk or antivirus scan shows up as read time rather than parse time. It also lists how often opening restarted and why, the most recent full rescans and saves with their durations, and the shape of the graph: how many pages, journals, Windows line-ending files, non-normalized file names and sync-conflict files it has, and the spread (median, 90th and 99th percentile, largest) of file sizes, blocks per page, nesting depth, links, tags, embeds, block references, queries, properties, backlinks per page and namespace depth. These are numbers only: never a page name, any text, or a hash of either.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b64","slug":"reference-troubleshooting-and-recovery","text":"Opening a large graph is slow on Windows","title":"Reference/Troubleshooting and recovery"},{"anchor":"b65","slug":"reference-troubleshooting-and-recovery","text":"Meaning: Windows Defender real-time protection scans each file the first time Tine reads it. On a graph of tens of thousands of files the first open after install, or after Defender updates, can take several times longer than later opens; the time shows up as read time in the diagnostic report, not parse time. Nothing is wrong with the graph.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b66","slug":"reference-troubleshooting-and-recovery","text":"1. When a graph's first open is slow and real-time protection is on, Tine shows a one-time notice for that graph: “Opening this graph took a while, and Windows Defender is scanning each file as Tine reads it.” Close it with × to dismiss it for that graph.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b67","slug":"reference-troubleshooting-and-recovery","text":"2. To act on it, choose Add an exclusion for this graph folder. Windows asks for administrator approval; only then does Tine run Add-MpPreference -ExclusionPath for the graph's folder. Tine never changes Defender without that choice. You can also do the same yourself in Windows Security → Virus & threat protection → Manage settings → Exclusions.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b68","slug":"reference-troubleshooting-and-recovery","text":"3. What you should see: “Windows Defender now skips this graph's folder” on success. If you decline the prompt, nothing changes and the notice returns the next time this graph opens slowly. If Defender is managed by your organization or another antivirus, Tine says it did not accept the exclusion and changes nothing.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b69","slug":"reference-troubleshooting-and-recovery","text":"4. The exclusion tells Defender not to scan that folder, which is a security tradeoff: only exclude folders you trust. The diagnostic report records only whether real-time protection is on (windowsDefenderRealtime: on, off, unknown, or not-applicable), never any path.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b70","slug":"reference-troubleshooting-and-recovery","text":"Rescan the graph on demand","title":"Reference/Troubleshooting and recovery"},{"anchor":"b71","slug":"reference-troubleshooting-and-recovery","text":"Meaning: Tine notices files changed outside it (another app, Syncthing, Dropbox) by itself. If you suspect it missed a change, or want to time a full check for a diagnostic report, you can ask for one.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b72","slug":"reference-troubleshooting-and-recovery","text":"1. Open Settings → Help & diagnostics and choose Rescan graph. Tine ignores everything it has remembered about your files: it reads and parses every file of the open graph again from disk, rebuilds its pages, links and search index from them, and shows whatever changed outside Tine. It does not freeze the app and it does not overwrite what you are typing; a page you have open keeps its place, and saving over a file that changed on disk is refused as usual. It takes longer than the quick check Tine does whenever you return to the window, which is why it is a button.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b73","slug":"reference-troubleshooting-and-recovery","text":"2. What you should see: the button reads Rescanning… while it works, then Last rescan finished at followed by the time. Create a diagnostic report afterwards to see how long that rescan took.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b74","slug":"reference-troubleshooting-and-recovery","text":"Check that two devices hold the same graph","title":"Reference/Troubleshooting and recovery"},{"anchor":"b75","slug":"reference-troubleshooting-and-recovery","text":"Meaning: after syncing a graph with Syncthing, Dropbox or a similar service, you can confirm that both devices hold the same Markdown and Org files, byte for byte, and see exactly which files differ if they do not.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b76","slug":"reference-troubleshooting-and-recovery","text":"1. On each device, open Settings → Help & diagnostics and choose Create graph verification report. Tine reads every Markdown and Org file of the open graph, shows its progress, and lets you Cancel.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b77","slug":"reference-troubleshooting-and-recovery","text":"2. On one device choose Copy graph report (or Save graph report… on desktop) and paste it into the box Report from the other device on the other, then choose Compare reports.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b78","slug":"reference-troubleshooting-and-recovery","text":"3. What you should see: either “The source file sets and bytes match”, or lists named Only on this device, Only on the other device and Different bytes with the file paths. The report holds paths and checksums, never file contents; nothing is uploaded and nothing in your graph changes.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b79","slug":"reference-troubleshooting-and-recovery","text":"4. If a file changed while Tine was reading it, the report says Incomplete and no match is confirmed: let the sync settle and create the report again.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b80","slug":"reference-troubleshooting-and-recovery","text":"A graph file could not be read","title":"Reference/Troubleshooting and recovery"},{"anchor":"b81","slug":"reference-troubleshooting-and-recovery","text":"If config.edn could not be read appears, the graph opens read-only so a missing setting cannot send new files to the wrong folder. Read your available pages, repair the file or its permissions in logseq/config.edn, then reopen the graph. Settings shows the same problem until that reopen.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b82","slug":"reference-troubleshooting-and-recovery","text":"If custom.css could not be read appears, Tine applies no custom CSS for that open if the failure happens while the graph opens; if it happens on an edit while the graph is open, the previous version stays applied (Tine retries once before it tells you). Repair logseq/custom.css or its permissions and save it again; Tine re-applies the file when it changes, and reopening the graph tries again too. Settings → Appearance → Custom CSS → Disable custom CSS ignores the file for the rest of the session if a stylesheet makes the window hard to use.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b83","slug":"reference-troubleshooting-and-recovery","text":"If Some page files couldn't be read appears, the notice names those files (the first five, then how many more), and Copy on the notice copies the full list.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b84","slug":"reference-troubleshooting-and-recovery","text":"A failed journal scan or page discovery does not mean those files are absent. The graph remains open; repair the unreadable file or folder and retry. A failed conflict refresh keeps the last successful conflict list, which may be out of date.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b85","slug":"reference-troubleshooting-and-recovery","text":"An asset that gained a reference after an orphan scan is kept when you choose Trash. Refresh the orphan scan before trying again. With external editors or sync, wait for their changes to appear in Tine first: a change it has not observed can still race deletion.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b86","slug":"reference-troubleshooting-and-recovery","text":"Cancelling graph verification makes no report and raises no error message. If a source file is replaced during verification, its report is incomplete; finish syncing or editing and create another report.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b87","slug":"reference-troubleshooting-and-recovery","text":"Switch between stable Tine and Tine Beta","title":"Reference/Troubleshooting and recovery"},{"anchor":"b88","slug":"reference-troubleshooting-and-recovery","text":"Each Beta has its own release page, tagged vX.Y.Z-beta.N. Beta's in-app updater checks https://tine.page/updates/beta/latest.json for the newest Beta; older Betas still find the new release. For a manual download, choose that version's Beta release page.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b89","slug":"reference-troubleshooting-and-recovery","text":"Master ships stable Tine; Tine Beta is a separate app for testing upcoming changes, with its own settings and Beta updates. Stable gets only stable updates, and Beta gets only Beta updates.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b90","slug":"reference-troubleshooting-and-recovery","text":"Close Tine before switching builds. On its first configured desktop launch, Tine Beta copies compatible settings from stable Tine and leaves stable app data intact. If it opens Welcome, choose your existing graph folder; do not delete application data to recover it. Android's separate Beta app needs its graph folder selected again.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b91","slug":"reference-troubleshooting-and-recovery","text":"To return to stable Tine, close Tine Beta and launch stable Tine; your graph files stay where they were. Save your edits before switching. In Settings → About, Copy version copies the app name and full version, including the Beta sequence, for a bug report.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b0","slug":"start-bring-an-existing-graph","text":"Bring an existing graph","title":"Start/Bring an existing graph"},{"anchor":"b1","slug":"start-bring-an-existing-graph","text":"Tine works directly on the same Markdown/Org files as Logseq — no import, no export, no lock-in.","title":"Start/Bring an existing graph"},{"anchor":"b2","slug":"start-bring-an-existing-graph","text":"Open your graph","title":"Start/Bring an existing graph"},{"anchor":"b3","slug":"start-bring-an-existing-graph","text":"1. On the Welcome screen, choose Open an existing graph and pick the graph's top-level folder — usually the one containing pages/, journals/, and logseq/. On Android, grant \"All files access\" when asked; Tine then continues to the folder picker.","title":"Start/Bring an existing graph"},{"anchor":"b4","slug":"start-bring-an-existing-graph","text":"2. Later, use the graph-name menu at the top of the left sidebar → Open graph…, or Settings (t s) → Graph → Open another graph…. Graphs you have opened appear in the same sidebar menu for one-click switching.","title":"Start/Bring an existing graph"},{"anchor":"b5","slug":"start-bring-an-existing-graph","text":"3. On desktop, from the command line, tine /path/to/graph (or tine open /path/to/graph, or TINE_GRAPH=/path/to/graph) opens a graph directly.","title":"Start/Bring an existing graph"},{"anchor":"b6","slug":"start-bring-an-existing-graph","text":"4. What you should see: the same pages and journals Logseq finds. Existing Markdown and Org pages may be at the graph root or in nested folders, not only under pages/ and journals/.","title":"Start/Bring an existing graph"},{"anchor":"b7","slug":"start-bring-an-existing-graph","text":"If the graph you used last time cannot be opened at launch — the folder moved, a drive is unplugged, a file is unreadable — the Welcome screen says so in a card that names the graph and the reason, with Try again and Copy details buttons. Nothing was changed on disk; you can also open another graph from the same screen.","title":"Start/Bring an existing graph"},{"anchor":"b8","slug":"start-bring-an-existing-graph","text":"Create a new graph","title":"Start/Bring an existing graph"},{"anchor":"b9","slug":"start-bring-an-existing-graph","text":"Choose Create a new graph on Welcome, or New graph… in the sidebar graph menu. Choose its parent folder on desktop or iOS; Android uses its default graph location.","title":"Start/Bring an existing graph"},{"anchor":"b10","slug":"start-bring-an-existing-graph","text":"Enter a Graph name. Tine suggests the first unused name: notes, notes-2, notes-3, and so on. The graph is always a child folder of that name, even when the parent is empty. Cancel creates nothing.","title":"Start/Bring an existing graph"},{"anchor":"b11","slug":"start-bring-an-existing-graph","text":"An existing empty child folder can be used. A nonempty folder is refused without replacing its files; the name prompt stays open so you can choose another name. Names must be one portable folder name, without path separators, Windows device names, invalid characters, or a trailing dot or space.","title":"Start/Bring an existing graph"},{"anchor":"b12","slug":"start-bring-an-existing-graph","text":"On Windows, use \\\\wsl.localhost\\<distro>\\… for a graph in WSL: Windows access through a distro package's LocalState\\rootfs can corrupt Linux files, so Tine refuses new graphs there and warns when opening an existing one.","title":"Start/Bring an existing graph"},{"anchor":"b13","slug":"start-bring-an-existing-graph","text":"What Tine reads","title":"Start/Bring an existing graph"},{"anchor":"b14","slug":"start-bring-an-existing-graph","text":"The usual layout is pages/, journals/, assets/, and logseq/config.edn, but Tine also finds eligible .md, .markdown, and .org pages elsewhere inside the graph.","title":"Start/Bring an existing graph"},{"anchor":"b15","slug":"start-bring-an-existing-graph","text":"Root-level and nested pages are named from their file names (or their title::) and save back to their exact existing paths. Tine skips hidden/internal trees, assets, publish output, and sync-provider conflict copies; :hidden prefixes in config.edn are honored too.","title":"Start/Bring an existing graph"},{"anchor":"b16","slug":"start-bring-an-existing-graph","text":"Your journal settings are honored: Tine reads the journal date formats from config.edn, so old files are recognized and new journals are created in your format.","title":"Start/Bring an existing graph"},{"anchor":"b17","slug":"start-bring-an-existing-graph","text":"An Org file Tine cannot reproduce byte-for-byte opens read-only rather than being rewritten imperfectly.","title":"Start/Bring an existing graph"},{"anchor":"b18","slug":"start-bring-an-existing-graph","text":"What Tine writes","title":"Start/Bring an existing graph"},{"anchor":"b19","slug":"start-bring-an-existing-graph","text":"Edits save automatically into the same file each page came from, preserving that file's exact formatting; files with no changes are not rewritten.","title":"Start/Bring an existing graph"},{"anchor":"b20","slug":"start-bring-an-existing-graph","text":"New pages and journals are ordinary .md or .org files in the configured pages and journals folders (Settings → Editor → File format chooses what new files use).","title":"Start/Bring an existing graph"},{"anchor":"b21","slug":"start-bring-an-existing-graph","text":"A Tine view (grid, table, board) attaches harmless tine.* properties to its own block; Logseq shows them as ordinary property lines — see Features/Sheets.","title":"Start/Bring an existing graph"},{"anchor":"b22","slug":"start-bring-an-existing-graph","text":"Coexisting with other tools","title":"Start/Bring an existing graph"},{"anchor":"b23","slug":"start-bring-an-existing-graph","text":"While Tine is open, it watches the files, so changes made by Logseq, another editor, or a sync tool appear automatically (Settings → Files → Watch for external edits switches to polling on filesystems where the live watcher is unreliable).","title":"Start/Bring an existing graph"},{"anchor":"b24","slug":"start-bring-an-existing-graph","text":"Avoid editing the same graph in two apps at once. A second Tine window on the same graph is refused; concurrent edits across other apps or devices are handled as conflicts, not assumed safe.","title":"Start/Bring an existing graph"},{"anchor":"b25","slug":"start-bring-an-existing-graph","text":"If a page changes on disk while you have unsaved edits, Tine overwrites nothing — a banner offers Review, which compares your draft with the disk version on the page. The mechanics are in Reference/Files, external edits, and backups.","title":"Start/Bring an existing graph"},{"anchor":"b26","slug":"start-bring-an-existing-graph","text":"Syncthing and Dropbox keep working on the folder as before; Tine detects their conflict copies, shows an N conflicts badge in the left sidebar, and helps you merge them — also in Reference/Files, external edits, and backups.","title":"Start/Bring an existing graph"},{"anchor":"b27","slug":"start-bring-an-existing-graph","text":"First safety checks","title":"Start/Bring an existing graph"},{"anchor":"b28","slug":"start-bring-an-existing-graph","text":"1. Confirm you opened the graph root: Settings (t s) → Graph → Graph folder shows the current graph path; on desktop, Show in folder beside it opens that folder in Finder, File Explorer or your file manager. In a standard Logseq graph, this is the folder containing pages/, journals/, and logseq/config.edn.","title":"Start/Bring an existing graph"},{"anchor":"b29","slug":"start-bring-an-existing-graph","text":"2. Skim Reference/Files, external edits, and backups now — know where snapshots, conflict copies, and the trash live before you need them.","title":"Start/Bring an existing graph"},{"anchor":"b30","slug":"start-bring-an-existing-graph","text":"3. What you should see: no conflict banner, your existing pages in their original locations, and edits from Tine landing in the same files Logseq reads.","title":"Start/Bring an existing graph"},{"anchor":"b31","slug":"start-bring-an-existing-graph","text":"Where next","title":"Start/Bring an existing graph"},{"anchor":"b32","slug":"start-bring-an-existing-graph","text":"Start/Where things are maps the page, sidebars, tabs, and Settings and Help you will meet on the way; Workflows/Capture and plan your day starts the journal-first daily flow.","title":"Start/Bring an existing graph"},{"anchor":"b0","slug":"start-where-things-are","text":"Where things are","title":"Start/Where things are"},{"anchor":"b1","slug":"start-where-things-are","text":"A short map of Tine's main places, so the recipes in this Guide make sense on first read: the page in the middle, the left sidebar, the tab strip, the right sidebar, and Settings and Help. Each place links to the workflow that teaches it — nothing here is a rulebook.","title":"Start/Where things are"},{"anchor":"b2","slug":"start-where-things-are","text":"The middle: one route per pane","title":"Start/Where things are"},{"anchor":"b3","slug":"start-where-things-are","text":"Each pane shows the page or PDF its active tab points to. Tine opens on the journal feed — one continuous, editable list of days — and the Journals item in the left sidebar always takes you back to it.","title":"Start/Where things are"},{"anchor":"b4","slug":"start-where-things-are","text":"Everything you write is a block (one bullet). Blocks nest under other blocks to form the outline, and any block can carry a task, a date, a link, or its own id for references from elsewhere.","title":"Start/Where things are"},{"anchor":"b5","slug":"start-where-things-are","text":"Press Ctrl+K at any time to jump to a page by name or to text inside any block.","title":"Start/Where things are"},{"anchor":"b6","slug":"start-where-things-are","text":"The reading column has a width cap. Press t w to toggle wide mode, which drops the cap; Settings → Appearance → Advanced holds Standard page width and Wide page width if you want your own numbers.","title":"Start/Where things are"},{"anchor":"b7","slug":"start-where-things-are","text":"If one region of the screen — the page, the sidebar, a references section, or the conflict panel — fails to draw, that region shows a small card saying so, with a Retry button, instead of leaving the whole window blank. Your files on disk are not touched by it.","title":"Start/Where things are"},{"anchor":"b8","slug":"start-where-things-are","text":"The left sidebar: your graph's contents","title":"Start/Where things are"},{"anchor":"b9","slug":"start-where-things-are","text":"At the very top sits the workspace switcher — saved window layouts, covered in Workflows/Keep context visible. Just under it, the graph-name menu switches between the graphs Tine knows, with Open graph… and New graph… beside them — on desktop, Shift-click a graph row to open it in a second window instead of switching this one. Right-click a row for the same thing as a menu item — Open in a new window — along with Open here, Show in folder, Copy path, and Remove from this list. The row for the graph you already have open shows the two open actions greyed out, so the menu keeps its shape wherever you click.","title":"Start/Where things are"},{"anchor":"b10","slug":"start-where-things-are","text":"Below the menu: Journals, then fold-up Favorites and Recent (each appears once it has something in it), All pages, and the Namespaces tree, where Project/Roadmap nests under Project. Namespaces appears only when the graph has namespaced page names. Favorites and Recent remember whether you left them open or folded.","title":"Start/Where things are"},{"anchor":"b11","slug":"start-where-things-are","text":"The All pages entry opens the full All pages view in the main pane: every page in your graph, however many, as one scrolling table. On a phone, choosing it closes the navigation drawer. It opens with the most recently changed pages first: the Updated column shows when each page's file last changed (a dash when Tine has no time for it). Click Updated, Page (name) or Backlinks to sort by it, and click again to reverse; type in the filter box to narrow by name, and tick Show journals to include the daily pages, which also adds the Journal date column (click it to sort by date). Rows open exactly like sidebar rows — click for this pane, Shift-click for the right sidebar, Ctrl/Cmd- or middle-click for a background tab, Alt-click for the other pane, right-click for the page menu.","title":"Start/Where things are"},{"anchor":"b12","slug":"start-where-things-are","text":"Every row is a whole-row click target: clicking the blank space to the right of a short page name opens that page, just like clicking the name itself. Shift-click a row for the right sidebar, middle-click for a background tab, right-click for the page menu.","title":"Start/Where things are"},{"anchor":"b13","slug":"start-where-things-are","text":"Favorites can be arranged without changing what Logseq sees: choose + New group, rename the plain-text label, then drag favorites or groups left/right to lift or nest them to any depth. Deleting a group keeps everything it held one level up. Tine stores that richer arrangement on an ordinary editable page while keeping config.edn :favorites as Logseq's flat list; Workflows/Find and revisit walks the safe path.","title":"Start/Where things are"},{"anchor":"b14","slug":"start-where-things-are","text":"The + New page button at the bottom opens the same Ctrl+K box; a name that matches nothing becomes a page you can create. When Syncthing, Dropbox or a merge leaves pages that need a decision, an N conflicts badge appears beside it — see Reference/Files, external edits, and backups. Press t l to fold the whole sidebar away, and t l again to bring it back.","title":"Start/Where things are"},{"anchor":"b15","slug":"start-where-things-are","text":"The tab strip: what's open","title":"Start/Where things are"},{"anchor":"b16","slug":"start-where-things-are","text":"Every open page or PDF keeps a tab along the top, browser-style: click to switch, Ctrl+W to close. Middle-click anything that opens a page — a link, a search result, a bullet's dot — to park it in a background tab without leaving this one. PDF links open in a companion pane by default, and their tabs can be dragged between panes like page tabs. Tabs come back after a restart.","title":"Start/Where things are"},{"anchor":"b17","slug":"start-where-things-are","text":"Tabs are a desktop feature — the mobile app hides the strip so one page or PDF route keeps the screen, with Back returning through its history.","title":"Start/Where things are"},{"anchor":"b18","slug":"start-where-things-are","text":"The right sidebar: parked context","title":"Start/Where things are"},{"anchor":"b19","slug":"start-where-things-are","text":"Anything you want beside the current page rather than instead of it — another page, or zoomed into one bullet — goes to the right sidebar: Shift-click a link or a bullet's dot. Items there are live editors, not previews. Press t r to show or hide the whole sidebar.","title":"Start/Where things are"},{"anchor":"b20","slug":"start-where-things-are","text":"Settings and Help","title":"Start/Where things are"},{"anchor":"b21","slug":"start-where-things-are","text":"The gear at the top right (or press t s) opens Settings: appearance (Light, System or Dark, interface size, wide mode), editor behavior, journals, files, backups & recovery, the graph, plugins, help & diagnostics, and the remappable Keyboard shortcuts list. The search box at the top shows only matching settings, with matching words highlighted. Choose a result to leave search and reveal its control, including Advanced settings; the setting is highlighted for about two seconds so it is easy to spot. Names that match come before descriptions that match, and a result found only through its description shows that description with the match highlighted. A single character matches only the text shown in your interface language, not the English names behind a translated interface. Clear the search to restore the normal tab. In Keyboard shortcuts, search filters commands and keys within that tab.","title":"Start/Where things are"},{"anchor":"b22","slug":"start-where-things-are","text":"Themes is the first section under Settings → Appearance, followed by Language and Mode. Advanced holds Fine-tuning, Custom CSS and content widths; Settings search reveals these controls too. Tine's menus, settings and messages can be shown in English or Simplified Chinese (简体中文); System default follows your system's language. The choice applies at once, in every open window, and is remembered on this device. Your notes, page names, properties and queries are never translated. Simplified Chinese covers the complete interface catalog, including settings, queries, context menus and recovery dialogs.","title":"Start/Where things are"},{"anchor":"b23","slug":"start-where-things-are","text":"Settings opens as a small dialog. The button beside its search box makes it fill the window, which is easier to read through; Tine remembers which size you left it at and opens it that way next time.","title":"Start/Where things are"},{"anchor":"b24","slug":"start-where-things-are","text":"The ? button at the bottom right (or press Shift+?) opens Help: this Guide, the shortcut reference, the features documentation, the bug-report and release-notes links, and the Welcome screen.","title":"Start/Where things are"},{"anchor":"b25","slug":"start-where-things-are","text":"On a phone","title":"Start/Where things are"},{"anchor":"b26","slug":"start-where-things-are","text":"Below a 640 px window width, either sidebar opens as an overlay on top of the current route instead of shrinking it — tap the shaded outside edge, press Esc, or use Android Back to dismiss. Split panes and the tab strip are desktop-only on a phone-sized screen.","title":"Start/Where things are"},{"anchor":"b27","slug":"start-where-things-are","text":"Reference/Platforms and mobile separates narrow-window behavior from native-app behavior and maps each platform's shipping surface.","title":"Start/Where things are"},{"anchor":"b28","slug":"start-where-things-are","text":"Where next","title":"Start/Where things are"},{"anchor":"b29","slug":"start-where-things-are","text":"New here? Welcome to Tine walks the first hands-on minutes. To put these places to work — parking, pinning, splitting, and saving the layout — continue with Workflows/Keep context visible; Features/Tips & shortcuts is the compact shortcut map.","title":"Start/Where things are"},{"anchor":"b0","slug":"tine-guide","text":"Tine Guide","title":"Tine Guide"},{"anchor":"b1","slug":"tine-guide","text":"Open this Guide beside your own graph when you want live examples without switching graphs.","title":"Tine Guide"},{"anchor":"b2","slug":"tine-guide","text":"Each page is read-only here. Use Copy the guide into your graph on any Guide page when you want an editable, interlinked sandbox under tine-guide/.","title":"Tine Guide"},{"anchor":"b3","slug":"tine-guide","text":"Start","title":"Tine Guide"},{"anchor":"b4","slug":"tine-guide","text":"Welcome to Tine — tour the basics hands-on: bullets, tasks, rich text, links, and live block references.","title":"Tine Guide"},{"anchor":"b5","slug":"tine-guide","text":"Start/Where things are — map the main places: the page, the left sidebar, tabs, the right sidebar, and Settings and Help.","title":"Tine Guide"},{"anchor":"b6","slug":"tine-guide","text":"Start/Bring an existing graph — point Tine at your existing Logseq graph and learn what it reads and writes.","title":"Tine Guide"},{"anchor":"b7","slug":"tine-guide","text":"Project/Roadmap — try a few example tasks for your first steps.","title":"Tine Guide"},{"anchor":"b8","slug":"tine-guide","text":"Workflows","title":"Tine Guide"},{"anchor":"b9","slug":"tine-guide","text":"Workflows/Keep context visible — park a source in the right sidebar, keep places in tabs and panes, and save the layout as a workspace.","title":"Tine Guide"},{"anchor":"b10","slug":"tine-guide","text":"Workflows/Structure repeated information — turn a small repeated outline into a table or board, then find and reuse its blocks before reaching for query syntax.","title":"Tine Guide"},{"anchor":"b11","slug":"tine-guide","text":"Workflows/Capture and plan your day — journal-first daily flow: tasks, priorities, dates, the agenda, and carrying leftovers forward.","title":"Tine Guide"},{"anchor":"b12","slug":"tine-guide","text":"Workflows/Find and revisit — jump back to anything with Ctrl+K and follow links and reference panels.","title":"Tine Guide"},{"anchor":"b13","slug":"tine-guide","text":"Workflows/Research a document — bring in a PDF, highlight it, and tie the highlights into your notes beside the source.","title":"Tine Guide"},{"anchor":"b14","slug":"tine-guide","text":"Workflows/Extend Tine — install a plugin or theme, see exactly what authority it receives, and disable or remove it safely.","title":"Tine Guide"},{"anchor":"b15","slug":"tine-guide","text":"Workflows/Customize Tine's look — pick a color scheme, then change colors, fonts, widths, bullets, and embed shading with a few lines in logseq/custom.css, using documented --tine-* tokens and ten copy-paste recipes.","title":"Tine Guide"},{"anchor":"b16","slug":"tine-guide","text":"Features/Sheets — create grids, tables, boards, queries, and formulas over ordinary bullets.","title":"Tine Guide"},{"anchor":"b17","slug":"tine-guide","text":"Features/Queries — keep live lists of matching blocks and pages with simple or advanced queries.","title":"Tine Guide"},{"anchor":"b18","slug":"tine-guide","text":"Features/Formulas — build read-only computed columns with the visual formula editor.","title":"Tine Guide"},{"anchor":"b19","slug":"tine-guide","text":"Features/Quick capture — set up a global capture box that files notes into your graph.","title":"Tine Guide"},{"anchor":"b20","slug":"tine-guide","text":"Features/PDF annotation — highlight PDFs and turn those highlights into linked note blocks.","title":"Tine Guide"},{"anchor":"b21","slug":"tine-guide","text":"Feature reference","title":"Tine Guide"},{"anchor":"b22","slug":"tine-guide","text":"Features/Plugins — install capability-limited extensions and token themes, review what they request, and keep them under your control.","title":"Tine Guide"},{"anchor":"b23","slug":"tine-guide","text":"Features/Tips & shortcuts — learn Ctrl+K, slash commands, tabs, sidebars, focus mode, and daily shortcuts.","title":"Tine Guide"},{"anchor":"b24","slug":"tine-guide","text":"Reference/Files, external edits, and backups — learn what Tine writes where, and where snapshots, conflict copies, and the trash live.","title":"Tine Guide"},{"anchor":"b25","slug":"tine-guide","text":"Reference/Troubleshooting and recovery — follow numbered recovery steps for the changed-on-disk banner, deleted pages, snapshots, conflict copies, duplicate days, a graph that will not open, and a region that fails to display.","title":"Tine Guide"},{"anchor":"b26","slug":"tine-guide","text":"Reference/Journals, tasks, and scheduling — map journal setup, task markers and priorities, scheduling dates, the agenda, time tracking, and repeating tasks.","title":"Tine Guide"},{"anchor":"b27","slug":"tine-guide","text":"Reference/Pages, links, references, and search — the exact rules for pages, links, tags, aliases, block references, reference panels, and every search surface.","title":"Tine Guide"},{"anchor":"b28","slug":"tine-guide","text":"Reference/Tine query model — every way a query's answer can differ from Logseq's, and why.","title":"Tine Guide"},{"anchor":"b29","slug":"tine-guide","text":"Reference/Command line — read and search a graph from a terminal, understand the app/serve owner handover, open Quick Capture, check a graph, or publish an export.","title":"Tine Guide"},{"anchor":"b30","slug":"tine-guide","text":"Reference/Platforms and mobile — learn what changes on a narrow window versus on the Android app, and what ships on each platform today.","title":"Tine Guide"},{"anchor":"b31","slug":"tine-guide","text":"Feature showcase","title":"Tine Guide"},{"anchor":"b32","slug":"tine-guide","text":"Feature showcase — inspect one live example of each supported Logseq rendering feature.","title":"Tine Guide"},{"anchor":"b33","slug":"tine-guide","text":"Create one yourself","title":"Tine Guide"},{"anchor":"b34","slug":"tine-guide","text":"1. Open one of the Guide pages above and follow its numbered steps.","title":"Tine Guide"},{"anchor":"b35","slug":"tine-guide","text":"2. Use Copy the guide into your graph when you want an editable sandbox.","title":"Tine Guide"},{"anchor":"b36","slug":"tine-guide","text":"3. Tine creates the real tine-guide/ namespace, rewrites guide links to that copy, and leaves existing copied pages untouched.","title":"Tine Guide"},{"anchor":"b37","slug":"tine-guide","text":"4. What you should see: normal Logseq pages you can edit, delete, or keep as a reference.","title":"Tine Guide"},{"anchor":"b0","slug":"welcome-to-tine","text":"Welcome to Tine 👋","title":"Welcome to Tine"},{"anchor":"b1","slug":"welcome-to-tine","text":"Tine is a fast, local outliner that reads and writes the same Markdown files as Logseq — the very folder you point it at. Edit here or in Logseq; it's one graph, no import, no export. We have a lot of respect for Logseq — Tine just tries to improve a few things.","title":"Welcome to Tine"},{"anchor":"b2","slug":"welcome-to-tine","text":"Everything you see here is a real Markdown file in this graph's pages/ folder. Open that folder in your file manager and look — nothing is locked away.","title":"Welcome to Tine"},{"anchor":"b3","slug":"welcome-to-tine","text":"Try the basics right now","title":"Welcome to Tine"},{"anchor":"b4","slug":"welcome-to-tine","text":"Click any bullet to edit it. Enter makes a new bullet, Tab indents, Shift+Tab outdents. Drag a bullet's dot to move it (and everything under it).","title":"Welcome to Tine"},{"anchor":"b5","slug":"welcome-to-tine","text":"Tasks — type TODO / DOING / DONE at the start of a bullet, or press Ctrl+Enter to cycle one; clicking a TODO/DOING (or LATER/NOW) label flips between the pair and never clears DONE:","title":"Welcome to Tine"},{"anchor":"b6","slug":"welcome-to-tine","text":"Click this checkbox to complete me","title":"Welcome to Tine"},{"anchor":"b7","slug":"welcome-to-tine","text":"This one is already done","title":"Welcome to Tine"},{"anchor":"b8","slug":"welcome-to-tine","text":"Rich text: bold, italic, highlight, inline code, and even math like e^{i\\pi} + 1 = 0.","title":"Welcome to Tine"},{"anchor":"b9","slug":"welcome-to-tine","text":"Links: type [[ to link a page or # for a #tag; a suggestion that is an alias is labelled alias of its page. Here's a link to Project/Roadmap — click it.","title":"Welcome to Tine"},{"anchor":"b10","slug":"welcome-to-tine","text":"Block references & embeds","title":"Welcome to Tine"},{"anchor":"b11","slug":"welcome-to-tine","text":"Every bullet has a hidden id, so you can point at one specific bullet from anywhere. This is a live reference to a bullet over on the Roadmap:","title":"Welcome to Tine"},{"anchor":"b12","slug":"welcome-to-tine","text":"And here is that same bullet embedded inline — it stays in sync with the original:","title":"Welcome to Tine"},{"anchor":"b14","slug":"welcome-to-tine","text":"Keep exploring","title":"Welcome to Tine"},{"anchor":"b15","slug":"welcome-to-tine","text":"Tine Guide — open the in-app how-to guide beside your own graph, with live examples you can copy into a sandbox.","title":"Welcome to Tine"},{"anchor":"b16","slug":"welcome-to-tine","text":"Start/Where things are — a map of the main places: the page, the sidebars, tabs, and Settings and Help.","title":"Welcome to Tine"},{"anchor":"b17","slug":"welcome-to-tine","text":"Features/Quick capture — drop a thought into your graph from any app with a global hotkey. (Set this one up — it's genuinely good.)","title":"Welcome to Tine"},{"anchor":"b18","slug":"welcome-to-tine","text":"Features/Tips & shortcuts — slash commands, the command palette, tabs, the sidebar, focus mode and dimming.","title":"Welcome to Tine"},{"anchor":"b19","slug":"welcome-to-tine","text":"Features/Sheets — grids, field tables, and task boards over plain bullets.","title":"Welcome to Tine"},{"anchor":"b20","slug":"welcome-to-tine","text":"Features/PDF annotation — highlight PDFs and turn them into linked notes.","title":"Welcome to Tine"},{"anchor":"b21","slug":"welcome-to-tine","text":"Features/Plugins — add small capability-limited extensions or token themes without giving code unrestricted access to Tine.","title":"Welcome to Tine"},{"anchor":"b22","slug":"welcome-to-tine","text":"When you're ready, point Tine at your own Logseq graph: open Settings (t s) and pick a different folder — Start/Bring an existing graph walks you through it. Your notes stay exactly where they are.","title":"Welcome to Tine"},{"anchor":"b0","slug":"workflows-capture-and-plan-your-day","text":"Capture and plan your day","title":"Workflows/Capture and plan your day"},{"anchor":"b1","slug":"workflows-capture-and-plan-your-day","text":"The shortest path: open Journals in the sidebar and start typing. Everything below adds one tool at a time — a task marker, a priority, a date — and ends with the two things that keep a plan current: the Agenda and carry-over.","title":"Workflows/Capture and plan your day"},{"anchor":"b2","slug":"workflows-capture-and-plan-your-day","text":"Describe your day in bullets","title":"Workflows/Capture and plan your day"},{"anchor":"b3","slug":"workflows-capture-and-plan-your-day","text":"1. Click Journals in the sidebar — the feed opens with today first (today is the current day on this machine's local calendar, and it rolls over at local midnight). Click into today's first bullet and type what happened or what you mean to do.","title":"Workflows/Capture and plan your day"},{"anchor":"b4","slug":"workflows-capture-and-plan-your-day","text":"2. Press Enter for the next bullet, Tab / Shift+Tab to nest or flatten it.","title":"Workflows/Capture and plan your day"},{"anchor":"b5","slug":"workflows-capture-and-plan-your-day","text":"3. To put a bullet above an existing one, press Enter with the caret at its very start. Some bullets keep Enter for themselves — inside a code block it adds a line of code — so for those, right-click the bullet's dot and choose Insert block above.","title":"Workflows/Capture and plan your day"},{"anchor":"b6","slug":"workflows-capture-and-plan-your-day","text":"4. What you should see: the text saves to today's journal file on its own — there is no Save button. For where writes go and what happens if a file changes on disk, see Reference/Files, external edits, and backups.","title":"Workflows/Capture and plan your day"},{"anchor":"b7","slug":"workflows-capture-and-plan-your-day","text":"Not at your desk? Quick capture","title":"Workflows/Capture and plan your day"},{"anchor":"b8","slug":"workflows-capture-and-plan-your-day","text":"When a thought arrives while you are in another app, press your desktop quick-capture shortcut, type, and the note is appended to today's journal without switching windows. One-time setup, the optional page-title field, and the Enter-key tuning are all in Features/Quick capture.","title":"Workflows/Capture and plan your day"},{"anchor":"b9","slug":"workflows-capture-and-plan-your-day","text":"Turn a bullet into a task","title":"Workflows/Capture and plan your day"},{"anchor":"b10","slug":"workflows-capture-and-plan-your-day","text":"1. With the caret anywhere in a bullet, press Ctrl+Enter (Cmd on Mac). The bullet becomes TODO …; press again for DOING, again for DONE, once more to drop the marker. (Under the NOW / LATER workflow — the default — the cycle is LATER → NOW → DONE.)","title":"Workflows/Capture and plan your day"},{"anchor":"b11","slug":"workflows-capture-and-plan-your-day","text":"2. Prefer the mouse? Click the marker chip to toggle between the workflow's two open states (TODO ↔ DOING or LATER ↔ NOW), or click the checkbox in front of the task to finish it in one step.","title":"Workflows/Capture and plan your day"},{"anchor":"b12","slug":"workflows-capture-and-plan-your-day","text":"3. Select several blocks first and the same keypress cycles every selected task at once.","title":"Workflows/Capture and plan your day"},{"anchor":"b13","slug":"workflows-capture-and-plan-your-day","text":"4. What you should see: a colored marker chip at the start of the block, plus an empty checkbox until the task is done.","title":"Workflows/Capture and plan your day"},{"anchor":"b14","slug":"workflows-capture-and-plan-your-day","text":"Rank it","title":"Workflows/Capture and plan your day"},{"anchor":"b15","slug":"workflows-capture-and-plan-your-day","text":"Type / and choose Priority A (or B, C) — the marker line becomes TODO [#A] Call the bank.","title":"Workflows/Capture and plan your day"},{"anchor":"b16","slug":"workflows-capture-and-plan-your-day","text":"What you should see: a colored [#A] chip right after the marker; swap it by running the command again.","title":"Workflows/Capture and plan your day"},{"anchor":"b17","slug":"workflows-capture-and-plan-your-day","text":"Give it a date","title":"Workflows/Capture and plan your day"},{"anchor":"b18","slug":"workflows-capture-and-plan-your-day","text":"1. Type / and choose Scheduled, then pick the day in the calendar popup — use + Add time if the hour matters.","title":"Workflows/Capture and plan your day"},{"anchor":"b19","slug":"workflows-capture-and-plan-your-day","text":"2. Add Deadline the same way when the task has a hard due date.","title":"Workflows/Capture and plan your day"},{"anchor":"b20","slug":"workflows-capture-and-plan-your-day","text":"3. What you should see: a small calendar chip next to the block for each date. Click a chip any time to change or remove it.","title":"Workflows/Capture and plan your day"},{"anchor":"b21","slug":"workflows-capture-and-plan-your-day","text":"Try it: from bullets to an open-task query","title":"Workflows/Capture and plan your day"},{"anchor":"b22","slug":"workflows-capture-and-plan-your-day","text":"Copy this Guide into your graph and look at these example tasks:","title":"Workflows/Capture and plan your day"},{"anchor":"b23","slug":"workflows-capture-and-plan-your-day","text":"Collect the audit receipts","title":"Workflows/Capture and plan your day"},{"anchor":"b24","slug":"workflows-capture-and-plan-your-day","text":"Book the flights","title":"Workflows/Capture and plan your day"},{"anchor":"b25","slug":"workflows-capture-and-plan-your-day","text":"Read the harvest notes","title":"Workflows/Capture and plan your day"},{"anchor":"b26","slug":"workflows-capture-and-plan-your-day","text":"Water the office plants","title":"Workflows/Capture and plan your day"},{"anchor":"b27","slug":"workflows-capture-and-plan-your-day","text":"Then this query lists them:","title":"Workflows/Capture and plan your day"},{"anchor":"b29","slug":"workflows-capture-and-plan-your-day","text":"What you should see: the marked tasks above, plus tasks elsewhere in the graph that use TODO, DOING, NOW, or LATER (the Feature showcase has a few; a copied Guide adds your own). The query covers the whole graph — a task written on any page turns up here, not just the ones on this page; DONE tasks and tasks using other markers do not appear.","title":"Workflows/Capture and plan your day"},{"anchor":"b30","slug":"workflows-capture-and-plan-your-day","text":"See the plan: the Agenda","title":"Workflows/Capture and plan your day"},{"anchor":"b31","slug":"workflows-capture-and-plan-your-day","text":"1. Look at the bottom of today's block in the Journals feed (the first day): the Scheduled & Deadline list shows open items whose date is near today, wherever in the graph they were written.","title":"Workflows/Capture and plan your day"},{"anchor":"b32","slug":"workflows-capture-and-plan-your-day","text":"2. What you should see: your dated tasks, each with its date chip; click one to jump to it. Widen or narrow the range in Settings → Journals → Agenda window (default: a week back and a week ahead). The Agenda sits under today in the feed, not on a journal page you opened by itself, and the list vanishes when nothing is dated in range.","title":"Workflows/Capture and plan your day"},{"anchor":"b33","slug":"workflows-capture-and-plan-your-day","text":"Carry-over: let unfinished tasks follow you","title":"Workflows/Capture and plan your day"},{"anchor":"b34","slug":"workflows-capture-and-plan-your-day","text":"1. Scroll to a past day in the feed, hover its title row (or focus a title-row control with the keyboard), and click Carry unfinished tasks → today under its title. Blocks with open markers move to today; DONE and CANCELED stay put.","title":"Workflows/Capture and plan your day"},{"anchor":"b35","slug":"workflows-capture-and-plan-your-day","text":"On touch devices without hover, the carry buttons stay visible. The same controls appear on a journal page opened by itself.","title":"Workflows/Capture and plan your day"},{"anchor":"b36","slug":"workflows-capture-and-plan-your-day","text":"2. What you should see: a \"Carried N items to today\" toast — or \"No unfinished tasks to carry\" if none were open.","title":"Workflows/Capture and plan your day"},{"anchor":"b37","slug":"workflows-capture-and-plan-your-day","text":"3. Variants: on today, Carry from previous day pulls the latest earlier day in; Carry last N days goes further back (N is set in Settings, default 7). The past-day action is also on that day's right-click menu, and the command palette (Ctrl+Shift+P) has 7 / 30 / 365-day presets.","title":"Workflows/Capture and plan your day"},{"anchor":"b38","slug":"workflows-capture-and-plan-your-day","text":"Settings → Journals also tunes it: hide the buttons (the right-click menu keeps working), move the whole block with its context or just the task line, add a “Carried over” heading.","title":"Workflows/Capture and plan your day"},{"anchor":"b39","slug":"workflows-capture-and-plan-your-day","text":"Where everything lives","title":"Workflows/Capture and plan your day"},{"anchor":"b40","slug":"workflows-capture-and-plan-your-day","text":"All of this remains plain text. Journal entries use the graph's configured journal directory; tasks on ordinary pages stay in their own Markdown or Org files. Within a task, the marker comes first, then [#A], then the SCHEDULED:/DEADLINE: lines — readable by Logseq and by any editor. The companion reference page Reference/Journals, tasks, and scheduling maps the marker set, repeaters, time tracking, and the stored query behind the Agenda. If something looks wrong — a banner, a conflict copy, a duplicate day — Reference/Troubleshooting and recovery has the recovery steps.","title":"Workflows/Capture and plan your day"},{"anchor":"b0","slug":"workflows-customize-tine-s-look","text":"Customize Tine's look","title":"Workflows/Customize Tine's look"},{"anchor":"b1","slug":"workflows-customize-tine-s-look","text":"Change colors, fonts, widths, bullets, and embed shading without a plugin: write a few lines of CSS in your graph's logseq/custom.css. This page shows where the file is, which names Tine promises to keep stable (the --tine-* tokens), ten copy-paste recipes, and how to find out what styles any element.","title":"Workflows/Customize Tine's look"},{"anchor":"b2","slug":"workflows-customize-tine-s-look","text":"1. Start from a color scheme","title":"Workflows/Customize Tine's look"},{"anchor":"b3","slug":"workflows-customize-tine-s-look","text":"1. Open Settings (t s) → Appearance and look at Color scheme. Default, Nord, Solarized, Gruvbox, and Soft are built in. Soft is a medium-brightness palette: warm gray in light mode and lifted slate gray in dark mode, with warm highlights and quiet active tabs. Its page, sidebars, menus, and code surfaces move together while text stays readable.","title":"Workflows/Customize Tine's look"},{"anchor":"b4","slug":"workflows-customize-tine-s-look","text":"2. Pick one. It applies at once and is remembered on this device.","title":"Workflows/Customize Tine's look"},{"anchor":"b5","slug":"workflows-customize-tine-s-look","text":"3. Precedence, lowest to highest: Tine's stock palette, then the color scheme you picked, then the Fine-tuning choices below, then device-wide global.css, then your graph's logseq/custom.css. Your CSS always has the last word, and an installed theme package never edits it. A Style preset such as editorial reading type keeps its own look, but the font and size tokens below still override its fonts and text size.","title":"Workflows/Customize Tine's look"},{"anchor":"b6","slug":"workflows-customize-tine-s-look","text":"4. Open Advanced in Appearance for Fine-tuning, a few visual details that are not worth a theme of their own. Embedded blocks shows embeds as a shaded box (the default) or with only the accent line and dot. Links to the web or a file is a solid underline (the default), a dotted one, or none; links to pages never have one, so the two kinds read differently. Links to pages that do not exist yet is the dimmed link color (the default), a stronger one, or the same color as other links. Every choice starts at Tine's default look, takes effect at once, and has its own Reset. Settings search also finds these controls and opens Advanced.","title":"Workflows/Customize Tine's look"},{"anchor":"b7","slug":"workflows-customize-tine-s-look","text":"Arrows and dashes (->, <-, =>, --, ---) show exactly as you typed them, as in Logseq. To see them as glyphs (→, ⇒, –, —), set Settings → Appearance → Typographic replacements to On (while reading), which changes only what you see and leaves your Markdown as typed, or On (while typing), which rewrites the text itself as you type. It is Off by default; a device that used the earlier default, where arrows were drawn as glyphs, needs to pick On (while reading) once.","title":"Workflows/Customize Tine's look"},{"anchor":"b8","slug":"workflows-customize-tine-s-look","text":"Fine-tuning choices are saved on this device (under style.knobs.v1 in Tine's device settings), never in your graph, so they do not follow the graph to another computer. Disable custom CSS switches them off for the session along with your stylesheet, and your custom.css outranks them.","title":"Workflows/Customize Tine's look"},{"anchor":"b9","slug":"workflows-customize-tine-s-look","text":"Block embed breadcrumbs is off by default. Turn it on to show a muted source page and parent trail above block embeds.","title":"Workflows/Customize Tine's look"},{"anchor":"b10","slug":"workflows-customize-tine-s-look","text":"What you should see: the whole window recolors together. Anything you then set in custom.css overrides only what you set. A Fine-tuning choice changes its one detail at once and Reset puts it back.","title":"Workflows/Customize Tine's look"},{"anchor":"b11","slug":"workflows-customize-tine-s-look","text":"2. Open your custom.css","title":"Workflows/Customize Tine's look"},{"anchor":"b12","slug":"workflows-customize-tine-s-look","text":"1. Settings → Appearance → Advanced → Custom CSS → Edit custom.css opens logseq/custom.css in Tine's text editor, including on mobile. Or press Ctrl+K (Cmd+K on macOS), type css or custom.css, and choose Edit custom.css. A missing file starts empty and is created only when you save.","title":"Workflows/Customize Tine's look"},{"anchor":"b13","slug":"workflows-customize-tine-s-look","text":"2. Press Save to apply changes immediately, or Save and close to return to your notes. If another editor or a sync tool changed the file, Tine refuses to overwrite it and keeps your text open. Copy your edits before choosing Reload from disk, then combine them with the latest file and save again.","title":"Workflows/Customize Tine's look"},{"anchor":"b14","slug":"workflows-customize-tine-s-look","text":"Switching apps or backgrounding Tine starts saving CSS alongside your pages. If a conflict refuses the save, reopening the same CSS file restores the recoverable draft with its original revision; copy it before reloading from disk.","title":"Workflows/Customize Tine's look"},{"anchor":"b15","slug":"workflows-customize-tine-s-look","text":"3. Edit global CSS opens global.css in Tine's per-user config directory, outside every graph. It applies to every graph on this device and loads before each graph's custom.css, so the graph can override it. The quick switcher also finds Edit global CSS (global.css). Saving applies it across open graph windows. This device file does not travel with a synced graph.","title":"Workflows/Customize Tine's look"},{"anchor":"b16","slug":"workflows-customize-tine-s-look","text":"What you should see: a rule such as :root { --tine-bullet-color: orange; } recolors every bullet as soon as you save.","title":"Workflows/Customize Tine's look"},{"anchor":"b17","slug":"workflows-customize-tine-s-look","text":"Something went wrong? Settings → Appearance → Advanced → Custom CSS → Disable custom CSS ignores both CSS files and Fine-tuning for this session only. It is never saved, so restarting Tine always brings custom CSS back; fix the file, then switch it back on. If the stylesheet hides Settings itself, open the command palette (Mod+Shift+P) and run Toggle custom CSS (safe mode, this session).","title":"Workflows/Customize Tine's look"},{"anchor":"b18","slug":"workflows-customize-tine-s-look","text":"3. The supported names: --tine-* tokens","title":"Workflows/Customize Tine's look"},{"anchor":"b19","slug":"workflows-customize-tine-s-look","text":"A token is a named setting. Each starts unset, which means \"use the theme's default\", so nothing changes until you set one. Set tokens on :root or html, like the recipes below; any selector you write wins over Tine's own, because Tine declares them with no specificity. These sixteen names are the ones Tine promises to keep: if one is ever removed or renamed, the changelog says so.","title":"Workflows/Customize Tine's look"},{"anchor":"b20","slug":"workflows-customize-tine-s-look","text":"Token Controls Default --tine-danger-color Error and destructive-action text and error borders (also the asset trash button's hover fill) A contrast-checked red for the theme's light or dark mode --tine-embed-bg Background of an embedded block or page The theme's secondary background --tine-embed-accent The accent line and bullet of an embedded block 35% accent mixed into the bullet color --tine-bullet-color Color of the block bullet dot The theme's bullet color --tine-bullet-size Diameter of the block bullet dot 6px --tine-tag-color Color of #tags and tag chips The theme's tag color --tine-highlight-bg Background of ^^highlighted^^ text The theme's highlight color --tine-missing-page-color Color of a link to a page that does not exist yet A dimmed tint of the link color --tine-external-link-underline The line under a link to a web address or file 1px solid (use none to remove it) --tine-content-width Maximum width of the page column 810px --tine-content-width-wide Maximum width of the column in Wide mode 100% --tine-page-title-size Font size of a page title 28px --tine-font-size Base font size of page text 16px --tine-content-font Font family of the interface and page text Inter, then your system fonts --tine-mono-font Font family of code and other monospace text MonoLisa, then your system mono fonts --tine-editable-font Font family of text while you edit it Inter, then the emoji font, then your system fonts","title":"Workflows/Customize Tine's look"},{"anchor":"b21","slug":"workflows-customize-tine-s-look","text":"The code and formula editors always edit in the monospace face, so --tine-editable-font does not reach them; --tine-mono-font does.","title":"Workflows/Customize Tine's look"},{"anchor":"b22","slug":"workflows-customize-tine-s-look","text":"Colors beyond these still use Logseq's --ls-* variables (for example --ls-primary-background-color), exactly as in Logseq, so a Logseq snippet you already have keeps working.","title":"Workflows/Customize Tine's look"},{"anchor":"b23","slug":"workflows-customize-tine-s-look","text":"The page widths you set in Settings → Appearance → Advanced (Standard page width, Wide page width) outrank --tine-content-width and --tine-content-width-wide. Reset those two fields if a token seems to have no effect.","title":"Workflows/Customize Tine's look"},{"anchor":"b24","slug":"workflows-customize-tine-s-look","text":"4. Ten copy-paste recipes","title":"Workflows/Customize Tine's look"},{"anchor":"b25","slug":"workflows-customize-tine-s-look","text":"Paste any of these into logseq/custom.css and save. Combine as many as you like.","title":"Workflows/Customize Tine's look"},{"anchor":"b26","slug":"workflows-customize-tine-s-look","text":"Remove the shade behind embedded blocks:","title":"Workflows/Customize Tine's look"},{"anchor":"b27","slug":"workflows-customize-tine-s-look","text":":root { --tine-embed-bg: transparent; }","title":"Workflows/Customize Tine's look"},{"anchor":"b28","slug":"workflows-customize-tine-s-look","text":"Give embedded blocks a warm accent instead of the theme's:","title":"Workflows/Customize Tine's look"},{"anchor":"b29","slug":"workflows-customize-tine-s-look","text":":root { --tine-embed-accent: #d97706; }","title":"Workflows/Customize Tine's look"},{"anchor":"b30","slug":"workflows-customize-tine-s-look","text":"Change the bullet color, and make bullets a little bigger:","title":"Workflows/Customize Tine's look"},{"anchor":"b31","slug":"workflows-customize-tine-s-look","text":":root { --tine-bullet-color: #d97706; --tine-bullet-size: 8px; }","title":"Workflows/Customize Tine's look"},{"anchor":"b32","slug":"workflows-customize-tine-s-look","text":"A wider page column, in normal and in Wide mode:","title":"Workflows/Customize Tine's look"},{"anchor":"b33","slug":"workflows-customize-tine-s-look","text":":root { --tine-content-width: 1100px; --tine-content-width-wide: 1500px; }","title":"Workflows/Customize Tine's look"},{"anchor":"b34","slug":"workflows-customize-tine-s-look","text":"A different reading font, for display and for editing (it also overrides the editorial reading style). Keep var(--tine-editable-emoji-font) in the editing list; it protects emoji from crashing some Linux systems:","title":"Workflows/Customize Tine's look"},{"anchor":"b35","slug":"workflows-customize-tine-s-look","text":":root { --tine-content-font: Georgia, \"Times New Roman\", serif; --tine-editable-font: Georgia, var(--tine-editable-emoji-font), serif; }","title":"Workflows/Customize Tine's look"},{"anchor":"b36","slug":"workflows-customize-tine-s-look","text":"Larger text everywhere the base size applies:","title":"Workflows/Customize Tine's look"},{"anchor":"b37","slug":"workflows-customize-tine-s-look","text":":root { --tine-font-size: 18px; }","title":"Workflows/Customize Tine's look"},{"anchor":"b38","slug":"workflows-customize-tine-s-look","text":"A different code font:","title":"Workflows/Customize Tine's look"},{"anchor":"b39","slug":"workflows-customize-tine-s-look","text":":root { --tine-mono-font: \"Fira Code\", Consolas, monospace; }","title":"Workflows/Customize Tine's look"},{"anchor":"b40","slug":"workflows-customize-tine-s-look","text":"A different tag color and highlight color:","title":"Workflows/Customize Tine's look"},{"anchor":"b41","slug":"workflows-customize-tine-s-look","text":":root { --tine-tag-color: #0d9488; --tine-highlight-bg: #fde68a; }","title":"Workflows/Customize Tine's look"},{"anchor":"b42","slug":"workflows-customize-tine-s-look","text":"Smaller page titles:","title":"Workflows/Customize Tine's look"},{"anchor":"b43","slug":"workflows-customize-tine-s-look","text":":root { --tine-page-title-size: 22px; }","title":"Workflows/Customize Tine's look"},{"anchor":"b44","slug":"workflows-customize-tine-s-look","text":"A different value only in dark mode (Tine marks the window light or dark):","title":"Workflows/Customize Tine's look"},{"anchor":"b45","slug":"workflows-customize-tine-s-look","text":"html[data-theme=\"dark\"] { --tine-bullet-color: #fbbf24; }","title":"Workflows/Customize Tine's look"},{"anchor":"b46","slug":"workflows-customize-tine-s-look","text":"Recolor the page itself with a Logseq variable, light mode only:","title":"Workflows/Customize Tine's look"},{"anchor":"b47","slug":"workflows-customize-tine-s-look","text":"html[data-theme=\"light\"] { --ls-primary-background-color: #fdf6e3; }","title":"Workflows/Customize Tine's look"},{"anchor":"b48","slug":"workflows-customize-tine-s-look","text":"5. Find out what styles an element","title":"Workflows/Customize Tine's look"},{"anchor":"b49","slug":"workflows-customize-tine-s-look","text":"1. Settings → Appearance → Advanced → Custom CSS → Developer tools (desktop), or press Ctrl+Shift+J (Cmd+Shift+J on macOS), opens the inspector. It is part of every desktop build, release builds included. Use its element picker, then read the Styles pane.","title":"Workflows/Customize Tine's look"},{"anchor":"b50","slug":"workflows-customize-tine-s-look","text":"2. Look for a var(--tine-…) or var(--ls-…) in the rule that draws what you want to change. Setting that variable in custom.css is the stable way to change it.","title":"Workflows/Customize Tine's look"},{"anchor":"b51","slug":"workflows-customize-tine-s-look","text":"3. When no variable exists, a class selector such as .embed-block works today, but class names and the structure of the page can change between releases, so a rule written that way may need a touch-up after an update. Prefer a token.","title":"Workflows/Customize Tine's look"},{"anchor":"b52","slug":"workflows-customize-tine-s-look","text":"What you should see: the inspector opens and highlights the element you point at, with its rules listed in the Styles pane.","title":"Workflows/Customize Tine's look"},{"anchor":"b53","slug":"workflows-customize-tine-s-look","text":"6. If it does not look right","title":"Workflows/Customize Tine's look"},{"anchor":"b54","slug":"workflows-customize-tine-s-look","text":"A token seems to do nothing: check that you set it on :root or html (or html[data-theme=\"dark\"]) and that the page-width Settings fields are reset for the two width tokens.","title":"Workflows/Customize Tine's look"},{"anchor":"b55","slug":"workflows-customize-tine-s-look","text":"The whole window became unreadable: Disable custom CSS in Settings, or restart Tine with the file edited.","title":"Workflows/Customize Tine's look"},{"anchor":"b56","slug":"workflows-customize-tine-s-look","text":"If a custom.css could not be read message appears, fix the file's permissions or size with an external text editor, then try Edit custom.css again.","title":"Workflows/Customize Tine's look"},{"anchor":"b57","slug":"workflows-customize-tine-s-look","text":"Where next","title":"Workflows/Customize Tine's look"},{"anchor":"b58","slug":"workflows-customize-tine-s-look","text":"Workflows/Extend Tine covers theme packages and plugins.","title":"Workflows/Customize Tine's look"},{"anchor":"b59","slug":"workflows-customize-tine-s-look","text":"Reference/Files, external edits, and backups explains what else lives in your graph's logseq/ folder.","title":"Workflows/Customize Tine's look"},{"anchor":"b0","slug":"workflows-extend-tine","text":"Extend Tine","title":"Workflows/Extend Tine"},{"anchor":"b1","slug":"workflows-extend-tine","text":"Add a plugin or a theme in a few minutes, know exactly what authority you granted, and take it back cleanly. This page is the hands-on path; the detailed rulebook stays on Features/Plugins.","title":"Workflows/Extend Tine"},{"anchor":"b2","slug":"workflows-extend-tine","text":"Know what a plugin can touch before you install one","title":"Workflows/Extend Tine"},{"anchor":"b3","slug":"workflows-extend-tine","text":"Tine plugins are capability-limited WebAssembly guests. They are not Logseq or Obsidian plugins, and plugins written for those apps do not run here.","title":"Workflows/Extend Tine"},{"anchor":"b4","slug":"workflows-extend-tine","text":"The plugin API is experimental. An app update may leave an incompatible plugin installed but disabled; it must not make your graph unreadable or discard the plugin's local settings.","title":"Workflows/Extend Tine"},{"anchor":"b5","slug":"workflows-extend-tine","text":"A plugin declares capabilities from a short, closed list, and Tine performs each one on its behalf: command-palette actions, slash commands, small block decorations (thread lines, badges), declarative settings, and narrowly preconditioned edits to a focused block.","title":"Workflows/Extend Tine"},{"anchor":"b6","slug":"workflows-extend-tine","text":"A plugin cannot access the DOM, Tauri, the network, files, processes, or your graph directly, and it cannot inject HTML or CSS — everything it shows is drawn by Tine. The one capability that can change your text is graph.write.block, and even it may edit only the block Tine handed the plugin, and only if that block's text is unchanged since Tine handed it over.","title":"Workflows/Extend Tine"},{"anchor":"b7","slug":"workflows-extend-tine","text":"Install one — it starts disabled","title":"Workflows/Extend Tine"},{"anchor":"b8","slug":"workflows-extend-tine","text":"1. Open Settings (t s) → Plugins → Browse. Each community-catalogue entry lists its source, license, supported platforms, and declared capabilities, plus a safety verdict — \"Automated review passed\", \"Low-risk automated pass\", or \"Human-reviewed before publication\". Open its Safety report for the digest-verified detail, and keep the reminder under it in mind: automated review is evidence, not a guarantee.","title":"Workflows/Extend Tine"},{"anchor":"b9","slug":"workflows-extend-tine","text":"2. Choose Install. Nothing runs yet — every plugin version is installed disabled, and Tine takes you to the Installed tab with its details open.","title":"Workflows/Extend Tine"},{"anchor":"b10","slug":"workflows-extend-tine","text":"3. Review what it claims: name, version, author, license, platforms, capabilities. If they match what you expected, flip the toggle to enable it.","title":"Workflows/Extend Tine"},{"anchor":"b11","slug":"workflows-extend-tine","text":"4. Developing or sideloading instead? Install a local package (under Browse, button Choose package…) takes a manifest.json and its .wasm file together — with the same installed-disabled rule.","title":"Workflows/Extend Tine"},{"anchor":"b12","slug":"workflows-extend-tine","text":"What you should see: exactly the contribution the plugin declared — a command-palette entry, a slash command, or a decoration — and nothing else. If the package does not support your device, its button reads Unavailable on … instead of Install.","title":"Workflows/Extend Tine"},{"anchor":"b13","slug":"workflows-extend-tine","text":"Change its settings — Tine's controls, your device","title":"Workflows/Extend Tine"},{"anchor":"b14","slug":"workflows-extend-tine","text":"A plugin that declares settings gets a Settings section on its details page (Settings… beside it in the Installed list), but Tine draws the controls — toggles, dropdowns, numbers, text — from the plugin's declared schema. Values are validated scalars, stored on this device only and never written into your graph. A changed key offers Reset; Reset all settings restores the schema defaults.","title":"Workflows/Extend Tine"},{"anchor":"b15","slug":"workflows-extend-tine","text":"Disable it, or take it out","title":"Workflows/Extend Tine"},{"anchor":"b16","slug":"workflows-extend-tine","text":"Flip the same toggle (on the details page or in the Installed list) to disable: the behavior stops, the package stays installed, and your pages remain exactly as readable as before — a plugin may not invent a format your graph would depend on.","title":"Workflows/Extend Tine"},{"anchor":"b17","slug":"workflows-extend-tine","text":"Uninstall… removes only that package version from this device. Tine asks first and states the boundary: it removes the plugin from this device and does not change your graph or notes.","title":"Workflows/Extend Tine"},{"anchor":"b18","slug":"workflows-extend-tine","text":"Behind the scenes, signed revocations are checked before a saved plugin starts, so a version revoked as unsafe stays disabled even when the live catalogue is temporarily unavailable.","title":"Workflows/Extend Tine"},{"anchor":"b19","slug":"workflows-extend-tine","text":"Themes change presentation; they never run","title":"Workflows/Extend Tine"},{"anchor":"b20","slug":"workflows-extend-tine","text":"Themes live separately under Settings → Appearance. Style controls typography, journal headings, and other Tine-owned presentation styles; Color scheme selects Default, Nord, Solarized, Gruvbox, Soft, or the colors from an installed package. Style and colors are independent, so you can keep one package's style while using another palette. Declarative packages install from the Theme packages list or a local theme.json file (Choose theme.json…) and contain no scripts, selectors, imports, downloaded fonts, or remote assets. The choices stay on this device, and no theme ever reads or writes your graph.","title":"Workflows/Extend Tine"},{"anchor":"b21","slug":"workflows-extend-tine","text":"A Today summary, when selected, is rendered by Tine from the journal page already on screen: it counts open task markers there and calls the DOING, NOW, STARTED, and IN-PROGRESS subset “in progress.” The theme receives neither those tasks nor a query interface.","title":"Workflows/Extend Tine"},{"anchor":"b22","slug":"workflows-extend-tine","text":"Your own logseq/custom.css outranks every theme: themes recolor Tine through Logseq's --ls-* variables, and your CSS loads last. Uninstalling a theme package leaves it untouched, too. Workflows/Customize Tine's look shows how to open that file, the --tine-* tokens Tine keeps stable, and ten copy-paste recipes.","title":"Workflows/Extend Tine"},{"anchor":"b23","slug":"workflows-extend-tine","text":"Platform and distribution lines","title":"Workflows/Extend Tine"},{"anchor":"b24","slug":"workflows-extend-tine","text":"Desktop and Android share the same plugin and theme lifecycle; a package that did not declare your platform shows as unavailable rather than failing later.","title":"Workflows/Extend Tine"},{"anchor":"b25","slug":"workflows-extend-tine","text":"The F-Droid build omits the network community catalogue to comply with the store's runtime-code-download policy. The plugin host, your already-installed plugins and themes, local manifest.json + .wasm and theme packages, and the built-in gallery all keep working there.","title":"Workflows/Extend Tine"},{"anchor":"b26","slug":"workflows-extend-tine","text":"The iOS beta runs themes but not plugins: the iOS plugin host is not enabled yet. Reference/Platforms and mobile carries the full platform map.","title":"Workflows/Extend Tine"},{"anchor":"b27","slug":"workflows-extend-tine","text":"Where next","title":"Workflows/Extend Tine"},{"anchor":"b28","slug":"workflows-extend-tine","text":"Features/Plugins keeps the detailed reference, including the safety-report fields and the cascade order — and links the authoring, packaging, and registry guide used by plugin developers.","title":"Workflows/Extend Tine"},{"anchor":"b0","slug":"workflows-find-and-revisit","text":"Find and revisit","title":"Workflows/Find and revisit"},{"anchor":"b1","slug":"workflows-find-and-revisit","text":"Three moves cover most of finding things: jump to what you remember, follow the trail of links, and keep a search that's worth keeping. No syntax is needed up front. The exact rules live in Reference/Pages, links, references, and search.","title":"Workflows/Find and revisit"},{"anchor":"b2","slug":"workflows-find-and-revisit","text":"\"I saw it somewhere\" — jump with Ctrl+K","title":"Workflows/Find and revisit"},{"anchor":"b3","slug":"workflows-find-and-revisit","text":"1. Press Ctrl+K (Cmd on Mac) and type any words from the title or the text you remember. The switcher matches page titles and the visible text of blocks.","title":"Workflows/Find and revisit"},{"anchor":"b4","slug":"workflows-find-and-revisit","text":"2. Too many hits? Narrow with the Search syntax forms listed in the switcher footer: -draft excludes a word, OR offers alternatives, quotes pin an exact phrase, /…/ is a case-sensitive regular expression.","title":"Workflows/Find and revisit"},{"anchor":"b5","slug":"workflows-find-and-revisit","text":"3. Enter opens the highlighted result; Shift+Enter opens it in the right sidebar beside your current page; Ctrl/Cmd+Enter or a middle-click opens it in a background tab without closing the search; Alt+Enter opens it in another pane.","title":"Workflows/Find and revisit"},{"anchor":"b6","slug":"workflows-find-and-revisit","text":"4. Sure it's on the open page? Ctrl+Shift+K searches only that page's blocks, and Ctrl+F searches the open main and split panes plus the right sidebar, in pane order then sidebar order. Its slim find bar shows match counts and expands folded branches to show a match. The arrow at its left opens Replace with: Replace changes the highlighted match, Replace all every match on that page, as one Undo step. On a phone, open it from the page's ⋯ menu → Find in page.","title":"Workflows/Find and revisit"},{"anchor":"b7","slug":"workflows-find-and-revisit","text":"Select a single line of text in a block editor or rendered content, then press Ctrl/Cmd+F: Find opens with the selected text and highlights the first match. With no selection or a selection spanning lines, it keeps your previous query.","title":"Workflows/Find and revisit"},{"anchor":"b8","slug":"workflows-find-and-revisit","text":"If the switcher cannot read results, choose Retry to run the same search again without clearing what you typed.","title":"Workflows/Find and revisit"},{"anchor":"b9","slug":"workflows-find-and-revisit","text":"What you should see: Tine jumps to the page or block. Exact title matches lead the list; over time Tine may prefer a result you deliberately picked before, but only among equally strong matches — Settings → Editor → Advanced → Learn Ctrl+K choices disables that, and Reset ranking clears it.","title":"Workflows/Find and revisit"},{"anchor":"b10","slug":"workflows-find-and-revisit","text":"Follow the trail: links, tags, and references","title":"Workflows/Find and revisit"},{"anchor":"b11","slug":"workflows-find-and-revisit","text":"1. Click any [[link]] or #tag to open its page. A link to a page that does not exist yet isn't broken — opening it gives you an empty page that is saved once you type in it. Linking [[foo]] and [[Foo]] always reaches one page. While editing, Ctrl+O follows the link at the caret and Ctrl+Shift+O opens it in the right sidebar.","title":"Workflows/Find and revisit"},{"anchor":"b12","slug":"workflows-find-and-revisit","text":"2. On the page you reach, scroll to Linked References: every block that points here, grouped by source page, with a filter (the funnel button) to narrow to blocks that also mention something else. Open Unlinked References to catch plain-text mentions you never linked.","title":"Workflows/Find and revisit"},{"anchor":"b13","slug":"workflows-find-and-revisit","text":"Click an ancestor in a Linked References or Unlinked References breadcrumb to show that ancestor and its subtree inline, without leaving the page. The ancestor opens while collapsed descendants stay folded. Shift+click opens the ancestor in the right sidebar instead. This context is temporary: leaving and returning resets it. Breadcrumbs become clickable once the source page has loaded.","title":"Workflows/Find and revisit"},{"anchor":"b14","slug":"workflows-find-and-revisit","text":"3. Need several references outside Tine? Use the copy/export button on Linked References or Unlinked References. Every visible entry starts selected; uncheck a subset, then use the ordinary Text / OPML / HTML export choices. Linked References honors the text and chip filters already applied.","title":"Workflows/Find and revisit"},{"anchor":"b15","slug":"workflows-find-and-revisit","text":"4. Found a line worth quoting in your own note? Edit the note, type ((, and search the line's text to insert a block reference — a live copy that updates whenever the original changes.","title":"Workflows/Find and revisit"},{"anchor":"b16","slug":"workflows-find-and-revisit","text":"The (( picker says Searching blocks… while reading, offers Retry if the read fails, and says No matched blocks only after a successful empty search. Retry keeps your text; Escape closes the picker.","title":"Workflows/Find and revisit"},{"anchor":"b17","slug":"workflows-find-and-revisit","text":"What you should see: the reference renders as link-styled text with the source's current words, and the source block gains a small reference-count badge that lists its referrers.","title":"Workflows/Find and revisit"},{"anchor":"b18","slug":"workflows-find-and-revisit","text":"Open a note from another app","title":"Workflows/Find and revisit"},{"anchor":"b19","slug":"workflows-find-and-revisit","text":"Choose Copy link in a graph's menu, or Copy as ▸ → Copy link in Page actions or a block's context menu, then paste the tine:// address into a task manager, calendar, chat, bookmark, or another note. Copy as ▸ also offers page references, or block references and embeds. A block link uses its saved ID alone and survives moving the block to another page.","title":"Workflows/Find and revisit"},{"anchor":"b20","slug":"workflows-find-and-revisit","text":"The first copy stores a small graph ID in logseq/tine-graph-id; copying a block also saves its ordinary id:: property. Browsing and opening links never create IDs, pages, blocks, or captured content.","title":"Workflows/Find and revisit"},{"anchor":"b21","slug":"workflows-find-and-revisit","text":"Links work with Tine closed or already running. A page or block opens in a new tab of the focused pane in its graph's window. A missing graph or target shows an error. After moving or renaming a graph folder, open that folder once so Tine knows its new location. If two known folders are copies of one graph, choose which to open; Tine remembers that choice on this device.","title":"Workflows/Find and revisit"},{"anchor":"b22","slug":"workflows-find-and-revisit","text":"Keep what matters close: Favorites","title":"Workflows/Find and revisit"},{"anchor":"b23","slug":"workflows-find-and-revisit","text":"1. Favorite a page from its title: the star beside the title (or Page actions → Add to favorites). It appears under Favorites in the left sidebar and remains in Logseq's ordinary flat config.edn :favorites list.","title":"Workflows/Find and revisit"},{"anchor":"b24","slug":"workflows-find-and-revisit","text":"2. Choose + New group, type a plain-text name, and drag a favorite onto it. Drag right to nest under the preceding row, left to lift out, or vertically to reorder without changing depth. Groups and favorites can both contain children. In the left sidebar the whole row is the link, so a short name is still an easy target — a row is reordered by dragging it, and a drag only has to move a few pixels to stop counting as a click. In the right sidebar, where items are parked pages rather than a navigation list, only the title itself opens the page and the rest of the row is there to grab.","title":"Workflows/Find and revisit"},{"anchor":"b25","slug":"workflows-find-and-revisit","text":"3. Collapse any row that has children. Delete a group when you no longer need the label: what it held moves up one level and stays favorited.","title":"Workflows/Find and revisit"},{"anchor":"b26","slug":"workflows-find-and-revisit","text":"4. Prefer the keyboard? Open the arrangement page Tine created, named Favorites. A bullet that is exactly one [[page link]] is a page favorite; a ((uuid)) row is a block favorite; other bullets are labels. Editing, nesting, adding, or removing those bullets updates the sidebar after saving.","title":"Workflows/Find and revisit"},{"anchor":"b27","slug":"workflows-find-and-revisit","text":"Right-click a block and choose Favourite block to add a ((uuid)) row to Favorites. Tine saves an id:: on the source first if it needs one. The sidebar shows the block's content; clicking zooms into that block, and Shift-click opens it in the right sidebar. Block favorites stay in the ordinary Favorites page, with a derived star on references from that page; they never add favorite:: properties or block entries to config.edn :favorites. Remove its row from Favorites to stop favoriting it.","title":"Workflows/Find and revisit"},{"anchor":"b28","slug":"workflows-find-and-revisit","text":"What you should see: the richer tree follows page renames and lives in an ordinary graph page, while Logseq continues to read the same flat favorites membership. Tine does not create the arrangement page until you make a group or nest a row.","title":"Workflows/Find and revisit"},{"anchor":"b29","slug":"workflows-find-and-revisit","text":"Keep the search: make a search tab","title":"Workflows/Find and revisit"},{"anchor":"b30","slug":"workflows-find-and-revisit","text":"1. From any Ctrl+K search, press Open search tab in the footer. The whole search becomes its own tab with its own search box — nothing is written to your graph yet, and the tab comes back after a restart.","title":"Workflows/Find and revisit"},{"anchor":"b31","slug":"workflows-find-and-revisit","text":"2. Refine it there: switch Search / List / Table / Board freely — that changes only how results are shown, never which blocks matched. Open Filters / Advanced for all words, any words, an exact phrase, excluded words or a regular expression, or Edit as visual query to edit the conditions one row at a time; Explain query describes what Tine understood.","title":"Workflows/Find and revisit"},{"anchor":"b32","slug":"workflows-find-and-revisit","text":"3. A text search answers two questions at once, so the results arrive in two sections: Pages and Blocks, in that order, each with its own count and its own control — Display pages and Display. Set the pages as a table of their own properties and leave the blocks as a list if that is what you want. A section with nothing in it says so (\"No matching pages.\" / \"No matching blocks.\") and keeps its control.","title":"Workflows/Find and revisit"},{"anchor":"b33","slug":"workflows-find-and-revisit","text":"4. Pages match beside the Pages section decides which pages count as matches at all: Names and aliases (the default), Block content — a page counts when one of its own blocks matches — or Names or content. It changes page membership only; the Blocks section still lists the blocks that matched, whichever you pick.","title":"Workflows/Find and revisit"},{"anchor":"b34","slug":"workflows-find-and-revisit","text":"5. Worth keeping? Type a name into Name this search to save it as a page and press Save page.","title":"Workflows/Find and revisit"},{"anchor":"b35","slug":"workflows-find-and-revisit","text":"6. What you should see: the tab becomes an ordinary page in your graph holding one query block (with tine.* lines for the view and display choices). You can link to it, favorite it, and its results refresh themselves; an existing page with the same name or alias is never overwritten. The saved block shows one results list with a single Display control, so the two-section split stays in the search tab.","title":"Workflows/Find and revisit"},{"anchor":"b36","slug":"workflows-find-and-revisit","text":"Try it: find every mention of one page","title":"Workflows/Find and revisit"},{"anchor":"b37","slug":"workflows-find-and-revisit","text":"1. Text search finds visible words. A page query asks a different question: \"which blocks connect to Project/Roadmap?\" — written as the page's name inside a query, like this live example:","title":"Workflows/Find and revisit"},{"anchor":"b39","slug":"workflows-find-and-revisit","text":"2. What you should see in a copied Guide or the public demo: the Roadmap outline itself (a block always counts its own page, and a nested bullet counts whatever its parents mention), the bullets elsewhere in the Guide that link there — Welcome to Tine has one — and this numbered bullet, which links too. In this read-only Guide the same block runs against your own graph instead, so it lists your pages' mentions — often nothing yet; it comes alive after you copy the Guide into your graph.","title":"Workflows/Find and revisit"},{"anchor":"b40","slug":"workflows-find-and-revisit","text":"Read a query, then edit it","title":"Workflows/Find and revisit"},{"anchor":"b41","slug":"workflows-find-and-revisit","text":"To insert a query, type /query and choose Query. It opens the query sheet on its empty condition list; press + Add condition to choose the first field.","title":"Workflows/Find and revisit"},{"anchor":"b42","slug":"workflows-find-and-revisit","text":"1. At rest a query shows its title, result count and results. Click the title to rename it. Hover or focus reveals ⋯; touch screens show the menu without hover.","title":"Workflows/Find and revisit"},{"anchor":"b43","slug":"workflows-find-and-revisit","text":"2. Open ⋯ → Edit for the inline builder: Find blocks ▾ where … and one row per condition. + Add condition adds one. The real results remain below the editor as your live preview. An empty new query asks you to add a condition.","title":"Workflows/Find and revisit"},{"anchor":"b44","slug":"workflows-find-and-revisit","text":"3. Both + Add condition and a row's field ▾ open the same list, and that list is your graph: the built-in fields first, then every property key you actually use, each with the type Tine has observed. Type to narrow it. A key the list does not already show is offered by name at the bottom — Use \"…\" as a block property and, on a block query, Use \"…\" as a page property — so a key the graph does not have yet, and a key it has only on pages, both stay writable.","title":"Workflows/Find and revisit"},{"anchor":"b45","slug":"workflows-find-and-revisit","text":"4. Change blocks to pages and Tine re-reads the whole query before changing anything. If conditions stop applying — task means nothing for a page — it says how many, names them, and offers Remove them, Keep anyway, or Cancel. Kept conditions stay as red rows with their reason, so nothing disappears behind your back.","title":"Workflows/Find and revisit"},{"anchor":"b46","slug":"workflows-find-and-revisit","text":"5. Group rows when a query needs a branch. Tick the boxes of two or more rows in the same list, press Group selected ▾, and choose All of, Any of or None of: they become one group where the topmost ticked row was, and the rows you did not tick stay exactly where they were. A single row's ⋮ offers Group with row above with the same three choices. Ticking only ever selects rows of ONE list, so grouping never quietly carries a condition out of the group it was written in; a condition changes group only when you drag it there (see 7). A group's ⋮ Ungroup puts its rows back exactly as they were. Very deeply nested queries fold into one ⟨advanced⟩ row: still saved, still run, and still something you can tick, move, disable and remove. Press that row and Tine opens the query text (Edit as text at the foot of the sheet) with your cursor in it, which is where the part the rows cannot draw is edited.","title":"Workflows/Find and revisit"},{"anchor":"b47","slug":"workflows-find-and-revisit","text":"If Ungroup is absent, the group has a wrapper that cannot be removed without changing its meaning. For a none of group, choose Remove none of first; for a disabled group, switch the group on first. These are changes to which results match, so make them only when that is what you intend.","title":"Workflows/Find and revisit"},{"anchor":"b48","slug":"workflows-find-and-revisit","text":"6. Turn a condition off instead of deleting it. The enabled switch at the end of a row — and the one on a group's header — keeps the condition in the query and stops it running, so a query can be narrowed and widened without losing the words you wrote. When the group above it is off, a row says disabled by group, because switching that one row on by itself would not bring it back.","title":"Workflows/Find and revisit"},{"anchor":"b49","slug":"workflows-find-and-revisit","text":"7. Reorder with the ⋮⋮ handle by dragging; the row's ⋮ has Move up and Move down as well. Drop the handle onto another group to move the condition into it; a group left with one condition dissolves into the list around it.","title":"Workflows/Find and revisit"},{"anchor":"b50","slug":"workflows-find-and-revisit","text":"8. That list of your graph's own keys is one read Tine makes when the sheet opens. While it is still reading, the list says Reading this graph's properties… and the built-in fields below it stay usable. If that read fails instead, the list says what failed and offers Try again.","title":"Workflows/Find and revisit"},{"anchor":"b51","slug":"workflows-find-and-revisit","text":"Press Done or Escape to close the inline editor and leave the title, count and results. The block on disk is still an ordinary {{query}} bullet. ⋯ → View chooses the presentation; Copy results keeps page/date titles and hierarchy in the shared export dialog; Collapse all / Expand all is one toggle that folds List result trees through their ordinary source properties. Search opens the query in a Search tab. Edit as text is Tine's reading of the query, written in the language below, rather than a copy of the block's Logseq bytes.","title":"Workflows/Find and revisit"},{"anchor":"b52","slug":"workflows-find-and-revisit","text":"Query text (TQL)","title":"Workflows/Find and revisit"},{"anchor":"b53","slug":"workflows-find-and-revisit","text":"1. Open ⋯ → Edit as text for the query text. It is the same query the builder shows, written out and always editable. Type in it and Tine re-reads it as you go; press Save query text to make it the block's query.","title":"Workflows/Find and revisit"},{"anchor":"b54","slug":"workflows-find-and-revisit","text":"2. The language is SQLite's expression syntax over a small fixed vocabulary. A query is @block or @page — which kind of row you are asking about — and then conditions joined with and, or, not and brackets:","title":"Workflows/Find and revisit"},{"anchor":"b55","slug":"workflows-find-and-revisit","text":"@block and task = 'TODO' and [[Project/Roadmap]]","title":"Workflows/Find and revisit"},{"anchor":"b56","slug":"workflows-find-and-revisit","text":"3. The vocabulary, in full. On a block row: content, task, priority, scheduled, deadline. On a page row: name, journal, namespace. [[Page name]] and #tag are page references; prop('key') is a property; page.name reaches the block's own page. The comparisons are =, !=, <, <=, >, >=, like (with % wildcards), match (full-text), between … and …, in (…), and is null / is not null.","title":"Workflows/Find and revisit"},{"anchor":"b57","slug":"workflows-find-and-revisit","text":"@block and prop('cost') > 100 and scheduled between today and '+7d'","title":"Workflows/Find and revisit"},{"anchor":"b58","slug":"workflows-find-and-revisit","text":"4. Three forms are Tine's own. any(children, …) and every(prop('tags'), …) ask about the things a row contains — a block's children, a page's blocks, a key's values. off(…), or a line beginning -- , keeps a condition in the query without running it. And tag('x') and page_tag('x') spell out what #x means on each kind of row.","title":"Workflows/Find and revisit"},{"anchor":"b59","slug":"workflows-find-and-revisit","text":"5. Outline conditions use any, none, or every over parent (direct parent), ancestors (all parents above), children (direct children), or descendants (all blocks below, at any depth). The condition inside binds to each related block; the result is the anchor block. The anchor itself and the owning page are excluded. With no related blocks, any is false and none and every are true.","title":"Workflows/Find and revisit"},{"anchor":"b60","slug":"workflows-find-and-revisit","text":"For example, find an action mentioning a budget under a project whose branch contains an approved item:","title":"Workflows/Find and revisit"},{"anchor":"b61","slug":"workflows-find-and-revisit","text":"@block and content match 'budget -draft' and any(ancestors, content match 'project') and any(parent, any(descendants, content match 'approved'))","title":"Workflows/Find and revisit"},{"anchor":"b62","slug":"workflows-find-and-revisit","text":"content match accepts the same words, OR, exclusions, quoted phrases and /regex/ as search. Combine conditions on ancestors and descendants to search both directions. These relations belong to TQL; ordinary quick-search syntax and the result layout stay as before.","title":"Workflows/Find and revisit"},{"anchor":"b63","slug":"workflows-find-and-revisit","text":"What you should see: an unknown word is named, not swallowed. When the message comes with a place in the text, a Show me button beside it selects exactly that much of what you typed. A query with a word Tine could not read returns no results — its result area says \"Tine didn't understand part of this query, so it returned no results\" — rather than quietly running a shorter query.","title":"Workflows/Find and revisit"},{"anchor":"b64","slug":"workflows-find-and-revisit","text":"Property types","title":"Workflows/Find and revisit"},{"anchor":"b65","slug":"workflows-find-and-revisit","text":"1. A property key means more when Tine knows what its values ARE. Open a property in Edit as visual query and Tine names the type it has observed across your graph — text, number, date, checkbox, or ref (a page link) — and says list of … when the key normally holds several values at once.","title":"Workflows/Find and revisit"},{"anchor":"b66","slug":"workflows-find-and-revisit","text":"2. Observation can be wrong, and an empty key has nothing to observe. Choose declare type… on the property and pick the type yourself; tick list of when the key is meant to hold several values. The declared type is then the one Tine uses.","title":"Workflows/Find and revisit"},{"anchor":"b67","slug":"workflows-find-and-revisit","text":"3. A declaration is an ordinary page property, written as tine.type:: number on the page named after the key — and the name is the key's normalized form, so a property written due date:: declares on the page due-date. Tine writes that line for you; if you type it yourself, use that spelling or nothing binds. Choose remove declaration to delete the line and go back to what Tine observes.","title":"Workflows/Find and revisit"},{"anchor":"b68","slug":"workflows-find-and-revisit","text":"4. The type decides which comparisons you are offered: is and is not for a checkbox or a page link, before, after and between for a date, <, ≤, >, ≥ for a number, contains and starts with for text. On a list of … key the equality operator reads contains this value, because the test is against the list.","title":"Workflows/Find and revisit"},{"anchor":"b69","slug":"workflows-find-and-revisit","text":"What you should see: the property shows one type marked observed or declared and, once you declare one, a count of the blocks or pages that do not match it. That count is a to-do list, not an error: the query still runs.","title":"Workflows/Find and revisit"},{"anchor":"b70","slug":"workflows-find-and-revisit","text":"When a query needs Tine features","title":"Workflows/Find and revisit"},{"anchor":"b71","slug":"workflows-find-and-revisit","text":"1. Some queries you can build have no {{query}} spelling at all: grouping, column totals, and typed comparisons like \"cost > 100\" are Tine's, not Logseq's. When you save one, Tine changes the block's macro name from query to tine-query and moves the view choices — view, sort, group, columns, column totals, sample — into tine.* properties on the same block.","title":"Workflows/Find and revisit"},{"anchor":"b72","slug":"workflows-find-and-revisit","text":"2. Tine says so when it happens, in a notice under the query: This query now uses Tine features Logseq can't read. Take Undo that change to put the block back exactly the bytes it had, or Keep it to go on. Nothing else on the page is touched either way.","title":"Workflows/Find and revisit"},{"anchor":"b73","slug":"workflows-find-and-revisit","text":"3. Nothing is lost in Logseq. The block stays ordinary Markdown and the tine.* lines stay ordinary properties; Logseq simply shows the bullet as the plain text it is instead of running it. Everything else on the page keeps working there.","title":"Workflows/Find and revisit"},{"anchor":"b74","slug":"workflows-find-and-revisit","text":"4. Don't show this again stops the notice. That choice is kept on this device, never in the graph, so it does not follow you to another machine.","title":"Workflows/Find and revisit"},{"anchor":"b75","slug":"workflows-find-and-revisit","text":"What you should see: the block still renders and refreshes in Tine as it did a moment ago; only its first line and its properties changed. Undo is the ordinary undo, so Ctrl+Z does the same thing as the button for as long as it is the newest change.","title":"Workflows/Find and revisit"},{"anchor":"b76","slug":"workflows-find-and-revisit","text":"Advanced queries","title":"Workflows/Find and revisit"},{"anchor":"b77","slug":"workflows-find-and-revisit","text":"A hand-written advanced query stays editable as text. A {{query {:query …}}} or #+BEGIN_QUERY block runs only when Tine can read every clause of it; otherwise it is refused whole (\"Advanced (datalog) query not run\") and the notice names the clauses Tine could not run, rather than show a wider answer than you asked for.","title":"Workflows/Find and revisit"},{"anchor":"b78","slug":"workflows-find-and-revisit","text":"Tine runs Logseq's query rules (task, priority, property, page-ref, between and the others) and the attribute patterns written on the block the query returns: its marker, priority, scheduled and deadline dates, and whether its page is a journal and which day, alone or narrowed by contains?, =, not=, <, <=, > or >=, and inside not. For example [:find (pull ?b [*]) :where [?b :block/marker ?m] [(contains? #{\"NOW\" \"DOING\"} ?m)]] lists what you are working on now.","title":"Workflows/Find and revisit"},{"anchor":"b79","slug":"workflows-find-and-revisit","text":"A part Tine does not understand refuses the whole query: it never runs half of it, because a partial answer could both add and hide blocks. A :result-transform function (other than Logseq's default priority sort), authored rules or an unsupported input is such a part. Common page/tag string inputs and numeric or relative date windows run; Reference/Tine query model lists the supported shapes.","title":"Workflows/Find and revisit"},{"anchor":"b80","slug":"workflows-find-and-revisit","text":"Where next","title":"Workflows/Find and revisit"},{"anchor":"b81","slug":"workflows-find-and-revisit","text":"The exact rules — ranking, search scope, saved-page behavior — are mapped in Reference/Pages, links, references, and search. For turning found or structured blocks into tables and boards, see Workflows/Structure repeated information; the wider shortcut map is Features/Tips & shortcuts.","title":"Workflows/Find and revisit"},{"anchor":"b0","slug":"workflows-keep-context-visible","text":"Keep context visible","title":"Workflows/Keep context visible"},{"anchor":"b1","slug":"workflows-keep-context-visible","text":"Source beside draft, note beside plan: this tour builds a working layout step by step — park a page in the right sidebar, collect places in tabs, split the window for true side-by-side, give a page its own window, and save the arrangement as a workspace. Each part ends with what you should see. The shortcut map is Features/Tips & shortcuts.","title":"Workflows/Keep context visible"},{"anchor":"b2","slug":"workflows-keep-context-visible","text":"Keep your place in a long outline","title":"Workflows/Keep context visible"},{"anchor":"b3","slug":"workflows-keep-context-visible","text":"Scroll down a nested outline: ancestors that leave the screen stay pinned at the top, through the root. Click a pinned ancestor to scroll back to its block. This works in pages, journals, panes, and right-sidebar outlines.","title":"Workflows/Keep context visible"},{"anchor":"b4","slug":"workflows-keep-context-visible","text":"Settings → Appearance → Sticky parent bullets turns this on or off on desktop and mobile. It starts on and is remembered on this device.","title":"Workflows/Keep context visible"},{"anchor":"b5","slug":"workflows-keep-context-visible","text":"Select the block containing an embed","title":"Workflows/Keep context visible"},{"anchor":"b6","slug":"workflows-keep-context-visible","text":"While editing an embedded source block, run Select embedding block from the command palette (Ctrl+Shift+P). It leaves the editor and selects the block containing the {{embed ...}} macro. Use the ordinary move, indent, outdent, or edit shortcuts on that selection.","title":"Workflows/Keep context visible"},{"anchor":"b7","slug":"workflows-keep-context-visible","text":"The command starts without a key: assign one in Settings → Keyboard shortcuts to leave an embed directly from the keyboard. It works for block and page embeds. Move Block Up/Down while still editing the embedded source keeps moving that source; the Moved in <page> notice still tells you where an unseen move went.","title":"Workflows/Keep context visible"},{"anchor":"b8","slug":"workflows-keep-context-visible","text":"Park a source in the right sidebar","title":"Workflows/Keep context visible"},{"anchor":"b9","slug":"workflows-keep-context-visible","text":"1. On the page you're writing, Shift-click a link (or a bullet's dot) to open it in the right sidebar. It's a full editor, not a preview — you can write in either place.","title":"Workflows/Keep context visible"},{"anchor":"b10","slug":"workflows-keep-context-visible","text":"2. Two more ways to park things: in Ctrl+K, press Shift+Enter on any page or block result; while editing, Ctrl+Shift+O sends the link at the caret across.","title":"Workflows/Keep context visible"},{"anchor":"b11","slug":"workflows-keep-context-visible","text":"3. Crowded? Fold an item with its arrow and keep just its title in reach; its ✕ closes it. The item's ⋯ menu offers Close others, Collapse others, and, for a page, Open as page to move it into the main pane. The sidebar header's ⋯ menu offers Collapse all, Expand all, and Close all. Drag the sidebar's left edge to resize it — up to 70% of the window, always leaving the page beside it room to work. Folding or closing never strands half-typed text — Tine commits the active edit first.","title":"Workflows/Keep context visible"},{"anchor":"b12","slug":"workflows-keep-context-visible","text":"4. Press t r to hide the whole sidebar and t r again to bring it back just as it was; its items are restored with your session.","title":"Workflows/Keep context visible"},{"anchor":"b13","slug":"workflows-keep-context-visible","text":"What you should see: the source parked beside your page, both editable — and it stays parked while the main page navigates elsewhere.","title":"Workflows/Keep context visible"},{"anchor":"b14","slug":"workflows-keep-context-visible","text":"Gather places in tabs, and pin the ones you live in","title":"Workflows/Keep context visible"},{"anchor":"b15","slug":"workflows-keep-context-visible","text":"1. Middle-click a link, a search hit, or a bullet's dot to open it in a background tab — you never leave the page you're on. In Ctrl+K, Ctrl/Cmd+Enter (or Ctrl/Cmd-click) does the same for the highlighted result and leaves the search open, so you can fan several out in a row.","title":"Workflows/Keep context visible"},{"anchor":"b16","slug":"workflows-keep-context-visible","text":"2. Navigating to a page that's already open just focuses its tab instead of making a duplicate (Settings → Editor → Advanced → Switch to an already-open tab when navigating turns that off).","title":"Workflows/Keep context visible"},{"anchor":"b17","slug":"workflows-keep-context-visible","text":"3. Double-click a tab to pin it. Pinned tabs gather at the left and hold their content: ordinary navigation from one opens a fresh tab instead, and closing a pinned tab asks first — an accidental Ctrl+W can't eat it.","title":"Workflows/Keep context visible"},{"anchor":"b18","slug":"workflows-keep-context-visible","text":"4. Closed one too soon? Ctrl+Shift+T reopens the last closed tab with its history. Ctrl+PageDown and Ctrl+PageUp step to the next and previous tab. Tabs stretch to fill the strip and share it evenly as more open; a tab zoomed into a block is named for that block, so two tabs of one page stay apart. When titles stop fitting, the Show all tabs button at the strip's edge lists them in full — activate, pin, close, or reorder there.","title":"Workflows/Keep context visible"},{"anchor":"b19","slug":"workflows-keep-context-visible","text":"What you should see: the same tabs, pins included, come back after a restart — and as session state kept in Tine's own app data, none of this ever adds a file to your graph.","title":"Workflows/Keep context visible"},{"anchor":"b20","slug":"workflows-keep-context-visible","text":"Split the window for true side-by-side","title":"Workflows/Keep context visible"},{"anchor":"b21","slug":"workflows-keep-context-visible","text":"1. Desktop only: Ctrl/Cmd-click any [[link]], tag, or block reference to open it in another pane — with a single pane, Tine splits right for it. In Ctrl+K, Alt+click or Alt+Enter does the same for the highlighted result. The direct bindings: Ctrl+Alt+\\ splits right with a copy of the current tab, Ctrl+Alt+Shift+\\ splits down.","title":"Workflows/Keep context visible"},{"anchor":"b22","slug":"workflows-keep-context-visible","text":"2. Each pane keeps its own tab strip and its own back/forward history — Alt+Left and Alt+Right step through it, even mid-edit.","title":"Workflows/Keep context visible"},{"anchor":"b23","slug":"workflows-keep-context-visible","text":"3. Drag the seam between panes to resize them. Drag a tab anywhere onto another pane's tab bar to put it last there (or next to a tab to put it in that spot), onto a pane's body to append it, or onto a seam or pane edge to split that spot and drop the tab into the new pane — Esc cancels a drag mid-way. The command palette (Ctrl+Shift+P) also has Toggle maximize active pane (Ctrl+Alt+M) and commands to grow or shrink the active pane.","title":"Workflows/Keep context visible"},{"anchor":"b24","slug":"workflows-keep-context-visible","text":"To split above a pane, drag just below its tab strip. All four edge drop zones grow with the pane; at a corner the nearest edge wins. The preview shows where the new pane will open. The centre appends the tab to the pane, and the tab strip keeps its reorder behavior.","title":"Workflows/Keep context visible"},{"anchor":"b25","slug":"workflows-keep-context-visible","text":"4. PDF readers use the same tabs and panes. Opening a PDF link makes a companion pane while preserving the source page; you can then drag the PDF tab into any pane or quadrant. Notes opens the PDF's notes page in its structural companion pane, and that notes tab can be moved in exactly the same way.","title":"Workflows/Keep context visible"},{"anchor":"b26","slug":"workflows-keep-context-visible","text":"5. From the keyboard, Ctrl+1 … Ctrl+9 focus panes in reading order, Ctrl+Alt+←↑↓→ moves focus to the nearest pane in that direction, and Ctrl+Alt+Shift+←↑↓→ moves the active tab there instead.","title":"Workflows/Keep context visible"},{"anchor":"b27","slug":"workflows-keep-context-visible","text":"6. Prefer staged control? Esc climbs from editing to block selection into pane-select mode — a hint pill at the bottom tells you when it's on (the command palette's Pane select mode enters it directly). Arrows step between panes, seams, and window edges; Enter on a seam makes a mirror split; typing opens the new pane with the search box pre-filled. Another Esc backs out.","title":"Workflows/Keep context visible"},{"anchor":"b28","slug":"workflows-keep-context-visible","text":"What you should see: two note panes that scroll, navigate, and keep tabs independently — source and draft side by side, never fighting over one cursor.","title":"Workflows/Keep context visible"},{"anchor":"b29","slug":"workflows-keep-context-visible","text":"Open a page in its own window","title":"Workflows/Keep context visible"},{"anchor":"b30","slug":"workflows-keep-context-visible","text":"1. Desktop only: right-click a page link or a page in the left sidebar and choose Open in new window — the page title's ⋯ menu has it too, and so does the command palette (Ctrl+Shift+P) as Open current page in new window. The page opens in a separate OS window you can move to another monitor.","title":"Workflows/Keep context visible"},{"anchor":"b31","slug":"workflows-keep-context-visible","text":"2. The window is a full workspace of its own: its own tabs, splits, and back/forward history. Links, Ctrl+K, and search results you use there open there. It has no left or right sidebar.","title":"Workflows/Keep context visible"},{"anchor":"b32","slug":"workflows-keep-context-visible","text":"3. Edits made in the window save exactly like edits in the main window, show up in the main window as you type, and Ctrl+Z undoes them from either place. Up to 8 windows can be open at once.","title":"Workflows/Keep context visible"},{"anchor":"b33","slug":"workflows-keep-context-visible","text":"4. Close it with its own title-bar button whenever you like — text you just typed is kept. Quitting Tine closes every window; the ones that were open come back, with their tabs, the next time you start Tine. Switching to another graph closes them.","title":"Workflows/Keep context visible"},{"anchor":"b34","slug":"workflows-keep-context-visible","text":"What you should see: the same page in two windows on two screens, edited in either, with every change in the one file on disk.","title":"Workflows/Keep context visible"},{"anchor":"b35","slug":"workflows-keep-context-visible","text":"Save the arrangement as a workspace","title":"Workflows/Keep context visible"},{"anchor":"b36","slug":"workflows-keep-context-visible","text":"1. With the layout where you want it — splits, every pane's tabs and histories, both sidebars — click the workspace name at the top of the left sidebar and choose + New workspace, or run New workspace… from the command palette (Mod+Shift+P); name it once.","title":"Workflows/Keep context visible"},{"anchor":"b37","slug":"workflows-keep-context-visible","text":"2. Come back to it from the same switcher: hover the name for a quick-switch list, or click it for the full menu with Rename and Delete. Each graph keeps its own set, and the active one comes back after a restart.","title":"Workflows/Keep context visible"},{"anchor":"b38","slug":"workflows-keep-context-visible","text":"What you should see: the saved pane layout, tabs and histories, sidebars, and Recent return together. Workspaces are device-local session state — saving, switching, or deleting one never writes to your graph.","title":"Workflows/Keep context visible"},{"anchor":"b39","slug":"workflows-keep-context-visible","text":"Clear everything else away","title":"Workflows/Keep context visible"},{"anchor":"b40","slug":"workflows-keep-context-visible","text":"t f (focus mode) hides the sidebars and toolbar so the screen is just text — on desktop it also takes the window full screen. Hover the top edge to reach the toolbar again; layered Esc steps back out.","title":"Workflows/Keep context visible"},{"anchor":"b41","slug":"workflows-keep-context-visible","text":"t b fades every block except the one you're editing. Settings → Appearance → Dim in focus mode turns that dimming on for you whenever focus mode is on.","title":"Workflows/Keep context visible"},{"anchor":"b42","slug":"workflows-keep-context-visible","text":"t w drops the reading-width cap for a wide page; Settings → Appearance → Advanced lets you set your own Standard page width and Wide page width.","title":"Workflows/Keep context visible"},{"anchor":"b43","slug":"workflows-keep-context-visible","text":"On a phone the layout stays one page: the sidebars open as overlays (dismiss with the shaded edge, Esc, or Android Back), and tabs and splits are off. A PDF and its Notes page use that same history, so Back returns to the previous surface.","title":"Workflows/Keep context visible"},{"anchor":"b44","slug":"workflows-keep-context-visible","text":"Where next","title":"Workflows/Keep context visible"},{"anchor":"b45","slug":"workflows-keep-context-visible","text":"Features/Tips & shortcuts has the compact shortcut map, Start/Where things are is the plain map of the places used here, and Workflows/Find and revisit covers getting back to anything you parked.","title":"Workflows/Keep context visible"},{"anchor":"b0","slug":"workflows-research-a-document","text":"Research a document","title":"Workflows/Research a document"},{"anchor":"b1","slug":"workflows-research-a-document","text":"The short path: drop a PDF onto a page, read it in a companion pane, and highlight as you go. Each highlight becomes an ordinary bullet you can write under, quote anywhere, and follow back to the exact spot — so a paper turns into linked, searchable notes without leaving Tine. The precise highlight rules live in Features/PDF annotation.","title":"Workflows/Research a document"},{"anchor":"b2","slug":"workflows-research-a-document","text":"Bring the document in","title":"Workflows/Research a document"},{"anchor":"b3","slug":"workflows-research-a-document","text":"To keep a PDF outside your graph, use a file:// link. On desktop it opens in your operating system's default PDF viewer, without copying the file into assets or creating annotation files in your graph. Upload it as an asset when you want to annotate it in Tine.","title":"Workflows/Research a document"},{"anchor":"b4","slug":"workflows-research-a-document","text":"1. Drag a PDF from your file manager onto any page and drop it on a block — or paste one you copied, or run the /Upload an asset slash command. Tine stores the file in your graph's assets/ folder and inserts a link where you dropped it.","title":"Workflows/Research a document"},{"anchor":"b5","slug":"workflows-research-a-document","text":"2. Click the inserted link. On desktop the document opens as a normal tab in a companion pane beside your notes; drag its tab into another pane or split to move it. On a phone it opens in the current one-pane history, and Back returns to the source page.","title":"Workflows/Research a document"},{"anchor":"b6","slug":"workflows-research-a-document","text":"What you should see: the PDF in an ordinary pane, with a toolbar holding a page-number box, a find button (Ctrl+F searches inside the document), zoom controls, an Area highlight toggle, a Notes button, Outline, a ⋯ menu, and the close control at the far edge. In a narrow pane the Area highlight, Notes and Outline buttons move into the ⋯ menu.","title":"Workflows/Research a document"},{"anchor":"b7","slug":"workflows-research-a-document","text":"Read and highlight","title":"Workflows/Research a document"},{"anchor":"b8","slug":"workflows-research-a-document","text":"1. Select a passage with the mouse and pick a color in the menu that appears — that's a highlight. Click an existing highlight to reopen its menu: recolor it, or remove it with ✕.","title":"Workflows/Research a document"},{"anchor":"b9","slug":"workflows-research-a-document","text":"2. To clip a figure or table instead, toggle Area highlight in the toolbar (or hold Shift on Linux/Windows, Command on macOS) and drag a rectangle over the region, then choose its color. Dismiss the color menu and nothing is written.","title":"Workflows/Research a document"},{"anchor":"b10","slug":"workflows-research-a-document","text":"3. Long document? Outline navigates its table of contents, the page-number box jumps straight to a page, and the ⋯ menu offers Fit width, Fit height and a Light, Warm, or Dark reader theme — remembered on this device, not written into your graph.","title":"Workflows/Research a document"},{"anchor":"b11","slug":"workflows-research-a-document","text":"What you should see: colored marks on the document — and, behind each mark, a bullet on a notes page named after the PDF.","title":"Workflows/Research a document"},{"anchor":"b12","slug":"workflows-research-a-document","text":"Turn highlights into notes","title":"Workflows/Research a document"},{"anchor":"b13","slug":"workflows-research-a-document","text":"1. Press Notes in the reader toolbar. On desktop Tine opens the document's highlights page in a companion pane next to the PDF; move its tab if another pane is more useful. On a phone it opens in the same history, so Back returns to the PDF. The page name starts with hls__, like Logseq, and every highlight is a bullet marked with a colored dot.","title":"Workflows/Research a document"},{"anchor":"b14","slug":"workflows-research-a-document","text":"2. Write under a highlight bullet: a summary, a question, your own structure. These are ordinary bullets on an ordinary graph page — edit, nest, tag, and search them like any others.","title":"Workflows/Research a document"},{"anchor":"b15","slug":"workflows-research-a-document","text":"3. Click the colored dot on a highlight bullet (or the highlight itself back in the PDF) to jump between the two: each note goes straight back to its spot in the document.","title":"Workflows/Research a document"},{"anchor":"b16","slug":"workflows-research-a-document","text":"What you should see: your notes and their source passages stay connected in both directions, and recoloring a highlight updates its dot on the notes page to match.","title":"Workflows/Research a document"},{"anchor":"b17","slug":"workflows-research-a-document","text":"Quote a passage in your ordinary notes","title":"Workflows/Research a document"},{"anchor":"b18","slug":"workflows-research-a-document","text":"1. Click the highlight and choose Copy ref, then paste into any bullet in your own notes. The pasted ((…)) renders as link-styled text quoting the highlighted passage, and clicking the quote opens the document at that page.","title":"Workflows/Research a document"},{"anchor":"b19","slug":"workflows-research-a-document","text":"2. Keep source and words visible while you write: the PDF is a normal tab, so it can sit in any resizable pane or quadrant next to your notes page; Shift-click on any bullet's dot parks that note in the right sidebar. On a phone the reader instead fills the width of the screen and the sidebars open as overlays — the two-up layout is a wider-window pattern.","title":"Workflows/Research a document"},{"anchor":"b20","slug":"workflows-research-a-document","text":"3. Choose Linked references on the highlight's menu to list every note that quotes it — the trail from one passage to everywhere you used it.","title":"Workflows/Research a document"},{"anchor":"b21","slug":"workflows-research-a-document","text":"What you should see: your note cites the source live, not as a copied excerpt — touch nothing, and the quote still opens the PDF at the right page tomorrow.","title":"Workflows/Research a document"},{"anchor":"b22","slug":"workflows-research-a-document","text":"Share the result","title":"Workflows/Research a document"},{"anchor":"b23","slug":"workflows-research-a-document","text":"1. From the notes page title's right-click menu: Copy / export as… offers Markdown and rendered copies, and Export to PDF… (desktop only) opens print options and then your OS print dialog — choose Save as PDF. The page always prints on a light background, whatever your theme.","title":"Workflows/Research a document"},{"anchor":"b24","slug":"workflows-research-a-document","text":"2. Publishing on the web? Pages marked public:: true go into the static export: Settings → Graph → Export HTML and read-only app… asks for a folder outside your graph. To share just one reading list or project, press Export… on a query: you review the pages its results live on, and Tine writes a standalone site in published-queries/<folder>/ inside the graph. A colliding folder offers Replace (with the previous export kept in recovery) or a separate export, and copied local assets travel with the folder. A query about blocks exports whole pages, not just the matched blocks, and the dialog asks you to confirm that. Nothing is uploaded.","title":"Workflows/Research a document"},{"anchor":"b25","slug":"workflows-research-a-document","text":"Your annotations are stored Logseq-compatibly — the hls__ page with your notes, an .edn sidecar and any clipped area images under assets/ — so launch snapshots cover your notes, config, and PDF highlight sidecars (not the PDF or other media files), and another Logseq-compatible tool reads the same annotations.","title":"Workflows/Research a document"},{"anchor":"b26","slug":"workflows-research-a-document","text":"Where next","title":"Workflows/Research a document"},{"anchor":"b27","slug":"workflows-research-a-document","text":"The exact highlight, merge, and storage rules are mapped in Features/PDF annotation. For quoting anything else with ((…)) and the reference panels, see Workflows/Find and revisit; for snapshots and backups, Reference/Files, external edits, and backups.","title":"Workflows/Research a document"},{"anchor":"b0","slug":"workflows-structure-repeated-information","text":"Structure repeated information","title":"Workflows/Structure repeated information"},{"anchor":"b1","slug":"workflows-structure-repeated-information","text":"Start with the bullets you already write. Add a few fields when they become useful, then choose a table or board to see the same blocks from a different angle.","title":"Workflows/Structure repeated information"},{"anchor":"b2","slug":"workflows-structure-repeated-information","text":"A small project tracker","title":"Workflows/Structure repeated information"},{"anchor":"b3","slug":"workflows-structure-repeated-information","text":"Refresh the Guide examples","title":"Workflows/Structure repeated information"},{"anchor":"b4","slug":"workflows-structure-repeated-information","text":"Decide the next topic","title":"Workflows/Structure repeated information"},{"anchor":"b5","slug":"workflows-structure-repeated-information","text":"Publish the updated demo","title":"Workflows/Structure repeated information"},{"anchor":"b6","slug":"workflows-structure-repeated-information","text":"Turn child bullets into a view","title":"Workflows/Structure repeated information"},{"anchor":"b7","slug":"workflows-structure-repeated-information","text":"1. Make a parent bullet like the tracker above, then add ordinary child bullets for each item.","title":"Workflows/Structure repeated information"},{"anchor":"b8","slug":"workflows-structure-repeated-information","text":"2. Right-click the parent and choose Show children as → Table (or type /Table). Use + Add column to add fields such as Status, Owner, and Estimate; edit their values in the cells.","title":"Workflows/Structure repeated information"},{"anchor":"b9","slug":"workflows-structure-repeated-information","text":"3. When progress matters more than rows, type /Board on that parent. Choose Group by and select Status to make one column per status.","title":"Workflows/Structure repeated information"},{"anchor":"b10","slug":"workflows-structure-repeated-information","text":"4. What you should see: the same child bullets appear as editable table rows or status columns. Move a board card to change that block's grouping field; return to the outline and the change is there too.","title":"Workflows/Structure repeated information"},{"anchor":"b11","slug":"workflows-structure-repeated-information","text":"Find and reuse the same kind of block","title":"Workflows/Structure repeated information"},{"anchor":"b12","slug":"workflows-structure-repeated-information","text":"1. Press Ctrl+K, then search for Refresh Guide examples. The friendly search surface finds that tracker block without needing a query expression.","title":"Workflows/Structure repeated information"},{"anchor":"b13","slug":"workflows-structure-repeated-information","text":"2. Choose Open search tab. There, choose Filters / Advanced, then Edit as visual query. The query reads as one sentence — Blocks where … — over a sheet of conditions; use + Add condition → Property to choose Owner and the value Avery.","title":"Workflows/Structure repeated information"},{"anchor":"b14","slug":"workflows-structure-repeated-information","text":"3. Choose Table or Board in the view switcher (Search, List, Table, Board) above the results. The selection answers which blocks to show; the view answers how to show them, so you can change the presentation without remaking the selection.","title":"Workflows/Structure repeated information"},{"anchor":"b15","slug":"workflows-structure-repeated-information","text":"4. Open Display beside the conditions to set the rest of the presentation in one place: the view, what the results are grouped by, the sort order, which columns show, what the footer summarizes, and a sample size that limits the rows. Sorts, columns, and summaries are ordered lists you can add to, reorder with the arrows, and remove from.","title":"Workflows/Structure repeated information"},{"anchor":"b16","slug":"workflows-structure-repeated-information","text":"5. What you should see: a reusable selection of matching tracker blocks, first as search results and then as the table or board you chose.","title":"Workflows/Structure repeated information"},{"anchor":"b17","slug":"workflows-structure-repeated-information","text":"Query-backed board of the same tracker","title":"Workflows/Structure repeated information"},{"anchor":"b19","slug":"workflows-structure-repeated-information","text":"This board finds the matching tracker bullets above; it does not copy them. Inspect it here, in a copied Guide, or in the public demo, then change its view with the visual controls.","title":"Workflows/Structure repeated information"},{"anchor":"b20","slug":"workflows-structure-repeated-information","text":"What is stored, only when you need to inspect it","title":"Workflows/Structure repeated information"},{"anchor":"b21","slug":"workflows-structure-repeated-information","text":"The view-owning parent carries tine.view:: table or tine.view:: board; the optional tine.fields:: line declares the columns and their types. The child bullets remain the source blocks with their ordinary properties.","title":"Workflows/Structure repeated information"},{"anchor":"b22","slug":"workflows-structure-repeated-information","text":"The query-backed example stores {{query (property owner Avery)}} to choose its blocks, while its tine.view:: board and tine.group-field:: prop:status lines choose the presentation. A query groups by a field name — prop:status for the property named Status, or state, priority, tags, page — so the same word cannot mean two things on two different views. An older graph that says tine.group-by:: status keeps working and is rewritten the first time you change the grouping from Display. The visual builder and friendly search lead here without requiring you to type the query syntax.","title":"Workflows/Structure repeated information"},{"anchor":"b23","slug":"workflows-structure-repeated-information","text":"Optional: add a derived field","title":"Workflows/Structure repeated information"},{"anchor":"b24","slug":"workflows-structure-repeated-information","text":"If Estimate needs a computed companion, add a formula from the table header. For the visual formula editor, its read-only results, and the raw-expression escape hatch, use Features/Formulas. For table, board, and query-view details, return to Features/Sheets.","title":"Workflows/Structure repeated information"}];
